let webpush = null; // Loaded lazily so a missing optional push dependency never blocks chat.

// Chat media uses direct browser-to-R2 multipart uploads when these variables
// are configured. MongoDB/GridFS remains available for existing files and as a
// compatibility path for deployments that have not added R2 yet.
const objectStorage = createObjectStorage();

const io = new Server(server, {
  // Chat media is uploaded through /api/upload. Keep Socket.IO payloads small so
  // a legacy/base64 event cannot consume hundreds of MB of RAM.
  maxHttpBufferSize: 2 * 1024 * 1024 // 2MB: more than enough for chat + WebRTC signaling
});

// =========================================================
// 1. Persistence: MongoDB Atlas + local JSON development fallback
// =========================================================
const DB_PATH = path.join(__dirname, "chat_database.json");
const MONGODB_URI = String(process.env.MONGODB_URI || "").trim();
const CLOUD_DATABASE_ENABLED = Boolean(MONGODB_URI);
// A JSON backup is useful in local development, but serializing the complete
// state synchronously on every message is unnecessary (and expensive) when
// MongoDB is the configured source of truth. An explicit environment value
// still wins for operators who want a backup in the cloud.
const configuredLocalBackup = process.env.WRITE_LOCAL_JSON_BACKUP;
const WRITE_LOCAL_JSON_BACKUP = String(
  configuredLocalBackup == null
    ? (CLOUD_DATABASE_ENABLED ? "false" : "true")
    : configuredLocalBackup
).toLowerCase() !== "false";

// Cloudflare Realtime TURN. Keep the long-lived TURN key token on the server.
// Browsers receive only short-lived credentials generated by Cloudflare.
const CLOUDFLARE_TURN_KEY_ID = String(
  process.env.CLOUDFLARE_TURN_KEY_ID || process.env.CF_TURN_KEY_ID || ""
).trim();
const CLOUDFLARE_TURN_API_TOKEN = String(
  process.env.CLOUDFLARE_TURN_API_TOKEN || process.env.CF_TURN_API_TOKEN || ""
).trim();
const CLOUDFLARE_TURN_CONFIGURED = Boolean(
  CLOUDFLARE_TURN_KEY_ID && CLOUDFLARE_TURN_API_TOKEN
);
const CLOUDFLARE_TURN_TTL_SECONDS = Math.min(
  86400,
  Math.max(900, Number(process.env.CLOUDFLARE_TURN_TTL_SECONDS || 86400) || 86400)
);
const cloudflareTurnCredentialCache = new Map();

let mongoReady = false;
let mongoSaveTimer = null;
let mongoSaveRunning = false;
let mongoSaveDirty = false;
let ChatifyState = null;
let gridFsBucket = null;
let analyticsService = null;
let aiService = null;
const MONGO_SAVE_DEBOUNCE_MS = Math.max(750, Number(process.env.MONGO_SAVE_DEBOUNCE_MS || 1500) || 1500);

function emptyDatabase() {
  return {
    roomHistory: {},
    users: {},
    friends: {},
    friendRequests: {},
    privateChats: {},
    rooms: {},
    roomBans: {},
    publicRooms: {},
    platformBans: {},
    reports: {},
    uploads: {},
    sessions: {},
    frames: {},
    telegramTopics: {},
    notificationPreferences: {},
    pushSubscriptions: {},
    pushConfig: {},
    voiceRooms: {},
    voiceRoomBans: {},
    voiceRoomInvites: {},
    aiPreferences: {},
    aiModerationAlerts: {}
  };
}

function normalizeDatabaseState(source) {
  const state = source && typeof source === "object" ? source : {};
  const defaults = emptyDatabase();
  for (const [key, value] of Object.entries(defaults)) {
    if (!state[key] || typeof state[key] !== "object") {
      state[key] = value;
    }
  }
  return state;
}

function loadDB() {
  try {
    if (fs.existsSync(DB_PATH)) {
      return normalizeDatabaseState(JSON.parse(fs.readFileSync(DB_PATH, "utf8")));
    }
  } catch (e) {
    console.error("Error loading local DB:", e.message);
  }
  return emptyDatabase();
}

let db = loadDB();

// =========================================================
// Stability guard: keep chat state bounded on small Render instances.
// Only the newest messages are retained per conversation. Older chat media is
// deleted from GridFS/local storage once no retained message references it.
// This intentionally does NOT delete avatars, frames, reports or voice-room art.
// =========================================================
const CHAT_HISTORY_LIMIT = Math.min(500, Math.max(10, Number(process.env.CHAT_HISTORY_LIMIT || 50) || 50));
const UNSENT_CHAT_UPLOAD_TTL_MS = Math.max(
  60 * 60 * 1000,
  Number(process.env.UNSENT_CHAT_UPLOAD_TTL_MS || 6 * 60 * 60 * 1000) || 6 * 60 * 60 * 1000
);
const MEMORY_WARN_MB = Math.max(220, Number(process.env.MEMORY_WARN_MB || 300) || 300);
const MEMORY_CLEANUP_MB = Math.max(MEMORY_WARN_MB + 20, Number(process.env.MEMORY_CLEANUP_MB || 340) || 340);
const MEMORY_CRITICAL_MB = Math.max(MEMORY_CLEANUP_MB + 40, Number(process.env.MEMORY_CRITICAL_MB || 440) || 440);
const MEMORY_GUARD_INTERVAL_MS = Math.max(15_000, Number(process.env.MEMORY_GUARD_INTERVAL_MS || 30_000) || 30_000);
const MEMORY_CRITICAL_STRIKES = Math.max(2, Number(process.env.MEMORY_CRITICAL_STRIKES || 3) || 3);
// RSS also includes native allocations and allocator pages that may remain
// resident after a stream finishes. Do not terminate a healthy Node process
// merely because RSS is high while V8/external buffers are low. Operators can
// opt into the old controlled-restart behavior after setting the thresholds
// for their actual Render plan.
const MEMORY_GUARD_RESTART = String(process.env.MEMORY_GUARD_RESTART || "false").toLowerCase() === "true";
const MEMORY_RESTART_HEAP_MB = Math.max(128, Number(process.env.MEMORY_RESTART_HEAP_MB || 240) || 240);
const MEMORY_RESTART_EXTERNAL_MB = Math.max(64, Number(process.env.MEMORY_RESTART_EXTERNAL_MB || 192) || 192);
let memoryGuardStatus = "normal";
let memoryCriticalStrikes = 0;
let memoryRestartRequested = false;
let memoryRestartSkipLogged = false;
let uploadDeletionChain = Promise.resolve();

async function persistMongoStateNow() {
  if (!mongoReady || !ChatifyState) return;
  if (mongoSaveRunning) {
    mongoSaveDirty = true;
    return;
  }

  mongoSaveRunning = true;
  mongoSaveDirty = false;
  try {
    // IMPORTANT: do not JSON.stringify/parse the whole database here. The old
    // implementation created a complete second copy of every message on every
    // save and could queue several snapshots while MongoDB was busy. On a 512MB
    // Render instance that can trigger an OOM restart. Mongoose/BSON will serialize
    // the object for the write; only one write is allowed in flight at a time.
    await ChatifyState.findOneAndUpdate(
      { key: "main" },
      { $set: { state: db, updatedAt: new Date() } },
      { upsert: true, setDefaultsOnInsert: true }
    ).exec();
  } catch (err) {
    console.error("MongoDB save failed:", err.message);
  } finally {
    mongoSaveRunning = false;
    if (mongoSaveDirty) {
      clearTimeout(mongoSaveTimer);
      mongoSaveTimer = setTimeout(() => {
        mongoSaveTimer = null;
        persistMongoStateNow().catch(() => {});
      }, MONGO_SAVE_DEBOUNCE_MS);
      mongoSaveTimer.unref?.();
    }
  }
}

function scheduleMongoSave() {
  if (!mongoReady || !ChatifyState) return;
  mongoSaveDirty = true;
  if (mongoSaveRunning) return;
  clearTimeout(mongoSaveTimer);
  mongoSaveTimer = setTimeout(() => {
    mongoSaveTimer = null;
    persistMongoStateNow().catch(() => {});
  }, MONGO_SAVE_DEBOUNCE_MS);
  mongoSaveTimer.unref?.();
}

function saveDB(data) {
  if (WRITE_LOCAL_JSON_BACKUP) {
    try {
      fs.writeFileSync(DB_PATH, JSON.stringify(data, null, 2), "utf8");
    } catch (e) {
      console.error("Error saving local DB backup:", e.message);
    }
  }
  scheduleMongoSave();
}

function messageFileIds(message) {
  const ids = [];
  if (message && typeof message === "object" && message.fileId) ids.push(String(message.fileId));
  return ids;
}

function isChatUploadReferenced(fileId) {
  if (!fileId) return false;
  for (const history of Object.values(db.roomHistory || {})) {
    if (!Array.isArray(history)) continue;
    if (history.some(message => String(message?.fileId || "") === fileId)) return true;
  }
  return false;
}

function queuePhysicalUploadDelete(record) {
  if (!record) return;
  uploadDeletionChain = uploadDeletionChain
    .catch(() => {})
    .then(async () => {
      try {
        // The local cache is only a short-lived acceleration layer for recently
        // uploaded media. Always remove it together with the canonical upload.
        if (record.cacheStoredName) {
          await fs.promises.unlink(path.join(UPLOAD_DIR, record.cacheStoredName)).catch(() => {});
        }
        if (record.playbackCacheStoredName) {
          await fs.promises.unlink(path.join(UPLOAD_DIR, record.playbackCacheStoredName)).catch(() => {});
        }
        if (record.storage === "r2" && record.r2Key) {
          await objectStorage.deleteObject({ key: record.r2Key });
        } else if (record.storage === "gridfs" && record.gridFsId && gridFsBucket) {
          await gridFsBucket.delete(new mongoose.Types.ObjectId(record.gridFsId));
        } else if (record.storedName) {
          await fs.promises.unlink(path.join(UPLOAD_DIR, record.storedName)).catch(() => {});
        }
        if (record.playbackStorage === "r2" && record.playbackR2Key) {
          await objectStorage.deleteObject({ key: record.playbackR2Key });
        } else if (record.playbackStorage === "gridfs" && record.playbackGridFsId && gridFsBucket) {
          await gridFsBucket.delete(new mongoose.Types.ObjectId(record.playbackGridFsId)).catch(() => {});
        } else if (record.playbackStoredName) {
          await fs.promises.unlink(path.join(UPLOAD_DIR, record.playbackStoredName)).catch(() => {});
        }
      } catch (err) {
        // A missing file is already effectively cleaned. Do not turn cleanup into
        // a server-fatal path.
        if (!/not found|FileNotFound/i.test(String(err?.message || ""))) {
          console.warn("Upload cleanup skipped:", err?.message || err);
        }
      }
    });
}

function pruneChatUploadIfUnreferenced(fileId) {
  const id = String(fileId || "");
  if (!id || isChatUploadReferenced(id)) return false;
  const record = db.uploads?.[id];
  if (!record || record.context !== "chat") return false;
  delete db.uploads[id];
  queuePhysicalUploadDelete(record);
  return true;
}

function trimRoomHistory(roomId, limit = CHAT_HISTORY_LIMIT) {
  const history = db.roomHistory?.[roomId];
  if (!Array.isArray(history) || history.length <= limit) return { removedMessages: 0, removedUploads: 0 };
  const removed = history.splice(0, history.length - limit);
  const removedIds = new Set(removed.map(message => String(message?.msgId || "")).filter(Boolean));
  const roomDoc = db.rooms?.[roomId];
  if (roomDoc && Array.isArray(roomDoc.pinnedMessageIds) && removedIds.size) {
    roomDoc.pinnedMessageIds = roomDoc.pinnedMessageIds.filter(id => !removedIds.has(String(id)));
  }
  let removedUploads = 0;
  for (const message of removed) {
    for (const fileId of messageFileIds(message)) {
      if (pruneChatUploadIfUnreferenced(fileId)) removedUploads += 1;
    }
  }
  return { removedMessages: removed.length, removedUploads };
}

function appendRoomMessage(roomId, messageData) {
  if (!db.roomHistory[roomId]) db.roomHistory[roomId] = [];
  db.roomHistory[roomId].push(messageData);
  return trimRoomHistory(roomId);
}

function countUnreadMessages(roomId, username) {
  if (!roomId || !username) return 0;
  const history = Array.isArray(db.roomHistory?.[roomId]) ? db.roomHistory[roomId] : [];
  let count = 0;
  for (const msg of history) {
    if (!msg || msg.deleted || msg.userId === username) continue;
    const readBy = Array.isArray(msg.readBy) ? msg.readBy : [];
    const read = readBy.some(entry => (typeof entry === "object" ? entry.userId : entry) === username);
    if (!read) count += 1;
  }
  return count;
}

function normalizePinnedMessageIds(roomDoc) {
  if (!roomDoc) return [];
  if (!Array.isArray(roomDoc.pinnedMessageIds)) roomDoc.pinnedMessageIds = [];
  roomDoc.pinnedMessageIds = [...new Set(roomDoc.pinnedMessageIds.map(String).filter(Boolean))].slice(-10);
  return roomDoc.pinnedMessageIds;
}

function canPinRoomMessage(roomId, actor) {
  const roomDoc = db.rooms?.[roomId];
  if (!roomDoc || !actor || !canUserAccessRoom(roomId, actor)) return false;
  if (roomDoc.isPrivate) return true;
  return roomDoc.owner === actor ||
    (Array.isArray(roomDoc.moderators) && roomDoc.moderators.includes(actor)) ||
    actor === PLATFORM_OWNER_USERNAME ||
    hasPermission(actor, "manage_rooms");
}

function removeRoomHistoryAndFiles(roomId) {
  const history = Array.isArray(db.roomHistory?.[roomId]) ? db.roomHistory[roomId] : [];
  const fileIds = [];
  for (const message of history) fileIds.push(...messageFileIds(message));
  delete db.roomHistory[roomId];
  for (const fileId of fileIds) pruneChatUploadIfUnreferenced(fileId);
}

function trimAllRoomHistories() {
  let removedMessages = 0;
  let removedUploads = 0;
  for (const roomId of Object.keys(db.roomHistory || {})) {
    const result = trimRoomHistory(roomId);
    removedMessages += result.removedMessages;
    removedUploads += result.removedUploads;
  }
  if (removedMessages > 0) {
    console.log(`🧹 History retention: removed ${removedMessages} old message(s), queued ${removedUploads} old chat upload(s) for deletion; keeping last ${CHAT_HISTORY_LIMIT} per chat.`);
  }
  return { removedMessages, removedUploads };
}

async function migrateLegacyBase64MediaToGridFS() {
  if (!mongoReady || !gridFsBucket) return 0;
  let migrated = 0;

  for (const [roomId, history] of Object.entries(db.roomHistory || {})) {
    if (!Array.isArray(history)) continue;
    for (const msg of history) {
      const dataUri = typeof msg?.fileData === "string" ? msg.fileData : "";
      if (!dataUri.startsWith("data:")) continue;

      const comma = dataUri.indexOf(",");
      if (comma < 0) continue;
      const header = dataUri.slice(5, comma);
      if (!/;base64(?:;|$)/i.test(header)) continue;
      const mimeType = header.split(";")[0] || "application/octet-stream";
      const fileType = msg.fileType || classifyFileType(mimeType, "");
      const ext = mime.extension(mimeType) || "bin";
      const fileId = msg.fileId || ("upl_" + crypto.randomBytes(16).toString("hex"));
      const fileName = msg.fileName || `legacy-${msg.msgId || Date.now()}.${ext}`;
      let decodedBytes = 0;

      try {
        const uploadStream = gridFsBucket.openUploadStream(fileName, {
          metadata: { fileId, mimeType, uploadedAt: new Date(), migratedFromBase64: true }
        });
        const dataStart = comma + 1;
        const chunkChars = 256 * 1024; // divisible by four
        function* decodedChunks() {
          let pos = dataStart;
          while (pos < dataUri.length) {
            let end = Math.min(dataUri.length, pos + chunkChars);
            if (end < dataUri.length) end -= (end - pos) % 4;
            if (end <= pos) end = dataUri.length;
            const buf = Buffer.from(dataUri.slice(pos, end), "base64");
            decodedBytes += buf.length;
            yield buf;
            pos = end;
          }
        }
        await pipeline(Readable.from(decodedChunks()), uploadStream);

        db.uploads[fileId] = {
          fileId,
          storedName: null,
          gridFsId: String(uploadStream.id),
          storage: "gridfs",
          originalName: String(fileName).slice(0, 180),
          mimeType,
          fileType,
          size: decodedBytes,
          uploader: msg.userId || msg.username || "unknown",
          roomId,
          context: "chat",
          createdAt: msg.createdAt || new Date().toISOString(),
          migratedFromBase64: true
        };
        msg.fileId = fileId;
        msg.fileUrl = `/api/files/${encodeURIComponent(fileId)}`;
        msg.fileName = fileName;
        msg.mimeType = mimeType;
        msg.fileSize = decodedBytes;
        delete msg.fileData;
        migrated += 1;
      } catch (err) {
        console.warn(`Legacy media migration skipped (${roomId}):`, err.message);
      }
    }
  }

  if (migrated) {
    console.log(`♻️ Migrated ${migrated} legacy Base64 media message(s) to GridFS`);
    // Persist the smaller state before accepting normal traffic.
    await persistMongoStateNow();
  }
  return migrated;
}

function repairLegacyMediaMetadata() {
  let repaired = 0;
  const byFileId = db.uploads || {};
  const legacyVideoExts = new Set([
    ".mp4", ".m4v", ".mov", ".webm", ".mkv", ".avi", ".3gp", ".3g2", ".mpeg", ".mpg",
    ".m2v", ".m1v", ".ts", ".mts", ".m2ts", ".ogv", ".flv", ".f4v", ".wmv", ".asf",
    ".vob", ".rm", ".rmvb", ".mxf", ".divx", ".xvid"
  ]);
  for (const record of Object.values(byFileId)) {
    if (!record || typeof record !== "object") continue;
    const name = String(record.originalName || "").toLowerCase();
    const ext = path.extname(name);
    const isVoice = /^voice[-_]/i.test(path.basename(name));
    const looksLikeVideoLabel = /^(?:mp4|video|vid)[._-]/i.test(path.basename(name));
    const looksLikeVideoMime = ["", "application/octet-stream", "audio/mp4", "audio/quicktime"]
      .includes(String(record.mimeType || "").toLowerCase());
    if (!isVoice && record.fileType === "audio"
      && (legacyVideoExts.has(ext)
        || (looksLikeVideoLabel && looksLikeVideoMime
          && ![".m4a", ".mp3", ".aac", ".wav", ".ogg", ".opus", ".flac", ".weba"].includes(ext)))) {
      record.fileType = "video";
      record.mimeType = "video/mp4";
      repaired += 1;
    }
  }

  for (const history of Object.values(db.roomHistory || {})) {
    if (!Array.isArray(history)) continue;
    for (const msg of history) {
      if (!msg?.fileId) continue;
      const record = byFileId[msg.fileId];
      if (!record) continue;
      if (msg.fileType !== record.fileType || msg.mimeType !== record.mimeType) {
        msg.fileType = record.fileType;
        msg.mimeType = record.mimeType;
        msg.fileName = msg.fileName || record.originalName;
        msg.fileSize = msg.fileSize || record.size;
        repaired += 1;
      }
    }
  }

  if (repaired) {
    console.log(`🛠️ Repaired ${repaired} legacy media metadata field(s)`);
    scheduleMongoSave();
  }
  return repaired;
}

async function initCloudDatabase() {
  if (!CLOUD_DATABASE_ENABLED) {
    console.log(`📁 Local JSON mode: ${DB_PATH}`);
    return;
  }

  try {
    await mongoose.connect(MONGODB_URI, {
      serverSelectionTimeoutMS: 15000,
      maxPoolSize: 5,
      minPoolSize: 0
    });

    const stateSchema = new mongoose.Schema({
      key: { type: String, required: true, unique: true, index: true },
      state: { type: mongoose.Schema.Types.Mixed, required: true },
      updatedAt: { type: Date, default: Date.now }
    }, { minimize: false, versionKey: false });

    ChatifyState = mongoose.models.ChatifyState || mongoose.model("ChatifyState", stateSchema);
    gridFsBucket = new mongoose.mongo.GridFSBucket(mongoose.connection.db, {
      bucketName: "chatifyUploads"
    });

    const cloudDoc = await ChatifyState.findOne({ key: "main" }).lean().exec();
    if (cloudDoc?.state) {
      db = normalizeDatabaseState(cloudDoc.state);
      console.log("☁️ MongoDB Atlas state loaded successfully");
    } else {
      db = normalizeDatabaseState(db);
      await ChatifyState.create({ key: "main", state: db, updatedAt: new Date() });
      console.log("☁️ MongoDB Atlas initialized from chat_database.json");
    }

    mongoReady = true;
    await migrateLegacyBase64MediaToGridFS();
    repairLegacyMediaMetadata();
  } catch (err) {
    mongoReady = false;
    gridFsBucket = null;
    console.error("⚠️ MongoDB unavailable; using local JSON fallback:", err.message);
  }
}

async function flushCloudDatabase() {
  clearTimeout(mongoSaveTimer);
  mongoSaveTimer = null;
  if (!mongoReady || !ChatifyState) return;
  mongoSaveDirty = true;
  while (mongoSaveRunning) {
    await new Promise(resolve => setTimeout(resolve, 25));
  }
  await persistMongoStateNow();
}

// =========================================================
// 2. Helper Functions
// =========================================================

// 🔐 Password hashing.
// New passwords use bcrypt. Legacy SHA-256 hashes remain readable and are
// upgraded automatically after the next successful login.
const LEGACY_PASSWORD_SALT = "_chatify_salt_v2024";

function legacyHashPassword(password) {
  return crypto.createHash("sha256").update(password + LEGACY_PASSWORD_SALT).digest("hex");
}

function hashPassword(password) {
  return bcrypt.hashSync(password, 12);
}

function verifyPassword(password, hash) {
  if (!hash || typeof hash !== "string") return false;
  if (hash.startsWith("$2a$") || hash.startsWith("$2b$") || hash.startsWith("$2y$")) {
    try {
      return bcrypt.compareSync(password, hash);
    } catch {
      return false;
    }
  }
  return legacyHashPassword(password) === hash;
}

function upgradePasswordHashIfNeeded(user, password) {
  if (!user || !user.password || user.password.startsWith("$2")) return;
  if (verifyPassword(password, user.password)) {
    user.password = hashPassword(password);
  }
}

// ✅ Username validation.
// Ordinary users must choose at least 4 characters.
// Short/special usernames are reserved for staff accounts created by the owner.
function validateUsername(username, options = {}) {
  if (!username || typeof username !== "string") {
    return { valid: false, error: "اسم المستخدم مطلوب" };
  }

  const trimmed = username.trim();
  const len = [...trimmed].length;
  const allowSpecial = !!options.allowSpecial;
  const minLength = allowSpecial ? 1 : 4;

  if (len < minLength) {
    return {
      valid: false,
      error: allowSpecial
        ? "اسم المستخدم غير صالح"
        : "اسم المستخدم للمستخدم العادي يجب أن يكون 4 أحرف على الأقل"
    };
  }

  if (len > 32) {
    return { valid: false, error: "اسم المستخدم يجب ألا يتجاوز 32 حرفاً" };
  }

  if (/\s/.test(trimmed)) {
    return { valid: false, error: "اسم المستخدم لا يمكن أن يحتوي على مسافات" };
  }

  return { valid: true, role: "user", username: trimmed };
}

// ✅ Validate password (min 6 chars)
function validatePassword(password) {
  if (!password || typeof password !== "string") {
    return { valid: false, error: "كلمة المرور مطلوبة" };
  }
  if (password.length < 6) {
    return { valid: false, error: "كلمة المرور يجب أن تكون 6 أحرف على الأقل" };
  }
  return { valid: true };
}

// 🔒 Private room helpers
function getPrivateRoomId(user1, user2) {
  return "private_" + [user1, user2].sort().join("_");
}

function isPrivateRoom(roomId) {
  return roomId && roomId.startsWith("private_");
}

// 🤝 Are they friends?
function areFriends(u1, u2) {
  const [a, b] = [u1, u2].sort();
  const key = a + "_" + b;
  return !!(db.friends && db.friends[key]);
}

// 🛡️ Check room ban
function checkRoomBan(roomId, userId) {
  if (!db.roomBans || !db.roomBans[roomId]) return { banned: false };
  const ban = db.roomBans[roomId][userId];
  if (!ban) return { banned: false };
  if (ban.isPermanent) {
    return { banned: true, reason: ban.reason || "", type: "permanent", bannedBy: ban.bannedBy };
  }
  if (ban.expiresAt && new Date(ban.expiresAt) > new Date()) {
    return { banned: true, reason: ban.reason || "", type: "temporary", expiresAt: ban.expiresAt, bannedBy: ban.bannedBy };
  }
  // Expired ban - remove it
  delete db.roomBans[roomId][userId];
  saveDB(db);
  return { banned: false };
}

// 🎭 Get user role
function getUserRole(username) {
  const user = db.users[username];
  if (!user) return "user";
  if (username === PLATFORM_OWNER_USERNAME) return "owner";
  if (user.staffApproved && ["admin", "moderator"].includes(user.role)) return user.role;
  return "user";
}

// 🛡️ Room/platform staff check.
function isRoomStaff(roomId, username) {
  const room = db.rooms[roomId];
  if (!room || !username) return false;
  if (room.owner === username) return "owner";
  if (room.moderators && room.moderators.includes(username)) return "moderator";
  if (username === PLATFORM_OWNER_USERNAME) return "owner";
  if (hasPermission(username, "manage_room_bans")) return getPublicRole(username);
  return false;
}

function canModeratePublicRoomTarget(roomId, actor, targetUser) {
  const room = db.rooms?.[roomId];
  if (!room || !actor || !targetUser || actor === targetUser) return false;
  if (!isRoomStaff(roomId, actor)) return false;

  // Only the platform owner can remove a public-room owner. Platform staff
  // and the room owner themselves cannot be removed by lower-level staff.
  if (actor === PLATFORM_OWNER_USERNAME) return true;
  if (isProtectedPlatformUser(targetUser)) return false;
  if (room.owner === targetUser) return false;

  // A normal room moderator can manage members, but not another room
  // moderator. The room owner may manage their room moderators.
  if (Array.isArray(room.moderators) && room.moderators.includes(targetUser) && room.owner !== actor) {
    return false;
  }
  return true;
}

// 📊 Get user stats
function getUserStats(username) {
  let friendsCount = 0;
  if (db.friends) {
    for (const key in db.friends) {
      const parts = key.split("_");
      if (parts.length === 2 && (parts[0] === username || parts[1] === username)) {
        friendsCount++;
      }
    }
  }
  let requestsCount = 0;
  if (db.friendRequests) {
    for (const key in db.friendRequests) {
      if (db.friendRequests[key].toUser === username) requestsCount++;
    }
  }
  return { friendsCount, requestsCount };
}

// 🆕 Generate a cryptographically-strong room/share code
function generateShareCode(length = 10) {
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789";
  const bytes = crypto.randomBytes(length);
  let code = "";
  for (let i = 0; i < length; i++) {
    code += chars[bytes[i] % chars.length];
  }
  return code;
}

function generateUniqueRoomCode() {
  let code;
  do {
    code = generateShareCode(10);
  } while (db.rooms[code] || Object.values(db.rooms).some(room => room && room.shareCode === code));
  return code;
}

function normalizeMaxUsers(value, fallback = 24) {
  const parsed = Number.parseInt(value, 10);
  if (!Number.isInteger(parsed)) return fallback;
  return Math.min(100, Math.max(2, parsed));
}

function findPublicRoomByIdOrCode(roomIdOrCode) {
  if (!roomIdOrCode) return null;

  const direct = db.rooms[roomIdOrCode];
  if (direct && !direct.isPrivate) {
    return { roomId: roomIdOrCode, room: direct };
  }

  for (const rId in db.rooms) {
    const room = db.rooms[rId];
    if (room && !room.isPrivate && room.shareCode === roomIdOrCode) {
      return { roomId: rId, room };
    }
  }

  return null;
}

function getPrivateRoomParticipants(roomId) {
  if (!roomId) return null;

  if (db.privateChats && db.privateChats[roomId] && Array.isArray(db.privateChats[roomId].members)) {
    return db.privateChats[roomId].members;
  }

  for (const key in db.friends) {
    const f = db.friends[key];
    if (!f || !f.user1 || !f.user2) continue;
    if (getPrivateRoomId(f.user1, f.user2) === roomId) {
      return [f.user1, f.user2];
    }
  }

  return null;
}

function canAccessPrivateRoom(roomId, userId) {
  const participants = getPrivateRoomParticipants(roomId);
  return Array.isArray(participants) && participants.includes(userId);
}

// Keep the canonical private-chat document synchronized in db.rooms.
// This makes text, uploads, voice notes and WebRTC signaling reliable even
// when a private conversation is opened from history before any message exists.
function ensurePrivateRoomDocument(roomId) {
  if (!isPrivateRoom(roomId)) return null;

  const participants = getPrivateRoomParticipants(roomId);
  if (!Array.isArray(participants) || participants.length !== 2) return null;

  const members = [...new Set(participants)];
  const now = new Date().toISOString();
  let changed = false;

  if (!db.privateChats[roomId]) {
    db.privateChats[roomId] = {
      roomId,
      members,
      isPrivate: true,
      createdAt: now
    };
    changed = true;
  } else {
    const privateChat = db.privateChats[roomId];
    if (
      !Array.isArray(privateChat.members) ||
      privateChat.members.length !== 2 ||
      members.some(member => !privateChat.members.includes(member))
    ) {
      privateChat.members = members;
      changed = true;
    }
    if (privateChat.isPrivate !== true) {
      privateChat.isPrivate = true;
      changed = true;
    }
  }

  if (!db.rooms[roomId]) {
    db.rooms[roomId] = {
      roomId,
      roomName: "محادثة خاصة",
      owner: null,
      moderators: [],
      members,
      maxUsers: 2,
      isPrivate: true,
      background: null,
      createdAt: db.privateChats[roomId].createdAt || now
    };
    changed = true;
  } else {
    const room = db.rooms[roomId];

    if (room.isPrivate !== true) {
      room.isPrivate = true;
      changed = true;
    }

    if (room.maxUsers !== 2) {
      room.maxUsers = 2;
      changed = true;
    }

    if (
      !Array.isArray(room.members) ||
      room.members.length !== 2 ||
      members.some(member => !room.members.includes(member))
    ) {
      room.members = members;
      changed = true;
    }

    if (!Array.isArray(room.moderators)) {
      room.moderators = [];
      changed = true;
    }

    if (!("background" in room)) {
      room.background = null;
      changed = true;
    }
  }

  if (!db.roomHistory[roomId]) {
    db.roomHistory[roomId] = [];
    changed = true;
  }

  if (changed) saveDB(db);
  return db.rooms[roomId];
}

function getCanonicalRoomId(roomIdOrCode) {
  if (!roomIdOrCode) return null;
  if (isPrivateRoom(roomIdOrCode)) return roomIdOrCode;

  const found = findPublicRoomByIdOrCode(roomIdOrCode);
  return found ? found.roomId : roomIdOrCode;
}

function getLastActivityIso(roomId, fallbackIso = null) {
  const history = db.roomHistory[roomId] || [];
  const last = history.length ? history[history.length - 1] : null;
  if (last && last.createdAt) return last.createdAt;
  return fallbackIso || null;
}

// Official TOMI platform inbox. It is a read-only private room created for
// each user when the owner/staff sends a platform-wide announcement.
function getPlatformInboxRoomId(username) {
  const digest = crypto.createHash("sha256").update(String(username || "")).digest("hex").slice(0, 24);
  return `private_platform_${digest}`;
}

function ensurePlatformInbox(username) {
  if (!username || !db.users[username] || username === PLATFORM_OWNER_USERNAME) return null;
  const roomId = getPlatformInboxRoomId(username);
  const now = new Date().toISOString();

  if (!db.privateChats[roomId]) {
    db.privateChats[roomId] = {
      roomId,
      members: [PLATFORM_OWNER_USERNAME, username],
      isPrivate: true,
      systemRoom: true,
      createdAt: now
    };
  } else {
    db.privateChats[roomId].members = [PLATFORM_OWNER_USERNAME, username];
    db.privateChats[roomId].isPrivate = true;
    db.privateChats[roomId].systemRoom = true;
  }

  const room = ensurePrivateRoomDocument(roomId);
  if (!room) return null;
  room.roomName = "TOMI • حساب المنصة";
  room.systemRoom = true;
  room.readOnly = true;
  room.platformAccount = true;
  room.members = [PLATFORM_OWNER_USERNAME, username];
  room.updatedAt = room.updatedAt || now;
  if (!Array.isArray(db.roomHistory[roomId])) db.roomHistory[roomId] = [];
  return { roomId, room };
}

function isPlatformSystemRoom(roomId) {
  return Boolean(db.rooms?.[roomId]?.systemRoom);
}


function isPlatformInboxCandidate(roomId, room, username) {
  if (!room || !username) return false;
  const members = Array.isArray(room.members) ? room.members : [];
  const roomName = String(room.roomName || room.name || "");
  const systemish = Boolean(
    room.systemRoom ||
    room.platformAccount ||
    String(roomId || "").startsWith("private_platform_") ||
    roomName === "TOMI • حساب المنصة"
  );
  return systemish && members.includes(username);
}

function platformMessageMergeKey(message) {
  const msg = message && typeof message === "object" ? message : {};
  const createdAt = String(msg.createdAt || "");
  const type = String(msg.type || "text");
  const body = String(msg.msg || "");
  const fileId = String(msg.fileId || msg.fileUrl || "");
  const sentBy = String(msg.sentBy || msg.username || msg.userId || "");

  // A single platform broadcast can exist in more than one legacy system room.
  // Those copies share the same timestamp/content but may have different msgIds.
  if (createdAt || body || fileId) {
    return `broadcast:${createdAt}|${type}|${body}|${fileId}|${sentBy}`;
  }
  return `id:${String(msg.msgId || "")}`;
}

// Older builds could leave more than one "TOMI • حساب المنصة" room for the
// same user. Merge all of them into the deterministic canonical inbox so every
// user sees ONE official conversation containing the complete announcement
// history. This runs after MongoDB is loaded and is safe to run repeatedly.
function consolidatePlatformInboxes() {
  let changed = false;
  let removedRooms = 0;
  let mergedUsers = 0;

  for (const username of Object.keys(db.users || {})) {
    if (!username || username === PLATFORM_OWNER_USERNAME) continue;

    const canonicalRoomId = getPlatformInboxRoomId(username);
    const candidateIds = new Set();

    for (const [roomId, room] of Object.entries(db.rooms || {})) {
      if (isPlatformInboxCandidate(roomId, room, username)) candidateIds.add(roomId);
    }
    for (const [roomId, room] of Object.entries(db.privateChats || {})) {
      if (isPlatformInboxCandidate(roomId, room, username)) candidateIds.add(roomId);
    }

    if (!candidateIds.size) continue;

    const inbox = ensurePlatformInbox(username);
    if (!inbox) continue;
    candidateIds.add(canonicalRoomId);

    const collected = [];
    let sequence = 0;
    for (const roomId of candidateIds) {
      const history = Array.isArray(db.roomHistory?.[roomId]) ? db.roomHistory[roomId] : [];
      for (const rawMessage of history) {
        if (!rawMessage || typeof rawMessage !== "object") continue;
        collected.push({ message: rawMessage, sequence: sequence++ });
      }
    }

    collected.sort((a, b) => {
      const ta = Date.parse(a.message.createdAt || "") || 0;
      const tb = Date.parse(b.message.createdAt || "") || 0;
      return ta === tb ? a.sequence - b.sequence : ta - tb;
    });

    const seen = new Set();
    const mergedHistory = [];
    for (const entry of collected) {
      const key = platformMessageMergeKey(entry.message);
      if (seen.has(key)) continue;
      seen.add(key);
      mergedHistory.push({
        ...entry.message,
        roomId: canonicalRoomId,
        platformAccount: true,
        systemBroadcast: entry.message.systemBroadcast !== false
      });
    }

    const previousCanonicalHistory = Array.isArray(db.roomHistory[canonicalRoomId])
      ? db.roomHistory[canonicalRoomId]
      : [];
    if (
      candidateIds.size > 1 ||
      previousCanonicalHistory.length !== mergedHistory.length ||
      mergedHistory.some((m, i) => previousCanonicalHistory[i]?.msgId !== m.msgId || previousCanonicalHistory[i]?.roomId !== canonicalRoomId)
    ) {
      db.roomHistory[canonicalRoomId] = mergedHistory;
      changed = true;
      mergedUsers += 1;
    }

    const lastMessage = mergedHistory.length ? mergedHistory[mergedHistory.length - 1] : null;
    inbox.room.roomName = "TOMI • حساب المنصة";
    inbox.room.systemRoom = true;
    inbox.room.readOnly = true;
    inbox.room.platformAccount = true;
    inbox.room.isPrivate = true;
    inbox.room.members = [PLATFORM_OWNER_USERNAME, username];
    if (lastMessage?.createdAt) inbox.room.updatedAt = lastMessage.createdAt;

    if (db.privateChats[canonicalRoomId]) {
      db.privateChats[canonicalRoomId].members = [PLATFORM_OWNER_USERNAME, username];
      db.privateChats[canonicalRoomId].isPrivate = true;
      db.privateChats[canonicalRoomId].systemRoom = true;
      db.privateChats[canonicalRoomId].platformAccount = true;
    }

    for (const roomId of candidateIds) {
      if (roomId === canonicalRoomId) continue;

      if (db.notificationPreferences?.[username]?.[roomId] !== undefined &&
          db.notificationPreferences?.[username]?.[canonicalRoomId] === undefined) {
        db.notificationPreferences[username][canonicalRoomId] = db.notificationPreferences[username][roomId];
      }
      if (db.notificationPreferences?.[username]) {
        delete db.notificationPreferences[username][roomId];
      }

      if (db.rooms?.[roomId]) delete db.rooms[roomId];
      if (db.privateChats?.[roomId]) delete db.privateChats[roomId];
      if (db.roomHistory?.[roomId]) delete db.roomHistory[roomId];
      if (db.roomBans?.[roomId]) delete db.roomBans[roomId];
      removedRooms += 1;
      changed = true;
    }
  }

  if (changed) {
    saveDB(db);
    console.log(`🧹 Platform inbox cleanup: merged ${mergedUsers} user inbox(es), removed ${removedRooms} duplicate room(s)`);
  }
  return { changed, mergedUsers, removedRooms };
}

// =========================================================
// Platform owner, permissions, receipts, sessions & uploads
// =========================================================
const PLATFORM_OWNER_USERNAME = "tomi";
const PLATFORM_OWNER_BOOTSTRAP_LEGACY_HASH = "6439dde8ccd48fbf7b0fa5c77f8ef45fd0e982a6650e4090678764b9ed937857";

const ALL_PERMISSIONS = Object.freeze([
  "manage_platform_bans",
  "manage_moderators",
  "manage_permissions",
  "manage_reports",
  "manage_rooms",
  "manage_room_bans",
  "delete_messages",
  "manage_backgrounds",
  "manage_frames",
  "create_special_staff_accounts",
  "send_platform_broadcast",
  "view_analytics",
  "view_system_metrics",
  "view_user_analytics",
  "manage_referrals",
  "manage_ai_safety"
]);

function normalizePermissions(list) {
  if (!Array.isArray(list)) return [];
  return [...new Set(list.filter(p => ALL_PERMISSIONS.includes(p)))];
}

function getUserPermissions(username) {
  if (!username) return [];
  if (username === PLATFORM_OWNER_USERNAME) return [...ALL_PERMISSIONS];
  const user = db.users[username];
  if (!user || !user.staffApproved) return [];
  return normalizePermissions(user.permissions);
}

function hasPermission(username, permission) {
  if (username === PLATFORM_OWNER_USERNAME) return true;
  return getUserPermissions(username).includes(permission);
}

function isApprovedPlatformStaff(username) {
  const user = db.users[username];
  if (!user) return false;
  if (username === PLATFORM_OWNER_USERNAME) return true;
  return !!user.staffApproved && ["admin", "moderator"].includes(user.role);
}

function getPublicRole(username) {
  const user = db.users[username];
  if (!user) return "user";
  if (username === PLATFORM_OWNER_USERNAME) return "owner";
  return isApprovedPlatformStaff(username) ? user.role : "user";
}

function getPlatformBadge(username) {
  const role = getPublicRole(username);
  if (role === "owner") return { type: "owner", label: "مالك المنصة", icon: "crown" };
  if (role === "admin") return { type: "admin", label: "إدارة", icon: "shield" };
  if (role === "moderator") return { type: "moderator", label: "مشرف", icon: "badge-check" };
  return null;
}

// Platform staff are protected everywhere. Room moderators remain ordinary
// room-level staff: they can be managed in other rooms unless they also have a
// platform role, and they cannot override platform staff protections.
function isProtectedPlatformUser(username) {
  return Boolean(username && isApprovedPlatformStaff(username));
}

function canManagePlatformRooms(username) {
  return Boolean(username && (username === PLATFORM_OWNER_USERNAME || hasPermission(username, "manage_rooms")));
}


function getActiveFrame(username) {
  const user = db.users?.[username];
  const assignment = user?.frameAssignment;
  if (!assignment?.frameId) return null;

  if (!assignment.permanent && assignment.expiresAt) {
    const expiresMs = Date.parse(assignment.expiresAt);
    if (Number.isFinite(expiresMs) && expiresMs <= Date.now()) {
      delete user.frameAssignment;
      saveDB(db);
      return null;
    }
  }

  const frame = db.frames?.[assignment.frameId];
  if (!frame) return null;

  return {
    frameId: frame.frameId,
    name: frame.name,
    fileId: frame.fileId,
    url: frame.url || `/api/files/${encodeURIComponent(frame.fileId)}`,
    animated: !!frame.animated,
    permanent: !!assignment.permanent,
    assignedAt: assignment.assignedAt || null,
    expiresAt: assignment.expiresAt || null
  };
}

function publicUserProfile(username) {
  const user = db.users?.[username] || {};
  return {
    username,
    displayName: user.displayName || username,
    avatar: user.avatar || "",
    role: getPublicRole(username),
    badge: getPlatformBadge(username),
    frame: getActiveFrame(username)
  };
}

function ensurePlatformOwner() {
  const now = new Date().toISOString();
  if (!db.users[PLATFORM_OWNER_USERNAME]) {
    db.users[PLATFORM_OWNER_USERNAME] = {
      username: PLATFORM_OWNER_USERNAME,
      password: PLATFORM_OWNER_BOOTSTRAP_LEGACY_HASH,
      role: "owner",
      displayName: "tomi",
      staffApproved: true,
      permissions: [...ALL_PERMISSIONS],
      registeredAt: now,
      status: "offline",
      lastSeen: now
    };
  } else {
    const owner = db.users[PLATFORM_OWNER_USERNAME];
    owner.role = "owner";
    owner.staffApproved = true;
    owner.permissions = [...ALL_PERMISSIONS];
    owner.displayName = owner.displayName || PLATFORM_OWNER_USERNAME;
  }

  // Old automatically-created moderators keep their data, but they do not
  // receive platform powers until the owner explicitly approves them.
  for (const username of Object.keys(db.users)) {
    if (username === PLATFORM_OWNER_USERNAME) continue;
    const user = db.users[username];
    if (!Array.isArray(user.permissions)) user.permissions = [];
    if (typeof user.staffApproved !== "boolean") user.staffApproved = false;
  }

  saveDB(db);
}

function checkPlatformBan(username) {
  if (!username || username === PLATFORM_OWNER_USERNAME) return { banned: false };
  const ban = db.platformBans[username];
  if (!ban) return { banned: false };

  if (ban.isPermanent) {
    return { banned: true, ...ban, type: "permanent" };
  }

  if (ban.expiresAt && Date.parse(ban.expiresAt) > Date.now()) {
    return { banned: true, ...ban, type: "temporary" };
  }

  delete db.platformBans[username];
  saveDB(db);
  return { banned: false };
}

function canUserAccessRoom(roomIdOrCode, username) {
  if (!username) return false;
  const rId = getCanonicalRoomId(roomIdOrCode);
  let room = db.rooms[rId];

  if (!room && isPrivateRoom(rId)) {
    room = ensurePrivateRoomDocument(rId);
  }

  if (!room) return false;
  if (room.isPrivate) return canAccessPrivateRoom(rId, username);
  return Array.isArray(room.members) && room.members.includes(username);
}

function getRoomAudience(roomId) {
  const room = db.rooms[roomId];
  if (!room) return [];
  if (room.isPrivate) return getPrivateRoomParticipants(roomId) || [];
  return Array.isArray(room.members) ? [...new Set(room.members)] : [];
}

// =========================================================
// Per-room notifications + Web Push
// =========================================================
let webPushReady = false;
let webPushPublicKey = "";

function ensureNotificationState() {
  if (!db.notificationPreferences || typeof db.notificationPreferences !== "object") db.notificationPreferences = {};
  if (!db.pushSubscriptions || typeof db.pushSubscriptions !== "object") db.pushSubscriptions = {};
  if (!db.pushConfig || typeof db.pushConfig !== "object") db.pushConfig = {};
}

function roomNotificationsEnabled(username, roomIdOrCode) {
  ensureNotificationState();
  const rId = getCanonicalRoomId(roomIdOrCode);
  if (!username || !rId) return false;
  return db.notificationPreferences?.[username]?.[rId] !== false;
}

function setRoomNotificationsEnabled(username, roomIdOrCode, enabled) {
  ensureNotificationState();
  const rId = getCanonicalRoomId(roomIdOrCode);
  if (!db.notificationPreferences[username]) db.notificationPreferences[username] = {};
  db.notificationPreferences[username][rId] = Boolean(enabled);
  saveDB(db);
  return db.notificationPreferences[username][rId];
}

function sanitizePushSubscription(subscription) {
  const endpoint = String(subscription?.endpoint || "").trim();
  const p256dh = String(subscription?.keys?.p256dh || "").trim();
  const auth = String(subscription?.keys?.auth || "").trim();
  if (!endpoint || !p256dh || !auth) return null;
  return { endpoint, expirationTime: subscription?.expirationTime || null, keys: { p256dh, auth } };
}

function initializeWebPush() {
  ensureNotificationState();
  try {
    const envPublic = String(process.env.VAPID_PUBLIC_KEY || "").trim();
    const envPrivate = String(process.env.VAPID_PRIVATE_KEY || "").trim();
    let publicKey = envPublic;
    let privateKey = envPrivate;

    if (!publicKey || !privateKey) {
      publicKey = String(db.pushConfig.publicKey || "").trim();
      privateKey = String(db.pushConfig.privateKey || "").trim();
    }

    if (!publicKey || !privateKey) {
      if (!webpush) webpush = require("web-push");
      const generated = webpush.generateVAPIDKeys();
      publicKey = generated.publicKey;
      privateKey = generated.privateKey;
      db.pushConfig.publicKey = publicKey;
      db.pushConfig.privateKey = privateKey;
      db.pushConfig.generatedAt = new Date().toISOString();
    }

    const subject = String(process.env.VAPID_SUBJECT || "mailto:admin@tomii.local").trim();
    if (!webpush) webpush = require("web-push");
    webpush.setVapidDetails(subject, publicKey, privateKey);
    webPushPublicKey = publicKey;
    webPushReady = true;
    console.log("🔔 Web Push notifications ready");
  } catch (error) {
    webPushReady = false;
    webPushPublicKey = "";
    console.error("Web Push initialization failed:", error.message);
  }
}

function upsertPushSubscription(username, subscription) {
  ensureNotificationState();
  const clean = sanitizePushSubscription(subscription);
  if (!clean || !username) return false;
  if (!Array.isArray(db.pushSubscriptions[username])) db.pushSubscriptions[username] = [];
  const list = db.pushSubscriptions[username];
  const existingIndex = list.findIndex(item => item?.endpoint === clean.endpoint);
  const record = { ...clean, updatedAt: new Date().toISOString() };
  if (existingIndex >= 0) list[existingIndex] = record;
  else list.push(record);
  if (list.length > 12) db.pushSubscriptions[username] = list.slice(-12);
  saveDB(db);
  return true;
}

function removePushSubscription(username, endpoint) {
  ensureNotificationState();
  const list = Array.isArray(db.pushSubscriptions[username]) ? db.pushSubscriptions[username] : [];
  const next = list.filter(item => item?.endpoint !== endpoint);
  if (next.length !== list.length) {
    db.pushSubscriptions[username] = next;
    saveDB(db);
  }
}

async function sendPushToUser(username, roomId, payload = {}) {
  if (!webPushReady || !username || !roomNotificationsEnabled(username, roomId)) return;
  const subscriptions = Array.isArray(db.pushSubscriptions?.[username]) ? [...db.pushSubscriptions[username]] : [];
  if (!subscriptions.length) return;

  const body = JSON.stringify({
    title: payload.title || "TOMI",
    body: payload.body || "لديك نشاط جديد",
    url: payload.url || `/room.html?roomId=${encodeURIComponent(roomId)}`,
    roomId,
    tag: payload.tag || `tomi-${roomId}-${Date.now()}`,
    type: payload.type || "message",
    requireInteraction: Boolean(payload.requireInteraction)
  });

  await Promise.allSettled(subscriptions.map(async subscription => {
    try {
      await webpush.sendNotification(subscription, body, { TTL: payload.type === "call" ? 45 : 180, urgency: "high" });
    } catch (error) {
      if (error?.statusCode === 404 || error?.statusCode === 410) {
        removePushSubscription(username, subscription.endpoint);
      } else {
        console.warn("Push notification failed:", error?.statusCode || error?.message || error);
      }
    }
  }));
}

function mediaNotificationBody(fileType, fileName = "") {
  const name = String(fileName || "").slice(0, 80);
  if (fileType === "image" || fileType === "gif") return "📷 أرسل صورة";
  if (fileType === "video") return "🎥 أرسل فيديو";
  if (fileType === "audio") return "🎤 أرسل رسالة صوتية";
  if (fileType === "pdf") return `📄 أرسل ملف PDF${name ? `: ${name}` : ""}`;
  return `📎 أرسل ملف${name ? `: ${name}` : ""}`;
}

async function notifyRoomParticipants(roomId, actor, payload) {
  const audience = getRoomAudience(roomId).filter(username => username && username !== actor);
  await Promise.allSettled(audience.map(username => sendPushToUser(username, roomId, payload)));
}

function normalizeReceiptEntries(entries) {
  if (!Array.isArray(entries)) return [];
  const out = [];
  const seen = new Set();
  for (const entry of entries) {
    const userId = typeof entry === "string" ? entry : entry?.userId;
    if (!userId || seen.has(userId)) continue;
    seen.add(userId);
    const user = db.users[userId] || {};
    out.push({
      userId,
      username: typeof entry === "object" && entry?.username ? entry.username : userId,
      displayName: user.displayName || userId,
      time: typeof entry === "object" ? (entry.time || "") : "",
      at: typeof entry === "object" ? (entry.at || entry.readAt || entry.deliveredAt || null) : null
    });
  }
  return out;
}

function getMessageInfo(roomId, msg) {
  const audience = getRoomAudience(roomId);
  const readBy = normalizeReceiptEntries(msg.readBy);
  const deliveredTo = normalizeReceiptEntries(msg.deliveredTo);
  const readSet = new Set(readBy.map(x => x.userId));
  const deliveredSet = new Set(deliveredTo.map(x => x.userId));

  const notReadBy = audience
    .filter(id => !readSet.has(id))
    .map(id => ({
      userId: id,
      username: id,
      displayName: db.users[id]?.displayName || id
    }));

  const notDeliveredTo = audience
    .filter(id => !deliveredSet.has(id))
    .map(id => ({
      userId: id,
      username: id,
      displayName: db.users[id]?.displayName || id
    }));

  return {
    messageId: msg.msgId,
    roomId,
    sentAt: msg.createdAt || null,
    sentTime: msg.time || "",
    readBy,
    deliveredTo,
    notReadBy,
    notDeliveredTo,
    totalRecipients: Math.max(0, audience.length - 1),
    readCount: Math.max(0, readBy.filter(x => x.userId !== msg.userId).length),
    deliveredCount: Math.max(0, deliveredTo.filter(x => x.userId !== msg.userId).length)
  };
}

// Persistent server sessions. Sessions live inside the cloud state so a Render
// restart does not automatically log every user out.
const SESSION_TTL_MS = 7 * 24 * 60 * 60 * 1000;

function issueSession(username) {
  const token = crypto.randomBytes(32).toString("hex");
  if (!db.sessions) db.sessions = {};
  db.sessions[token] = { username, expiresAt: Date.now() + SESSION_TTL_MS };
  saveDB(db);
  return token;
}

function getSession(token) {
  if (!token) return null;
  if (!db.sessions) db.sessions = {};
  const session = db.sessions[token];
  if (!session) return null;
  if (session.expiresAt <= Date.now()) {
    delete db.sessions[token];
    saveDB(db);
    return null;
  }
  return session;
}

function deleteSession(token) {
  if (!token || !db.sessions?.[token]) return;
  delete db.sessions[token];
  saveDB(db);
}

function parseCookies(cookieHeader = "") {
  const out = {};
  for (const chunk of String(cookieHeader).split(";")) {
    const idx = chunk.indexOf("=");
    if (idx === -1) continue;
    const key = chunk.slice(0, idx).trim();
    const value = chunk.slice(idx + 1).trim();
    if (key) out[key] = decodeURIComponent(value);
  }
  return out;
}

function getRequestSession(req) {
  const auth = req.headers.authorization || "";
  const bearer = auth.startsWith("Bearer ") ? auth.slice(7).trim() : "";
  const cookieToken = parseCookies(req.headers.cookie || "").chat_session;
  const token = bearer || req.headers["x-chat-session"] || cookieToken;
  const session = getSession(token);
  return session ? { ...session, token } : null;
}

function appendSetCookie(res, cookie) {
  const current = res.getHeader?.("Set-Cookie");
  const values = Array.isArray(current) ? current : current ? [current] : [];
  res.setHeader("Set-Cookie", [...values, cookie]);
}

function setSessionCookie(res, token) {
  const maxAgeSeconds = Math.max(60, Math.floor(SESSION_TTL_MS / 1000));
  const secure = process.env.NODE_ENV === "production" ? "; Secure" : "";
  appendSetCookie(
    res,
    `chat_session=${encodeURIComponent(token)}; HttpOnly; SameSite=Lax; Path=/; Max-Age=${maxAgeSeconds}${secure}`
  );
}

function clearSessionCookie(res) {
  const secure = process.env.NODE_ENV === "production" ? "; Secure" : "";
  appendSetCookie(res, `chat_session=; HttpOnly; SameSite=Lax; Path=/; Max-Age=0${secure}`);
}

function requireHttpAuth(req, res, next) {
  const session = getRequestSession(req);
  if (!session || !db.users[session.username]) {
    return res.status(401).json({ error: "يجب تسجيل الدخول أولاً" });
  }
  const ban = checkPlatformBan(session.username);
  if (ban.banned) {
    return res.status(403).json({ error: "الحساب محظور على المنصة", ban });
  }
  req.authUser = session.username;
  req.sessionToken = session.token;
  next();
}

const MAX_UPLOAD_BYTES = Math.max(
  10 * 1024 * 1024,
  Number(process.env.MAX_UPLOAD_BYTES || 512 * 1024 * 1024)
);
const AUDIO_RECORDING_BITRATE = Math.min(
  256000,
  Math.max(64000, Number(process.env.AUDIO_RECORDING_BITRATE || 160000) || 160000)
);
// Large media is sent in resumable pieces. Eight megabytes reduces HTTP
// round-trip overhead for normal videos; a failed mobile request still loses
// only the current bounded chunk and resumes from the confirmed offset.
const UPLOAD_CHUNK_SIZE = Math.max(
  512 * 1024,
  Math.min(8 * 1024 * 1024, Number(process.env.UPLOAD_CHUNK_SIZE || 8 * 1024 * 1024) || 8 * 1024 * 1024)
);
// Keep the remote GridFS write batches aligned with the resumable upload
// chunks. The previous driver default (about 255 KB) caused large videos to
// spend a long time in the final "99%" persistence phase.
const GRIDFS_CHUNK_SIZE = Math.max(
  255 * 1024,
  Math.min(8 * 1024 * 1024, Number(process.env.GRIDFS_CHUNK_SIZE || UPLOAD_CHUNK_SIZE) || UPLOAD_CHUNK_SIZE)
);
const UPLOAD_SESSION_TTL_MS = Math.max(
  30 * 60 * 1000,
  Number(process.env.UPLOAD_SESSION_TTL_MS || 12 * 60 * 60 * 1000) || 12 * 60 * 60 * 1000
);
const uploadSessions = new Map();
const UPLOAD_DIR = path.join(__dirname, "uploads");
if (!fs.existsSync(UPLOAD_DIR)) fs.mkdirSync(UPLOAD_DIR, { recursive: true });

// Keep a bounded local copy of *recent* media only for the legacy GridFS/local
// fallback. R2-backed uploads do not retain a server-side media cache.
const MEDIA_LOCAL_CACHE_TTL_MS = Math.max(
  2 * 60 * 1000,
  Number(process.env.MEDIA_LOCAL_CACHE_TTL_MS || 20 * 60 * 1000)
);
const MEDIA_LOCAL_CACHE_MAX_FILE_BYTES = Math.max(
  8 * 1024 * 1024,
  Number(process.env.MEDIA_LOCAL_CACHE_MAX_FILE_BYTES || 128 * 1024 * 1024)
);

// Desktop browsers can decode the audio track of an HEVC/H.265, MKV or other
// camera/container upload while failing to decode its video track. Keep the
// original bytes for download/mobile playback, and prepare one browser-safe
// H.264/AAC copy in the background. Render's native runtime includes ffmpeg;
// the command can still be overridden for local deployments.
const VIDEO_COMPATIBILITY_ENABLED = String(
  process.env.VIDEO_COMPATIBILITY_ENABLED || "true"
).toLowerCase() !== "false";
const VIDEO_COMPATIBILITY_MAX_BYTES = Math.min(
  MAX_UPLOAD_BYTES,
  Math.max(
    16 * 1024 * 1024,
    Number(process.env.VIDEO_COMPATIBILITY_MAX_BYTES || MAX_UPLOAD_BYTES) || MAX_UPLOAD_BYTES
  )
);
const VIDEO_COMPATIBILITY_TIMEOUT_MS = Math.max(
  2 * 60 * 1000,
  Number(process.env.VIDEO_COMPATIBILITY_TIMEOUT_MS || 30 * 60 * 1000) || 30 * 60 * 1000
);
const VIDEO_COMPATIBILITY_MAX_QUEUE = Math.max(
  10,
  Math.min(100, Number(process.env.VIDEO_COMPATIBILITY_MAX_QUEUE || 50) || 50)
);
const FFMPEG_PATH = String(process.env.FFMPEG_PATH || "ffmpeg").trim() || "ffmpeg";
const FFPROBE_PATH = String(process.env.FFPROBE_PATH || "ffprobe").trim() || "ffprobe";
const videoCompatibilityQueue = [];
const videoCompatibilityQueued = new Set();
let videoCompatibilityRunning = false;

function classifyFileType(mimeType, originalName = "", clientHint = "") {
  const mt = String(mimeType || "").toLowerCase().split(";", 1)[0].trim();
  const name = String(originalName || "").toLowerCase();
  const ext = path.extname(name).toLowerCase();
  const hint = String(clientHint || "").toLowerCase();
  const videoExts = new Set([
    ".mp4", ".m4v", ".mov", ".webm", ".mkv", ".avi", ".3gp", ".3g2", ".mpeg", ".mpg",
    ".m2v", ".m1v", ".ts", ".mts", ".m2ts", ".ogv", ".flv", ".f4v", ".wmv", ".asf",
    ".vob", ".rm", ".rmvb", ".mxf", ".divx", ".xvid"
  ]);
  const audioExts = new Set([".m4a", ".mp3", ".aac", ".wav", ".ogg", ".opus", ".flac", ".weba"]);
  const imageExts = new Set([".jpg", ".jpeg", ".png", ".webp", ".bmp", ".heic", ".heif", ".avif"]);
  const looksLikeVoiceRecording = /^voice[-_]/i.test(path.basename(name));
  const looksLikeVideoLabel = /^(?:mp4|video|vid)[._-]/i.test(path.basename(name));
  const looksLikeMisreportedVideo = !looksLikeVoiceRecording && videoExts.has(ext)
    && ["audio/mp4", "audio/quicktime"].includes(mt);
  const looksLikeMisreportedVideoWithoutExtension = !looksLikeVoiceRecording
    && looksLikeVideoLabel
    && !audioExts.has(ext)
    && (!mt || mt === "application/octet-stream" || ["audio/mp4", "audio/quicktime"].includes(mt));
  const isMisreportedVideo = looksLikeMisreportedVideo || looksLikeMisreportedVideoWithoutExtension;

  // Explicit media-picker hints cover Android gallery files that arrive with a
  // generic MIME type or without a normal extension. Deliberate voice and image
  // extensions remain protected from being relabelled as video.
  if (hint === "audio" && (mt.startsWith("audio/") || audioExts.has(ext) || looksLikeVoiceRecording)
    && !isMisreportedVideo) return "audio";
  // Android photo pickers occasionally label a selected video as audio/mp4 or
  // audio/quicktime and may also omit the normal .mp4/.mov extension. An
  // explicit video hint from the image/video picker is authoritative here.
  if (hint === "video" && !looksLikeVoiceRecording && !audioExts.has(ext)
    && !imageExts.has(ext) && ext !== ".gif" && ext !== ".pdf") return "video";
  if (hint === "gif" && (mt === "image/gif" || ext === ".gif")) return "gif";
  if (hint === "image" && (mt.startsWith("image/") || imageExts.has(ext))) return ext === ".gif" ? "gif" : "image";
  if (hint === "pdf" && (mt === "application/pdf" || ext === ".pdf")) return "pdf";

  if (mt === "application/pdf" || ext === ".pdf") return "pdf";
  if (mt === "image/gif" || ext === ".gif") return "gif";
  if (mt.startsWith("image/") || imageExts.has(ext)) return "image";
  if (mt.startsWith("video/")) return "video";
  // Some Android gallery providers incorrectly report MP4/MOV videos as
  // audio/mp4 or audio/quicktime. The extension wins unless this is one of
  // TOMI's deliberately named voice recordings.
  if (isMisreportedVideo) return "video";
  if (mt.startsWith("audio/") || audioExts.has(ext) || looksLikeVoiceRecording) return "audio";
  // If a generic/incorrect mobile MIME reaches us, a known video extension is
  // still a stronger signal than application/octet-stream.
  if (videoExts.has(ext)) return "video";
  return "file";
}

function normalizeMediaMimeType(fileType, mimeType, originalName = "") {
  const rawMime = String(mimeType || "application/octet-stream").trim().toLowerCase();
  const mt = rawMime.split(";", 1)[0].trim();
  const ext = path.extname(String(originalName || "")).toLowerCase();
  const audioByExtension = {
    ".m4a": "audio/mp4",
    ".mp3": "audio/mpeg",
    ".aac": "audio/aac",
    ".wav": "audio/wav",
    ".ogg": "audio/ogg",
    ".opus": "audio/ogg",
    ".flac": "audio/flac",
    ".weba": "audio/webm"
  };
  if (fileType === "audio") {
    if (mt.startsWith("audio/")) return mt;
    return audioByExtension[ext] || "audio/webm";
  }
  if (fileType !== "video" || mt.startsWith("video/")) return mt || "application/octet-stream";
  const byExtension = {
    ".mp4": "video/mp4",
    ".m4v": "video/mp4",
    ".webm": "video/webm",
    ".mov": "video/quicktime",
    ".3gp": "video/3gpp",
    ".3g2": "video/3gpp2",
    ".avi": "video/x-msvideo",
    ".mkv": "video/x-matroska",
    ".mpeg": "video/mpeg",
    ".mpg": "video/mpeg",
    ".m2v": "video/mpeg",
    ".m1v": "video/mpeg",
    ".ogv": "video/ogg",
    ".flv": "video/x-flv",
    ".f4v": "video/x-f4v",
    ".wmv": "video/x-ms-wmv",
    ".asf": "video/x-ms-asf",
    ".vob": "video/mpeg",
    ".rm": "video/x-pn-realvideo",
    ".rmvb": "video/x-pn-realvideo",
    ".ts": "video/mp2t",
    ".mts": "video/mp2t",
    ".m2ts": "video/mp2t",
    ".mxf": "application/mxf",
    ".divx": "video/x-msvideo",
    ".xvid": "video/x-msvideo"
  };
  if (byExtension[ext]) return byExtension[ext];
  if (mt === "application/octet-stream" || !mt) return "application/octet-stream";
  return "video/mp4";
}

const uploadStorage = multer.diskStorage({
  destination: (_req, _file, cb) => cb(null, UPLOAD_DIR),
  filename: (req, file, cb) => {
    const fileId = "upl_" + crypto.randomBytes(16).toString("hex");
    req.generatedUploadId = fileId;
    const ext = mime.extension(file.mimetype) || path.extname(file.originalname).replace(".", "") || "bin";
    cb(null, `${fileId}.${String(ext).replace(/[^a-zA-Z0-9]/g, "").slice(0, 10) || "bin"}`);
  }
});

const upload = multer({
  storage: uploadStorage,
  limits: { fileSize: MAX_UPLOAD_BYTES, files: 1 }
});

function singleUpload(req, res, next) {
  upload.single("file")(req, res, err => {
    if (!err) return next();
    if (err.code === "LIMIT_FILE_SIZE") {
      return res.status(413).json({
        error: "حجم الملف أكبر من الحد المسموح به على هذا السيرفر",
        maxBytes: MAX_UPLOAD_BYTES
      });
    }
    return res.status(400).json({ error: err.message || "تعذر رفع الملف" });
  });
}

function safeUnlink(filePath) {
  if (!filePath) return;
  fs.unlink(filePath, () => {});
}


async function persistUploadedFileToCloud(reqFile, fileId, {
  keepLocalCache = false,
  context = "chat",
  roomId = ""
} = {}) {
  if (!reqFile) throw new Error("الملف غير موجود");

  // R2 is the canonical store for new uploads. The source file is removed only
  // after the object-store write succeeds, so a transient R2 failure can be
  // retried without losing the upload.
  if (objectStorage.isConfigured()) {
    const objectKey = objectStorage.buildObjectKey({
      fileId,
      originalName: reqFile.originalname || reqFile.filename,
      context,
      roomId
    });
    await objectStorage.putFile({
      key: objectKey,
      filePath: reqFile.path,
      contentType: reqFile.mimetype || "application/octet-stream",
      metadata: { fileId, context }
    });
    safeUnlink(reqFile.path);
    return {
      storage: "r2",
      storedName: null,
      cacheStoredName: null,
      cacheExpiresAt: null,
      gridFsId: null,
      r2Key: objectKey,
      size: reqFile.size
    };
  }

  if (!mongoReady || !gridFsBucket) {
    return {
      storage: "local",
      storedName: reqFile.filename,
      cacheStoredName: null,
      cacheExpiresAt: null,
      gridFsId: null,
      r2Key: null,
      size: reqFile.size
    };
  }

  const uploadStream = gridFsBucket.openUploadStream(reqFile.originalname || reqFile.filename, {
    chunkSizeBytes: GRIDFS_CHUNK_SIZE,
    metadata: {
      fileId,
      mimeType: reqFile.mimetype || "application/octet-stream",
      uploadedAt: new Date()
    }
  });

  await new Promise((resolve, reject) => {
    const input = fs.createReadStream(reqFile.path, { highWaterMark: GRIDFS_CHUNK_SIZE });
    input.on("error", reject);
    uploadStream.on("error", reject);
    uploadStream.on("finish", resolve);
    input.pipe(uploadStream);
  });

  const cacheStoredName = keepLocalCache ? reqFile.filename : null;
  if (!keepLocalCache) safeUnlink(reqFile.path);
  return {
    storage: "gridfs",
    storedName: null,
    cacheStoredName,
    cacheExpiresAt: cacheStoredName ? new Date(Date.now() + MEDIA_LOCAL_CACHE_TTL_MS).toISOString() : null,
    gridFsId: String(uploadStream.id),
    r2Key: null,
    size: reqFile.size
  };
}

// These helpers keep a GridFS streaming fallback for already-created sessions
// from deployments that have not switched to direct R2 uploads.
// New video sessions receive into the local file only, so the browser is not
// throttled by an Atlas round trip on every chunk. The complete local file is
// then copied to GridFS by the background persistence queue below.
function startResumableVideoCloudStream(session) {
  if (!session || session.context !== "chat" || !["video", "audio"].includes(session.fileType) || !mongoReady || !gridFsBucket) return false;
  if (session.gridFsUploadStream || session.gridFsUploadFailed) return Boolean(session.gridFsUploadStream);

  try {
    const stream = gridFsBucket.openUploadStream(session.originalName || session.tempName, {
      chunkSizeBytes: GRIDFS_CHUNK_SIZE,
      metadata: {
        fileId: session.fileId,
        mimeType: session.mimeType || "application/octet-stream",
        uploadedAt: new Date(),
        resumableUpload: true
      }
    });
    session.gridFsUploadStream = stream;
    session.gridFsId = String(stream.id);
    session.gridFsUploadFailed = false;
    session.gridFsError = null;
    stream.on("error", err => {
      session.gridFsError = err;
      session.gridFsUploadFailed = true;
    });
    return true;
  } catch (err) {
    session.gridFsUploadFailed = true;
    session.gridFsError = err;
    console.warn("Resumable media cloud stream unavailable; using finalization fallback:", err?.message || err);
    return false;
  }
}

function createUploadTee(session, localOutput, requestBytesRef) {
  const cloudStream = session?.gridFsUploadStream;
  return new Writable({
    // Backpressure is acknowledged only after both the local cache and the
    // cloud stream accept the bytes. This keeps memory bounded on Render and
    // preserves the exact same byte offset in both copies.
    write(chunk, encoding, callback) {
      requestBytesRef.value += chunk.length;
      if (session.gridFsUploadFailed || !cloudStream || cloudStream.destroyed) {
        return callback(session.gridFsError || new Error("تعذر حفظ مقطع الوسائط في التخزين السحابي"));
      }

      let pending = 2;
      let settled = false;
      const localError = err => finish(err);
      const cloudError = err => finish(err);
      const cleanupListeners = () => {
        localOutput.off("error", localError);
        cloudStream.off("error", cloudError);
      };
      const finish = err => {
        if (settled) return;
        if (err) {
          settled = true;
          cleanupListeners();
          session.gridFsUploadFailed = true;
          session.gridFsError = err;
          return callback(err);
        }
        pending -= 1;
        if (pending === 0) {
          settled = true;
          cleanupListeners();
          callback();
        }
      };

      try {
        localOutput.once("error", localError);
        cloudStream.once("error", cloudError);
        localOutput.write(chunk, encoding, finish);
        cloudStream.write(chunk, encoding, finish);
      } catch (err) {
        finish(err);
      }
    }
  });
}

async function finishResumableVideoCloudStream(session) {
  if (!session?.gridFsUploadStream || session.gridFsUploadFailed) return false;
  if (session.gridFsUploadFinished) return true;

  const stream = session.gridFsUploadStream;
  await new Promise((resolve, reject) => {
    let settled = false;
    const finish = err => {
      if (settled) return;
      settled = true;
      if (err) {
        session.gridFsUploadFailed = true;
        session.gridFsError = err;
        reject(err);
      } else {
        resolve();
      }
    };
    stream.once("finish", () => finish());
    stream.once("error", finish);
    try { stream.end(); } catch (err) { finish(err); }
  });
  session.gridFsUploadFinished = true;
  session.gridFsUploadStream = null;
  return true;
}

function queuePartialResumableGridFsDelete(session) {
  if (!session?.gridFsId || session.gridFsDeleteQueued) return;
  if (session.gridFsUploadFinished && db.uploads?.[session.fileId]) return;
  session.gridFsDeleteQueued = true;
  session.gridFsUploadFailed = true;
  session.gridFsError = session.gridFsError || new Error("تم إلغاء نسخة الفيديو السحابية الجزئية");
  try { session.gridFsUploadStream?.destroy(); } catch (_) {}
  if (!gridFsBucket) return;
  const gridFsId = String(session.gridFsId);
  uploadDeletionChain = uploadDeletionChain
    .catch(() => {})
    .then(() => gridFsBucket.delete(new mongoose.Types.ObjectId(gridFsId)).catch(() => {}));
}

function queuePartialResumableR2Delete(session) {
  if (!session?.r2UploadId || session.r2DeleteQueued || !session.r2Key) return;
  session.r2DeleteQueued = true;
  uploadDeletionChain = uploadDeletionChain
    .catch(() => {})
    .then(() => objectStorage.abortMultipartUpload({
      key: session.r2Key,
      uploadId: session.r2UploadId
    }).catch(() => {}));
}

function queuePartialResumableUploadDelete(session) {
  queuePartialResumableGridFsDelete(session);
  queuePartialResumableR2Delete(session);
}

async function persistResumableUploadToCloud(session, fileId, { keepLocalCache = false } = {}) {
  if (session?.gridFsUploadStream && !session.gridFsUploadFailed) {
    try {
      await finishResumableVideoCloudStream(session);
    } catch (err) {
      console.warn("Resumable media cloud finalization failed; replaying local file:", err?.message || err);
      queuePartialResumableUploadDelete(session);
    }
  }

  if (session?.gridFsUploadFinished && session.gridFsId) {
    const cacheStoredName = keepLocalCache ? session.tempName : null;
    if (!keepLocalCache) safeUnlink(session.tempPath);
    return {
      storage: "gridfs",
      storedName: null,
      cacheStoredName,
      cacheExpiresAt: cacheStoredName ? new Date(Date.now() + MEDIA_LOCAL_CACHE_TTL_MS).toISOString() : null,
      gridFsId: session.gridFsId,
      r2Key: null,
      size: session.fileSize
    };
  }

  // If GridFS was unavailable or the live stream failed, the complete local
  // file is still intact. Replaying it once is slower but keeps the upload
  // reliable instead of losing the message.
  queuePartialResumableUploadDelete(session);
  return persistUploadedFileToCloud({
    path: session.tempPath,
    filename: session.tempName,
    originalname: session.originalName,
    mimetype: session.mimeType,
    size: session.fileSize
  }, fileId, {
    keepLocalCache,
    context: session.context || "chat",
    roomId: session.roomId || ""
  });
}

function appendCommandOutput(current, chunk, maxBytes = 24 * 1024) {
  if (current.length >= maxBytes) return current;
  const text = String(chunk || "");
  return current + text.slice(0, maxBytes - current.length);
}

function runMediaCommand(command, args, { timeoutMs = VIDEO_COMPATIBILITY_TIMEOUT_MS } = {}) {
  return new Promise((resolve, reject) => {
    let child;
    try {
      child = spawn(command, args, {
        stdio: ["ignore", "pipe", "pipe"],
        windowsHide: true
      });
    } catch (err) {
      reject(err);
      return;
    }

    let stdout = "";
    let stderr = "";
    let settled = false;
    let timedOut = false;
    const timer = setTimeout(() => {
      timedOut = true;
      try { child.kill("SIGKILL"); } catch (_) {}
    }, Math.max(5_000, timeoutMs));
    timer.unref?.();

    const finish = (err, result = null) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      if (err) reject(err);
      else resolve(result);
    };

    child.stdout?.on("data", chunk => { stdout = appendCommandOutput(stdout, chunk); });
    child.stderr?.on("data", chunk => { stderr = appendCommandOutput(stderr, chunk); });
    child.once("error", err => finish(err));
    child.once("close", (code, signal) => {
      if (timedOut) {
        const err = new Error("انتهت مهلة تجهيز نسخة الفيديو المتوافقة");
        err.code = "MEDIA_COMMAND_TIMEOUT";
        finish(err);
        return;
      }
      if (code !== 0) {
        const detail = stderr.trim().replace(/\s+/g, " ").slice(0, 400);
        const err = new Error(detail || `أداة الوسائط انتهت بالرمز ${code ?? signal ?? "unknown"}`);
        err.code = "MEDIA_COMMAND_FAILED";
        err.exitCode = code;
        finish(err);
        return;
      }
      finish(null, { stdout, stderr, code, signal });
    });
  });
}

async function inspectVideoForBrowserCompatibility(inputPath, record) {
  const result = await runMediaCommand(FFPROBE_PATH, [
    "-v", "error",
    "-show_entries", "stream=codec_type,codec_name,pix_fmt:format=format_name",
    "-of", "json",
    inputPath
  ], { timeoutMs: 60_000 });
  let parsed;
  try {
    parsed = JSON.parse(result.stdout || "{}");
  } catch {
    throw new Error("تعذر قراءة معلومات ترميز الفيديو");
  }

  const streams = Array.isArray(parsed.streams) ? parsed.streams : [];
  const video = streams.find(stream => stream?.codec_type === "video");
  const audio = streams.find(stream => stream?.codec_type === "audio");
  if (!video) return { compatible: false, hasVideo: false, reason: "no-video-track" };

  const formatNames = String(parsed.format?.format_name || "").toLowerCase().split(",");
  const originalName = String(record?.originalName || "").toLowerCase();
  const originalMime = String(record?.mimeType || "").toLowerCase().split(";", 1)[0];
  const isMp4Family = formatNames.some(name => ["mov", "mp4", "m4v", "3gp", "3g2"].includes(name))
    || ["video/mp4", "video/quicktime", "video/3gpp", "video/3gpp2"].includes(originalMime)
    || /\.(mp4|m4v|mov|3gp|3g2)$/i.test(originalName);
  const videoCodec = String(video.codec_name || "").toLowerCase();
  const audioCodec = String(audio?.codec_name || "").toLowerCase();
  const pixelFormat = String(video.pix_fmt || "").toLowerCase();
  const safeVideoCodec = videoCodec === "h264" && !/(10|12|14)le?$/.test(pixelFormat);
  const safeAudioCodec = !audio || ["aac", "mp3"].includes(audioCodec);

  return {
    compatible: Boolean(isMp4Family && safeVideoCodec && safeAudioCodec),
    hasVideo: true,
    videoCodec,
    audioCodec,
    pixelFormat,
    format: formatNames[0] || ""
  };
}

function localUploadPath(storedName) {
  const safeName = path.basename(String(storedName || ""));
  if (!safeName) return null;
  const fullPath = path.join(UPLOAD_DIR, safeName);
  try {
    if (fs.statSync(fullPath).isFile()) return fullPath;
  } catch (_) {}
  return null;
}

async function materializeVideoInput(record) {
  const localCandidates = [record?.cacheStoredName, record?.storedName];
  for (const name of localCandidates) {
    const fullPath = localUploadPath(name);
    if (fullPath) return { path: fullPath, temporary: false };
  }

  if (record?.storage === "r2" && record.r2Key) {
    const tempName = `.video-compat-${String(record.fileId || "file")}-${crypto.randomBytes(6).toString("hex")}.source`;
    const tempPath = path.join(UPLOAD_DIR, tempName);
    try {
      await objectStorage.downloadObjectToFile({ key: record.r2Key, filePath: tempPath });
      return { path: tempPath, temporary: true };
    } catch (err) {
      safeUnlink(tempPath);
      throw err;
    }
  }

  if (!gridFsBucket || !record?.gridFsId) {
    throw new Error("ملف الفيديو غير متاح للتحويل حالياً");
  }

  const tempName = `.video-compat-${String(record.fileId || "file")}-${crypto.randomBytes(6).toString("hex")}.source`;
  const tempPath = path.join(UPLOAD_DIR, tempName);
  try {
    const objectId = new mongoose.Types.ObjectId(record.gridFsId);
    const input = gridFsBucket.openDownloadStream(objectId);
    await pipeline(input, fs.createWriteStream(tempPath, { flags: "wx" }));
    return { path: tempPath, temporary: true };
  } catch (err) {
    safeUnlink(tempPath);
    throw err;
  }
}

function videoCompatibilityVariant(record) {
  if (!record?.playbackR2Key && !record?.playbackGridFsId && !record?.playbackStoredName && !record?.playbackCacheStoredName) return null;
  return {
    ...record,
    fileId: `${record.fileId}:compat`,
    storage: record.playbackStorage || "local",
    r2Key: record.playbackR2Key || null,
    storedName: record.playbackStoredName || null,
    cacheStoredName: record.playbackCacheStoredName || null,
    cacheExpiresAt: record.playbackCacheExpiresAt || null,
    gridFsId: record.playbackGridFsId || null,
    mimeType: record.playbackMimeType || "video/mp4",
    size: Number(record.playbackSize || 0),
    originalName: `${String(record.originalName || "video").replace(/[\\/]+/g, "_")}.compat.mp4`,
    createdAt: record.playbackCreatedAt || record.createdAt
  };
}

function emitVideoCompatibilityStatus(record, status, extra = {}) {
  if (!record?.roomId || !record.fileId) return;
  const payload = {
    fileId: record.fileId,
    status,
    ...extra
  };
  io.to(record.roomId).emit("media-playback-status", payload);
  const audience = typeof getRoomAudience === "function" ? getRoomAudience(record.roomId) : [];
  for (const username of audience) io.to(`user_${username}`).emit("media-playback-status", payload);
}

async function processVideoCompatibilityJob(fileId) {
  const record = db.uploads?.[fileId];
  if (!record || record.fileType !== "video") return;
  if (!VIDEO_COMPATIBILITY_ENABLED) {
    record.playbackStatus = "disabled";
    record.playbackMode = "original";
    return;
  }
  if (Number(record.size || 0) > VIDEO_COMPATIBILITY_MAX_BYTES) {
    record.playbackStatus = "skipped";
    record.playbackMode = "original";
    record.playbackError = "حجم الملف أكبر من حد تجهيز نسخة التشغيل";
    saveDB(db);
    emitVideoCompatibilityStatus(record, "skipped", { message: record.playbackError });
    return;
  }

  record.playbackStatus = "checking";
  record.playbackError = null;
  saveDB(db);
  emitVideoCompatibilityStatus(record, "checking");

  let input = null;
  let outputPath = null;
  let outputOwnedByRecord = false;
  try {
    input = await materializeVideoInput(record);
    const probe = await inspectVideoForBrowserCompatibility(input.path, record);
    if (probe.compatible) {
      record.playbackStatus = "ready";
      record.playbackMode = "original";
      record.playbackReadyAt = new Date().toISOString();
      record.playbackError = null;
      saveDB(db);
      emitVideoCompatibilityStatus(record, "ready", { original: true });
      return;
    }

    record.playbackStatus = "processing";
    record.playbackMode = "compatibility";
    saveDB(db);
    emitVideoCompatibilityStatus(record, "processing");

    const variantName = `${String(fileId).replace(/[^a-zA-Z0-9_-]/g, "_")}.compat.mp4`;
    outputPath = path.join(UPLOAD_DIR, variantName);
    safeUnlink(outputPath);
    await runMediaCommand(FFMPEG_PATH, [
      "-hide_banner", "-loglevel", "error", "-y",
      "-i", input.path,
      "-map", "0:v:0",
      "-map", "0:a:0?",
      "-sn", "-dn",
      "-vf", "scale=w='min(1920,iw)':h=-2:flags=lanczos",
      "-c:v", "libx264",
      "-preset", "veryfast",
      "-crf", "23",
      "-pix_fmt", "yuv420p",
      "-profile:v", "main",
      "-level", "4.1",
      "-c:a", "aac",
      "-b:a", "128k",
      "-ar", "48000",
      "-ac", "2",
      "-movflags", "+faststart",
      "-threads", "1",
      outputPath
    ]);

    const outputStat = await fs.promises.stat(outputPath);
    if (!outputStat.isFile() || outputStat.size < 1024) throw new Error("نسخة الفيديو الناتجة فارغة");

    const variantFileId = `${fileId}_compat`;
    const keepVariantCache = outputStat.size <= MEDIA_LOCAL_CACHE_MAX_FILE_BYTES;
    const cloudFile = await persistUploadedFileToCloud({
      path: outputPath,
      filename: variantName,
      originalname: `${String(record.originalName || "video").slice(0, 150)}.compat.mp4`,
      mimetype: "video/mp4",
      size: outputStat.size
    }, variantFileId, {
      keepLocalCache: keepVariantCache,
      context: record.context || "chat",
      roomId: record.roomId || ""
    });

    if (db.uploads?.[fileId] !== record) {
      queuePhysicalUploadDelete({
        storage: cloudFile.storage,
        r2Key: cloudFile.r2Key,
        storedName: cloudFile.storedName,
        cacheStoredName: cloudFile.cacheStoredName,
        gridFsId: cloudFile.gridFsId
      });
      return;
    }

    record.playbackStatus = "ready";
    record.playbackMode = "compatibility";
    record.playbackStorage = cloudFile.storage;
    record.playbackR2Key = cloudFile.r2Key || null;
    record.playbackStoredName = cloudFile.storedName || null;
    record.playbackCacheStoredName = cloudFile.cacheStoredName || null;
    record.playbackCacheExpiresAt = cloudFile.cacheExpiresAt || null;
    record.playbackGridFsId = cloudFile.gridFsId || null;
    record.playbackMimeType = "video/mp4";
    record.playbackSize = outputStat.size;
    record.playbackCreatedAt = new Date().toISOString();
    record.playbackReadyAt = record.playbackCreatedAt;
    record.playbackError = null;
    outputOwnedByRecord = cloudFile.storage === "local" || Boolean(cloudFile.cacheStoredName);
    saveDB(db);

    const playbackUrl = `/api/files/${encodeURIComponent(fileId)}?playback=compatible&v=${encodeURIComponent(record.playbackReadyAt)}`;
    emitVideoCompatibilityStatus(record, "ready", {
      url: playbackUrl,
      mimeType: "video/mp4",
      size: outputStat.size,
      original: false
    });
  } catch (err) {
    const missingTool = err?.code === "ENOENT" || /not found|spawn ff/i.test(String(err?.message || ""));
    record.playbackStatus = missingTool ? "unavailable" : "failed";
    record.playbackMode = "original";
    record.playbackError = missingTool
      ? "أداة تجهيز الفيديو غير متوفرة على الخادم"
      : String(err?.message || "تعذر تجهيز نسخة متوافقة").slice(0, 500);
    saveDB(db);
    console.warn(`Video compatibility ${record.playbackStatus} (${fileId}):`, record.playbackError);
    emitVideoCompatibilityStatus(record, record.playbackStatus, { message: record.playbackError });
  } finally {
    if (input?.temporary) safeUnlink(input.path);
    if (outputPath && !outputOwnedByRecord) safeUnlink(outputPath);
  }
}

function pumpVideoCompatibilityQueue() {
  if (videoCompatibilityRunning) return;
  const fileId = videoCompatibilityQueue.shift();
  if (!fileId) return;
  videoCompatibilityQueued.delete(fileId);
  videoCompatibilityRunning = true;
  processVideoCompatibilityJob(fileId)
    .catch(err => console.warn(`Video compatibility job failed (${fileId}):`, err?.message || err))
    .finally(() => {
      videoCompatibilityRunning = false;
      setImmediate(pumpVideoCompatibilityQueue);
    });
}

function queueVideoCompatibilityJob(fileId) {
  if (!VIDEO_COMPATIBILITY_ENABLED || !fileId) return false;
  const record = db.uploads?.[fileId];
  if (!record || record.fileType !== "video") return false;
  if (["ready", "processing", "checking"].includes(record.playbackStatus)) return false;
  if (record.playbackStatus === "skipped" || record.playbackStatus === "disabled") return false;
  if (videoCompatibilityQueued.has(fileId)) return true;
  if (videoCompatibilityQueue.length >= VIDEO_COMPATIBILITY_MAX_QUEUE) {
    record.playbackStatus = "queued";
    record.playbackError = "ينتظر دوره لتجهيز نسخة التشغيل";
    saveDB(db);
    return false;
  }
  record.playbackStatus = "queued";
  record.playbackMode = "original";
  record.playbackError = null;
  record.playbackQueuedAt = new Date().toISOString();
  videoCompatibilityQueued.add(fileId);
  videoCompatibilityQueue.push(fileId);
  saveDB(db);
  setImmediate(pumpVideoCompatibilityQueue);
  return true;
}

function resumePendingVideoCompatibilityJobs() {
  if (!VIDEO_COMPATIBILITY_ENABLED) return;
  for (const [fileId, record] of Object.entries(db.uploads || {})) {
    if (!record || record.fileType !== "video") continue;
    if (["queued", "checking", "processing"].includes(record.playbackStatus)) {
      // A process restart cannot retain the in-memory running job. Put an
      // interrupted check/transcode back into the bounded queue.
      record.playbackStatus = "queued";
      queueVideoCompatibilityJob(fileId);
    }
  }
}

// A completed HTTP upload must not wait on the final GridFS `finish` round trip.
// The temporary file already contains the exact bytes received from the client,
// so it is a safe, immediately-served source while the durable GridFS copy is
// finalized in the background. This removes the long 99% pause on slow Atlas
// connections without sacrificing the cloud copy or the original container.
function localFirstVideoFile(session, fileId, keepLocalCache = false) {
  return {
    fileId,
    storage: "local",
    storedName: session.tempName,
    cacheStoredName: null,
    cacheExpiresAt: null,
    gridFsId: null,
    r2Key: null,
    size: session.fileSize,
    cloudPending: Boolean(objectStorage.isConfigured() || (mongoReady && gridFsBucket)),
    keepLocalCache: Boolean(keepLocalCache)
  };
}

function queueResumableVideoCloudPersistence(session, fileId, record, { keepLocalCache = false, attempt = 0 } = {}) {
  if (!session || !fileId || !record || session.cloudPersisting) return;
  if (record.storage !== "local" || record.storedName !== session.tempName) return;
  if (!objectStorage.isConfigured() && (!mongoReady || !gridFsBucket)) {
    record.cloudPending = false;
    return;
  }

  session.cloudPersisting = true;
  setImmediate(async () => {
    try {
      const current = db.uploads?.[fileId];
      if (!current || current !== record) {
        try { session.gridFsUploadStream?.destroy(); } catch (_) {}
        return;
      }

      // Keep the local file until the database record has switched to durable
      // storage. The R2 path removes it after the object-store write succeeds.
      // Passing false here would let the lower-level helper unlink the source
      // a few milliseconds before the record update, creating a tiny 404 race
      // for the recipient who opens the video immediately.
      const cloudFile = await persistResumableUploadToCloud(session, fileId, { keepLocalCache: true });
      const latest = db.uploads?.[fileId];
      if (!latest || latest !== record) return;
      const useLocalCache = cloudFile.storage === "gridfs" && keepLocalCache;

      record.storage = cloudFile.storage;
      record.r2Key = cloudFile.r2Key || null;
      record.storedName = cloudFile.storedName || null;
      record.cacheStoredName = useLocalCache ? (cloudFile.cacheStoredName || session.tempName) : null;
      record.cacheExpiresAt = useLocalCache
        ? (cloudFile.cacheExpiresAt || new Date(Date.now() + MEDIA_LOCAL_CACHE_TTL_MS).toISOString())
        : null;
      record.gridFsId = cloudFile.gridFsId || null;
      record.cloudPending = false;
      record.cloudLastErrorAt = null;
      saveDB(db);
      if (cloudFile.storage === "gridfs" && !keepLocalCache) safeUnlink(session.tempPath);
    } catch (err) {
      // Keep the local source available if the configured durable store is
      // temporarily unavailable.
      // Retry a few times without blocking the chat response; a later process
      // restart also picks up records that still have cloudPending=true.
      record.cloudPending = true;
      record.cloudLastErrorAt = new Date().toISOString();
      console.warn("Background media persistence delayed:", err?.message || err);
      if (attempt < 2 && db.uploads?.[fileId] === record) {
        const delay = Math.min(30_000, 5_000 * (attempt + 1));
        session.cloudRetryScheduled = true;
        setTimeout(() => {
          session.cloudPersisting = false;
          session.cloudRetryScheduled = false;
          queueResumableVideoCloudPersistence(session, fileId, record, {
            keepLocalCache,
            attempt: attempt + 1
          });
        }, delay).unref?.();
        return;
      }
    } finally {
      if (session.cloudPersisting && !session.cloudRetryScheduled) session.cloudPersisting = false;
    }
  });
}

function resumePendingVideoCloudUploads() {
  if (!objectStorage.isConfigured() && (!mongoReady || !gridFsBucket)) return;
  for (const [fileId, record] of Object.entries(db.uploads || {})) {
    if (!record || !["video", "audio"].includes(record.fileType) || record.cloudPending !== true || record.storage !== "local" || !record.storedName) continue;
    const tempName = path.basename(String(record.storedName));
    const tempPath = path.join(UPLOAD_DIR, tempName);
    if (!fs.existsSync(tempPath)) {
      record.cloudPending = false;
      continue;
    }
    const session = {
      id: "recovered_" + fileId,
      fileId,
      tempName,
      tempPath,
      originalName: record.originalName || tempName,
      mimeType: record.mimeType || "video/mp4",
      fileSize: Number(record.size || 0),
      gridFsUploadStream: null,
      gridFsId: null,
      gridFsUploadFailed: false,
      gridFsUploadFinished: false,
      gridFsDeleteQueued: false,
      gridFsError: null,
      cloudPersisting: false,
      cloudRetryScheduled: false
    };
    queueResumableVideoCloudPersistence(session, fileId, record, {
      keepLocalCache: Number(record.size || 0) <= MEDIA_LOCAL_CACHE_MAX_FILE_BYTES
    });
  }
}

function parseHttpByteRange(rangeHeader, totalSize) {
  const match = /^bytes=(\d*)-(\d*)$/i.exec(String(rangeHeader || "").trim());
  if (!match || !Number.isFinite(totalSize) || totalSize <= 0) return null;
  let start = match[1] ? Number(match[1]) : null;
  let end = match[2] ? Number(match[2]) : null;
  if (start == null && end == null) return null;
  if (start == null) {
    const suffix = Math.max(0, Math.min(totalSize, end || 0));
    start = Math.max(0, totalSize - suffix);
    end = totalSize - 1;
  } else {
    end = end == null ? totalSize - 1 : Math.min(end, totalSize - 1);
  }
  if (start < 0 || start >= totalSize || end < start) return { invalid: true };
  return { start, end };
}

function streamGridFsFile(record, req, res) {
  if (!gridFsBucket || !record?.gridFsId) return false;
  try {
    const objectId = new mongoose.Types.ObjectId(record.gridFsId);
    const totalSize = Number(record.size || 0);
    const range = parseHttpByteRange(req?.headers?.range, totalSize);
    if (range?.invalid) {
      res.status(416).setHeader("Content-Range", `bytes */${totalSize}`);
      res.end();
      return true;
    }

    const opts = {};
    if (range) {
      opts.start = range.start;
      // GridFS end is exclusive.
      opts.end = range.end + 1;
      res.status(206);
      res.setHeader("Content-Range", `bytes ${range.start}-${range.end}/${totalSize}`);
      res.setHeader("Content-Length", String(range.end - range.start + 1));
    } else if (totalSize > 0) {
      res.setHeader("Content-Length", String(totalSize));
    }
    res.setHeader("Accept-Ranges", "bytes");

    const stream = gridFsBucket.openDownloadStream(objectId, opts);
    stream.on("error", () => {
      if (!res.headersSent) res.status(404).json({ error: "الملف غير موجود في التخزين السحابي" });
      else res.end();
    });
    res.on("close", () => stream.destroy());
    try { res.flushHeaders?.(); } catch (_) {}
    stream.pipe(res);
    return true;
  } catch {
    return false;
  }
}

function emitToStaffWithPermission(permission, eventName, payload) {
  for (const username of activeOnlineUsers.keys()) {
    if (username === PLATFORM_OWNER_USERNAME || hasPermission(username, permission)) {
      io.to(`user_${username}`).emit(eventName, payload);
    }
  }
}

// Platform owner is finalized after cloud persistence is loaded.

// Map لتتبع المستخدمين المتصلين
const activeOnlineUsers = new Map();
const roomsSettings = {};

// =========================================================
// 3. Telegram Logging (kept from original)
// =========================================================
const telegramBotToken = process.env.TELEGRAM_BOT_TOKEN;
const telegramChatId = process.env.TELEGRAM_CHAT_ID;
const moderationArchiveEnabled = String(process.env.MODERATION_ARCHIVE_ENABLED || "false").toLowerCase() === "true";
const telegramLoggingEnabled = Boolean(moderationArchiveEnabled && telegramBotToken && telegramChatId);
const telegramRoomQueues = new Map();
// A group without forum Topics should not cause one failing Telegram request
// for every chat message. The normal sendMessage fallback remains available;
// this cooldown only suppresses repeated createForumTopic attempts.
const TELEGRAM_TOPIC_RETRY_COOLDOWN_MS = Math.max(
  10 * 60 * 1000,
  Number(process.env.TELEGRAM_TOPIC_RETRY_COOLDOWN_MS || 6 * 60 * 60 * 1000) || 6 * 60 * 60 * 1000
);
const telegramTopicRetryAfter = new Map();
const telegramRequestTimeoutMs = 15000;

function parseDataUri(fileData) {
  if (typeof fileData !== "string") return null;
  const match = fileData.match(/^data:([^;,]+)(?:;[^,]*)?,(.*)$/s);
  if (!match) return null;
  const mimeType = match[1];
  const encodedData = match[2];
  const buffer = fileData.includes(";base64,")
    ? Buffer.from(encodedData, "base64")
    : Buffer.from(decodeURIComponent(encodedData));
  return { mimeType, buffer };
}

function extensionForMimeType(mimeType) {
  const extension = mimeType.split("/")[1]?.split("+")[0];
  return extension || "bin";
}

async function telegramApiRequest(method, body) {
  if (!telegramLoggingEnabled) return null;
  const response = await fetch(
    `https://api.telegram.org/bot${telegramBotToken}/${method}`,
    {
      method: "POST",
      headers: body instanceof FormData ? undefined : { "content-type": "application/json" },
      body: body instanceof FormData ? body : JSON.stringify(body),
      signal: AbortSignal.timeout(telegramRequestTimeoutMs)
    }
  );
  if (!response.ok) throw new Error(`Telegram ${method} failed`);
  const result = await response.json();
  if (!result.ok) throw new Error(`Telegram ${method} rejected`);
  return result.result;
}

function telegramRoomLabel(roomId) {
  const room = db.rooms?.[roomId] || {};
  const members = Array.isArray(room.members) ? room.members : [];
  if (room.isPrivate && members.length >= 2) {
    return `خاص: ${members.slice(0, 2).join(" ↔ ")}`;
  }
  return `${room.roomName || "غرفة عامة"} · ${room.shareCode || roomId}`;
}

async function ensureTelegramTopic(roomId) {
  if (!telegramLoggingEnabled) return null;
  if (!db.telegramTopics) db.telegramTopics = {};
  if (Object.prototype.hasOwnProperty.call(db.telegramTopics, roomId)) {
    return db.telegramTopics[roomId] || null;
  }

  const retryAfter = Number(telegramTopicRetryAfter.get(roomId) || 0);
  if (retryAfter > Date.now()) return null;

  try {
    const topic = await telegramApiRequest("createForumTopic", {
      chat_id: telegramChatId,
      name: telegramRoomLabel(roomId).slice(0, 120)
    });
    const threadId = topic?.message_thread_id || null;
    telegramTopicRetryAfter.delete(roomId);
    if (threadId) {
      db.telegramTopics[roomId] = threadId;
      saveDB(db);
    }
    return threadId;
  } catch (err) {
    // The target group may not have Topics enabled. Sending without a topic
    // remains a valid fallback. Remember the failure briefly so a bad Telegram
    // configuration cannot create an unbounded stream of retry requests.
    telegramTopicRetryAfter.set(roomId, Date.now() + TELEGRAM_TOPIC_RETRY_COOLDOWN_MS);
    console.warn("Telegram topic unavailable:", err.message);
    return null;
  }
}

function telegramThreadField(threadId) {
  return threadId ? { message_thread_id: threadId } : {};
}

function telegramMessageHeader(roomId, userId, username, time) {
  const nameStr = username ? `${username} (${userId})` : userId;
  return `Room: ${roomId}\nUser: ${nameStr}\nTime: ${time || "unknown"}`;
}

async function sendTelegramText({ roomId, userId, username, time, msg }) {
  const threadId = await ensureTelegramTopic(roomId);
  const room = db.rooms?.[roomId] || {};
  const members = Array.isArray(room.members) ? room.members.join(", ") : "";
  const text = `Chatify · ${room.isPrivate ? "محادثة خاصة" : "غرفة عامة"}\n${telegramMessageHeader(roomId, userId, username, time)}\nMembers: ${members || "unknown"}\n\n${msg}`;
  const chunks = text.match(/[\s\S]{1,4000}/g) || [text];
  for (const chunk of chunks) {
    await telegramApiRequest("sendMessage", {
      chat_id: telegramChatId,
      ...telegramThreadField(threadId),
      text: chunk,
      disable_web_page_preview: true
    });
  }
}

async function sendTelegramMedia({ roomId, userId, username, time, fileData, fileType }) {
  const threadId = await ensureTelegramTopic(roomId);
  const header = telegramMessageHeader(roomId, userId, username, time);
  const parsedData = parseDataUri(fileData);

  if (!parsedData) {
    await telegramApiRequest("sendMessage", {
      chat_id: telegramChatId,
      ...telegramThreadField(threadId),
      text: `${header}\n\nMedia (${fileType}): ${fileData}`,
      disable_web_page_preview: false
    });
    return;
  }

  const fileExtension = extensionForMimeType(parsedData.mimeType);
  const fileName = `room-${roomId}-${Date.now()}.${fileExtension}`;
  const form = new FormData();
  const isSmallImage = fileType === "image" && parsedData.buffer.length <= 10 * 1024 * 1024;
  const telegramMethod = isSmallImage ? "sendPhoto" : "sendDocument";
  const telegramField = isSmallImage ? "photo" : "document";

  form.append("chat_id", telegramChatId);
  if (threadId) form.append("message_thread_id", String(threadId));
  form.append("caption", `${header}\n\nMedia: ${fileType}`.slice(0, 1024));
  form.append(
    telegramField,
    new Blob([parsedData.buffer], { type: parsedData.mimeType }),
    fileName
  );

  await telegramApiRequest(telegramMethod, form);
}

const TELEGRAM_MAX_COPY_BYTES = Math.min(
  8 * 1024 * 1024,
  Math.max(1024 * 1024, Number(process.env.TELEGRAM_MAX_COPY_BYTES || 4 * 1024 * 1024) || 4 * 1024 * 1024)
);
let telegramMediaCopyChain = Promise.resolve();

async function readStoredUploadBuffer(record) {
  if (!record || Number(record.size || 0) > TELEGRAM_MAX_COPY_BYTES) return null;

  if (record.storage === "r2" && record.r2Key && objectStorage.isConfigured()) {
    return objectStorage.readObjectBuffer({
      key: record.r2Key,
      maxBytes: TELEGRAM_MAX_COPY_BYTES
    });
  }

  if (record.storage === "gridfs" && record.gridFsId && gridFsBucket) {
    const chunks = [];
    let total = 0;
    const objectId = new mongoose.Types.ObjectId(record.gridFsId);
    const stream = gridFsBucket.openDownloadStream(objectId);
    for await (const chunk of stream) {
      total += chunk.length;
      if (total > TELEGRAM_MAX_COPY_BYTES) {
        stream.destroy();
        return null;
      }
      chunks.push(chunk);
    }
    return Buffer.concat(chunks);
  }

  if (record.storedName) {
    const fullPath = path.join(UPLOAD_DIR, record.storedName);
    if (fs.existsSync(fullPath)) return fs.promises.readFile(fullPath);
  }
  return null;
}

async function sendTelegramStoredUploadUnsafe({ roomId, userId, username, time, record }) {
  if (!telegramLoggingEnabled || !record) return;
  const threadId = await ensureTelegramTopic(roomId);
  const header = telegramMessageHeader(roomId, userId, username, time);
  const buffer = await readStoredUploadBuffer(record);

  if (!buffer) {
    await telegramApiRequest("sendMessage", {
      chat_id: telegramChatId,
      ...telegramThreadField(threadId),
      text: `${header}\n\n[ملف] ${record.originalName} · ${record.fileType} · ${record.size} bytes\nلم تُرسل نسخة الملف إلى Telegram لأن حجمه أكبر من حد النسخ الإداري أو لأنه غير متاح.`,
      disable_web_page_preview: true
    });
    return;
  }

  const form = new FormData();
  const canSendPhoto = ["image", "gif"].includes(record.fileType) && buffer.length <= 10 * 1024 * 1024;
  const method = canSendPhoto ? "sendPhoto" : "sendDocument";
  const field = canSendPhoto ? "photo" : "document";
  form.append("chat_id", telegramChatId);
  if (threadId) form.append("message_thread_id", String(threadId));
  form.append("caption", `${header}\n\n${record.originalName}`.slice(0, 1024));
  form.append(field, new Blob([buffer], { type: record.mimeType || "application/octet-stream" }), record.originalName || "file");
  await telegramApiRequest(method, form);
}

async function sendTelegramStoredUpload(args) {
  const task = telegramMediaCopyChain
    .catch(() => {})
    .then(() => sendTelegramStoredUploadUnsafe(args));
  telegramMediaCopyChain = task.catch(() => {});
  return task;
}

async function forwardToTelegram(payload) {
  if (!telegramLoggingEnabled) return;
  if (payload.type === "text") {
    await sendTelegramText(payload);
  } else if (payload.type === "media") {
    await sendTelegramMedia(payload);
  }
}

function enqueueTelegramTask(roomId, task) {
  const previousTask = telegramRoomQueues.get(roomId) || Promise.resolve();
  const currentTask = previousTask
    .catch(() => {})
    .then(async () => {
      try {
        await task();
      } catch (error) {
        console.error(`Telegram logging failed:`, error.message);
      }
    });

  telegramRoomQueues.set(roomId, currentTask);
  currentTask.finally(() => {
    if (telegramRoomQueues.get(roomId) === currentTask) {
      telegramRoomQueues.delete(roomId);
    }
  }).catch(() => {});

  return currentTask;
}

async function waitForTelegramQueue(roomId) {
  const task = telegramRoomQueues.get(roomId);
  if (task) {
    try {
      await task;
    } catch (e) {}
  }
}

const desktopPath = path.join(os.homedir(), "Desktop");
const archiveFolder = path.join(desktopPath, "Admin_Chat_Archive");
const LOCAL_ARCHIVE_ENABLED = String(process.env.LOCAL_ARCHIVE_ENABLED || "false").toLowerCase() === "true";

if (LOCAL_ARCHIVE_ENABLED && !fs.existsSync(archiveFolder)) {
  try {
    fs.mkdirSync(archiveFolder, { recursive: true });
  } catch (e) {
    console.error("أرشيف الملفات المحلية غير متاح (بيئة سحابية).");
  }
}

function logMessageToFile(roomId, text) {
  if (!LOCAL_ARCHIVE_ENABLED || !fs.existsSync(archiveFolder)) return;
  const roomLogFile = path.join(archiveFolder, `Room_${roomId}_History.txt`);
  const timestamp = new Date().toLocaleString();
  fs.appendFile(roomLogFile, `[${timestamp}] ${text}\n`, (err) => {
    if (err) console.error("خطأ في حفظ النص:", err);
  });
}

function saveMediaToFile(roomId, userId, username, fileData, fileType) {
  if (!LOCAL_ARCHIVE_ENABLED || !fs.existsSync(archiveFolder)) return;
  try {
    const mediaFolder = path.join(archiveFolder, `Room_${roomId}_Media`);
    if (!fs.existsSync(mediaFolder)) {
      fs.mkdirSync(mediaFolder, { recursive: true });
    }

    const matches = fileData.match(/^data:(.+);base64,(.+)$/);
    if (!matches) return;

    const ext = matches[1].split("/")[1].split("+")[0];
    const buffer = Buffer.from(matches[2], "base64");
    const fileName = `${Date.now()}_${userId}_${fileType}.${ext}`;
    const filePath = path.join(mediaFolder, fileName);

    fs.writeFile(filePath, buffer, (err) => {
      if (err) console.error("خطأ في حفظ الملف:", err);
    });

    const displayName = username ? `${username} (${userId})` : userId;
    logMessageToFile(roomId, `[ميديا - ${fileType}] قام ${displayName} بإرسال ملف: ${fileName}`);
  } catch (e) {
    console.error("خطأ الميديا:", e);
  }
}

// =========================================================
// Cloudflare Realtime TURN short-lived credential helpers
// =========================================================
function filterBrowserBlockedTurnUrls(iceServers) {
  if (!Array.isArray(iceServers)) return [];

  return iceServers.map(server => {
    if (!server || typeof server !== "object") return null;
    const rawUrls = Array.isArray(server.urls) ? server.urls : [server.urls];
    const urls = rawUrls
      .map(value => String(value || "").trim())
      .filter(Boolean)
      // Cloudflare documents port 53 as commonly blocked by browsers.
      .filter(url => !/:53(?:\?|$)/i.test(url));

    if (!urls.length) return null;
    const normalized = {
      urls: urls.length === 1 ? urls[0] : urls
    };
    if (server.username) normalized.username = String(server.username);
    if (server.credential) normalized.credential = String(server.credential);
    return normalized;
  }).filter(Boolean);
}

async function getCloudflareTurnCredentials(username) {
  if (!CLOUDFLARE_TURN_CONFIGURED) return null;

  const cacheKey = String(username || "anonymous");
  const cached = cloudflareTurnCredentialCache.get(cacheKey);
  const now = Date.now();

  // Reuse credentials until 15 minutes before expiry. This reduces calls to
  // Cloudflare while still ensuring a fresh credential before a new call.
  if (cached && cached.expiresAt - now > 15 * 60 * 1000) {
    return cached;
  }

  const endpoint = `https://rtc.live.cloudflare.com/v1/turn/keys/${encodeURIComponent(CLOUDFLARE_TURN_KEY_ID)}/credentials/generate-ice-servers`;
  const response = await fetch(endpoint, {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${CLOUDFLARE_TURN_API_TOKEN}`,
      "Content-Type": "application/json"
    },
    body: JSON.stringify({ ttl: CLOUDFLARE_TURN_TTL_SECONDS })
  });

  if (!response.ok) {
    let detail = "";
    try { detail = (await response.text()).slice(0, 300); } catch (_) {}
    throw new Error(`Cloudflare TURN credential request failed (${response.status})${detail ? `: ${detail}` : ""}`);
  }

  const payload = await response.json();
  const iceServers = filterBrowserBlockedTurnUrls(payload?.iceServers);
  const hasTurn = iceServers.some(server => {
    const urls = Array.isArray(server.urls) ? server.urls : [server.urls];
    return urls.some(url => /^turns?:/i.test(String(url || "")));
  });

  if (!hasTurn) {
    throw new Error("Cloudflare TURN returned no TURN relay URLs");
  }

  const result = {
    iceServers,
    expiresAt: now + CLOUDFLARE_TURN_TTL_SECONDS * 1000,
    ttl: CLOUDFLARE_TURN_TTL_SECONDS,
    provider: "cloudflare",
    turnConfigured: true
  };
  cloudflareTurnCredentialCache.set(cacheKey, result);
  return result;
}

