// 📝 API: Register
app.post("/api/register", authLimiter, (req, res) => {
  try {
    const { username, password, displayName } = req.body;
    const referralCode = String(req.body?.refCode || parseCookies(req.headers.cookie || "").tomi_ref || "").slice(0, 40);
    const uVal = validateUsername(username);
    if (!uVal.valid) return res.status(400).json({ error: uVal.error });

    const pVal = validatePassword(password);
    if (!pVal.valid) return res.status(400).json({ error: pVal.error });

    if (db.users[uVal.username]) {
      return res.status(409).json({ error: "اسم المستخدم موجود مسبقاً" });
    }

    db.users[uVal.username] = {
      username: uVal.username,
      password: hashPassword(password),
      role: "user",
      displayName: (displayName || uVal.username).trim().slice(0, 60),
      staffApproved: false,
      permissions: [],
      registeredAt: new Date().toISOString(),
      status: "online",
      lastSeen: new Date().toISOString()
    };
    analyticsService?.track("register", {
      userId: uVal.username,
      refCode: referralCode,
      page: "/login.html",
      visitorId: req.analytics?.visitorId,
      sessionId: req.analytics?.sessionId,
      deviceType: req.analytics?.device?.deviceType,
      browser: req.analytics?.device?.browser,
      os: req.analytics?.device?.os
    });
    saveDB(db);

    const sessionToken = issueSession(uVal.username);
    setSessionCookie(res, sessionToken);
    analyticsService?.clearReferralCookie(res);

    res.json({
      success: true,
      username: uVal.username,
      role: "user",
      displayName: db.users[uVal.username].displayName,
      badge: null,
      permissions: [],
      avatar: db.users[uVal.username].avatar || "",
      frame: getActiveFrame(uVal.username),
      referralCode: db.users[uVal.username].referralCode || "",
      sessionToken,
      message: "تم إنشاء الحساب بنجاح"
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// 🔐 API: Login
app.post("/api/login", authLimiter, (req, res) => {
  try {
    const { username, password } = req.body;
    if (!username || !password) {
      return res.status(400).json({ error: "بيانات غير كاملة" });
    }

    const cleanUsername = username.trim();
    const user = db.users[cleanUsername];
    if (!user || !verifyPassword(password, user.password)) {
      return res.status(401).json({ error: "اسم المستخدم أو كلمة المرور غير صحيحة" });
    }

    const platformBan = checkPlatformBan(cleanUsername);
    if (platformBan.banned) {
      return res.status(403).json({ error: "هذا الحساب محظور على المنصة", ban: platformBan });
    }

    upgradePasswordHashIfNeeded(user, password);
    user.lastSeen = new Date().toISOString();
    user.status = "online";
    analyticsService?.track("login", {
      userId: cleanUsername,
      page: "/login.html",
      visitorId: req.analytics?.visitorId,
      sessionId: req.analytics?.sessionId,
      deviceType: req.analytics?.device?.deviceType,
      browser: req.analytics?.device?.browser,
      os: req.analytics?.device?.os
    });
    saveDB(db);

    const sessionToken = issueSession(cleanUsername);
    setSessionCookie(res, sessionToken);

    res.json({
      success: true,
      username: user.username,
      role: getPublicRole(user.username),
      displayName: user.displayName,
      badge: getPlatformBadge(user.username),
      permissions: getUserPermissions(user.username),
      avatar: user.avatar || "",
      frame: getActiveFrame(user.username),
      referralCode: user.referralCode || "",
      sessionToken
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

