app.get("/api/client-config", requireHttpAuth, (_req, res) => {
  const turnUrl = process.env.TURN_URL || "";
  const turnUsername = process.env.TURN_USERNAME || "";
  const turnCredential = process.env.TURN_CREDENTIAL || "";
  const iceServers = [{ urls: ["stun:stun.cloudflare.com:3478", "stun:stun.l.google.com:19302", "stun:stun1.l.google.com:19302"] }];
  const turnUrls = String(turnUrl || "")
    .split(",")
    .map(value => value.trim())
    .filter(Boolean);
  const staticTurnConfigured = Boolean(turnUrls.length && turnUsername && turnCredential);
  if (staticTurnConfigured) {
    iceServers.push({
      urls: turnUrls.length === 1 ? turnUrls[0] : turnUrls,
      username: turnUsername,
      credential: turnCredential
    });
  }

  res.json({
    maxUploadBytes: MAX_UPLOAD_BYTES,
    uploadChunkSize: UPLOAD_CHUNK_SIZE,
    resumableUploads: true,
    directObjectStorage: objectStorage.isConfigured(),
    objectStorageProvider: objectStorage.isConfigured() ? "cloudflare-r2" : null,
    objectStoragePartSize: objectStorage.isConfigured() ? objectStorage.getPartSize() : null,
    audioRecording: {
      preferredMimeType: "audio/webm;codecs=opus",
      audioBitsPerSecond: AUDIO_RECORDING_BITRATE,
      sampleRate: 48000,
      sampleSize: 16,
      channelCount: 1,
      echoCancellation: true,
      noiseSuppression: true,
      autoGainControl: true
    },
    webrtc: {
      iceServers,
      // Static TURN is already usable. Cloudflare TURN is fetched dynamically
      // immediately before calls so its long-lived key never reaches browsers.
      turnConfigured: staticTurnConfigured,
      cloudflareTurnConfigured: CLOUDFLARE_TURN_CONFIGURED,
      turnProvider: CLOUDFLARE_TURN_CONFIGURED ? "cloudflare" : (staticTurnConfigured ? "static" : "none"),
      iceTransportPolicy: String(process.env.FORCE_TURN_RELAY || "false").toLowerCase() === "true" ? "relay" : "all"
    },
    notifications: {
      pushSupported: webPushReady,
      vapidPublicKey: webPushReady ? webPushPublicKey : ""
    },
    
    giphy: {
      // Keep the old client key field for backwards compatibility. New clients
      // use the authenticated server proxy below, so the key never needs to be
      // placed in a public page URL.
      apiKey: String(process.env.GIPHY_API_KEY || "").trim(),
      apiKeyConfigured: Boolean(String(process.env.GIPHY_API_KEY || "").trim()),
      enabled: Boolean(String(process.env.GIPHY_API_KEY || "").trim()),
      apiEndpoint: "/api/giphy/search",
      rating: "r"
    }
  });
});

// GIPHY sticker search. The previous UI called GIPHY directly from the
// browser, which made a missing/CORS-sensitive client configuration look like
// a broken sticker picker. Keep GIPHY_API_KEY on the server and return the
// native GIPHY payload through an authenticated, rate-limited proxy.
app.get("/api/giphy/search", giphyLimiter, requireHttpAuth, async (req, res) => {
  const apiKey = String(process.env.GIPHY_API_KEY || "").trim();
  if (!apiKey) {
    return res.status(503).json({
      error: "GIPHY_API_KEY غير مهيأ على السيرفر",
      configured: false
    });
  }

  const query = String(req.query.q || "").trim().slice(0, 80);
  const limit = Math.max(1, Math.min(50, Number.parseInt(req.query.limit, 10) || 50));
  const offset = Math.max(0, Math.min(5000, Number.parseInt(req.query.offset, 10) || 0));
  const requestedRating = String(req.query.rating || "r").toLowerCase();
  const rating = ["g", "pg", "pg-13", "r"].includes(requestedRating) ? requestedRating : "r";
  const endpoint = query
    ? "https://api.giphy.com/v1/gifs/search"
    : "https://api.giphy.com/v1/gifs/trending";
  const params = new URLSearchParams({
    api_key: apiKey,
    limit: String(limit),
    offset: String(offset),
    rating
  });
  if (query) params.set("q", query);

  try {
    const upstream = await fetch(`${endpoint}?${params.toString()}`, {
      method: "GET",
      headers: { Accept: "application/json" },
      signal: AbortSignal.timeout(12_000)
    });
    const payload = await upstream.json().catch(() => ({}));
    if (!upstream.ok) {
      console.warn(`GIPHY request failed (${upstream.status})`);
      return res.status(upstream.status === 429 ? 429 : 502).json({
        error: "تعذر تحميل ملصقات GIPHY حالياً",
        configured: true
      });
    }
    res.setHeader("Cache-Control", "private, max-age=20");
    return res.json(payload);
  } catch (error) {
    console.warn("GIPHY request error:", error?.message || error);
    return res.status(502).json({
      error: "تعذر الاتصال بخدمة GIPHY حالياً",
      configured: true
    });
  }
});

