// Generate short-lived Cloudflare TURN credentials for the authenticated user.
// Long-lived Cloudflare TURN secrets remain only in Render Environment Variables.
app.get("/api/turn-credentials", requireHttpAuth, turnCredentialLimiter, async (req, res) => {
  try {
    if (CLOUDFLARE_TURN_CONFIGURED) {
      const credentials = await getCloudflareTurnCredentials(req.authUser);
      res.setHeader("Cache-Control", "no-store");
      return res.json({
        success: true,
        ...credentials,
        iceTransportPolicy: String(process.env.FORCE_TURN_RELAY || "false").toLowerCase() === "true" ? "relay" : "all"
      });
    }

    // Backwards-compatible fallback for an existing static TURN service.
    const turnUrls = String(process.env.TURN_URL || "")
      .split(",")
      .map(value => value.trim())
      .filter(Boolean);
    const username = String(process.env.TURN_USERNAME || "").trim();
    const credential = String(process.env.TURN_CREDENTIAL || "").trim();
    if (turnUrls.length && username && credential) {
      return res.json({
        success: true,
        provider: "static",
        turnConfigured: true,
        expiresAt: 0,
        iceServers: [
          { urls: ["stun:stun.cloudflare.com:3478", "stun:stun.l.google.com:19302"] },
          { urls: turnUrls.length === 1 ? turnUrls[0] : turnUrls, username, credential }
        ],
        iceTransportPolicy: String(process.env.FORCE_TURN_RELAY || "false").toLowerCase() === "true" ? "relay" : "all"
      });
    }

    return res.status(503).json({
      success: false,
      error: "TURN غير مهيأ على الخادم"
    });
  } catch (error) {
    console.error("Cloudflare TURN credentials error:", error.message);
    return res.status(502).json({
      success: false,
      error: "تعذر الحصول على بيانات TURN المؤقتة"
    });
  }
});

