// 🟢 API: Online friends
app.get("/api/online-friends/:username", (req, res) => {
  try {
    const username = req.params.username;
    const friends = [];
    for (const key in db.friends) {
      const parts = key.split("_");
      if (parts.length === 2) {
        if (parts[0] === username) friends.push(parts[1]);
        else if (parts[1] === username) friends.push(parts[0]);
      }
    }
    const onlineFriends = friends.filter(f => activeOnlineUsers.has(f));
    res.json({ onlineFriends, count: onlineFriends.length });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ⭐ API: Approved platform staff search
app.get("/api/moderators", (req, res) => {
  try {
    const query = (req.query.q || "").toLowerCase();
    const mods = [];

    for (const username in db.users) {
      if (!isApprovedPlatformStaff(username)) continue;
      const user = db.users[username];

      if (
        !query ||
        username.toLowerCase().includes(query) ||
        (user.displayName && user.displayName.toLowerCase().includes(query))
      ) {
        mods.push({
          username,
          displayName: user.displayName || username,
          role: getPublicRole(username),
          badge: getPlatformBadge(username),
          avatar: user.avatar || "",
          frame: getActiveFrame(username),
          isOnline: activeOnlineUsers.has(username)
        });
      }
    }

    mods.sort((a, b) => {
      const rank = { owner: 0, admin: 1, moderator: 2 };
      return (rank[a.role] ?? 9) - (rank[b.role] ?? 9) || a.username.localeCompare(b.username);
    });

    res.json(mods.slice(0, 50));
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// 🚫 API: Ban user in a public room
app.post("/api/room/ban", requireHttpAuth, (req, res) => {
  try {
    const { roomId: roomIdOrCode, targetUser, duration, reason, isPermanent } = req.body;
    const actor = req.authUser;
    if (!roomIdOrCode || !targetUser) {
      return res.status(400).json({ error: "بيانات غير كاملة" });
    }

    const roomId = getCanonicalRoomId(roomIdOrCode);
    if (!canModeratePublicRoomTarget(roomId, actor, targetUser)) {
      return res.status(403).json({ error: "لا تملك صلاحية حظر هذا المستخدم أو أن الحساب محمي" });
    }

    if (!db.roomBans[roomId]) db.roomBans[roomId] = {};
    const minutes = Math.max(1, Number.parseInt(duration, 10) || 60);
    const expiresAt = isPermanent ? null : new Date(Date.now() + minutes * 60000).toISOString();

    db.roomBans[roomId][targetUser] = {
      bannedBy: actor,
      reason: String(reason || "").slice(0, 500),
      isPermanent: !!isPermanent,
      expiresAt,
      createdAt: new Date().toISOString()
    };

    if (Array.isArray(db.rooms[roomId]?.members)) {
      db.rooms[roomId].members = db.rooms[roomId].members.filter(id => id !== targetUser);
    }
    saveDB(db);

    const liveRoom = io.sockets.adapter.rooms.get(roomId);
    if (liveRoom) {
      for (const socketId of liveRoom) {
        const clientSocket = io.sockets.sockets.get(socketId);
        if (clientSocket?.userId === targetUser) {
          clientSocket.emit("banned-from-room", {
            message: isPermanent ? "تم حظرك دائماً من هذه الغرفة" : "تم حظرك مؤقتاً من هذه الغرفة",
            reason: reason || "",
            expiresAt
          });
          clientSocket.leave(roomId);
        }
      }
    }

    res.json({ success: true, message: "تم الحظر بنجاح" });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ✅ API: Unban user from room
app.post("/api/room/unban", requireHttpAuth, (req, res) => {
  try {
    const { roomId: roomIdOrCode, targetUser } = req.body;
    const actor = req.authUser;
    if (!roomIdOrCode || !targetUser) return res.status(400).json({ error: "بيانات غير كاملة" });

    const roomId = getCanonicalRoomId(roomIdOrCode);
    if (!isRoomStaff(roomId, actor)) return res.status(403).json({ error: "ليس لديك صلاحية" });

    if (db.roomBans[roomId]) {
      delete db.roomBans[roomId][targetUser];
      saveDB(db);
    }
    res.json({ success: true, message: "تم فك الحظر" });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// 📋 API: Bans list
app.get("/api/room/bans/:roomId", requireHttpAuth, (req, res) => {
  try {
    const roomId = getCanonicalRoomId(req.params.roomId);
    if (!isRoomStaff(roomId, req.authUser)) {
      return res.status(403).json({ error: "ليس لديك صلاحية عرض المحظورين" });
    }
    const bans = db.roomBans[roomId] || {};
    const list = Object.keys(bans).map(userId => ({ userId, ...bans[userId] }));
    res.json(list);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});


// Publish an already-uploaded file as a chat message. Keeping this on the HTTP
// side makes mobile uploads reliable even when Android/iOS suspends Socket.IO
// while the system Gallery / file picker is open. The function is idempotent:
// repeating the publish request for the same file returns the existing message.
function publishStoredUploadMessage({ actor, roomIdOrCode, fileId, msgId, time, replyTo, voiceDurationMs, voiceWaveform }) {
  if (!actor || !roomIdOrCode || !fileId) {
    return { success: false, status: 400, error: "بيانات إرسال الملف غير كاملة" };
  }

  const rId = getCanonicalRoomId(roomIdOrCode);
  const roomDoc = db.rooms[rId];
  const file = db.uploads[fileId];

  if (!roomDoc || !canUserAccessRoom(rId, actor)) {
    return { success: false, status: 403, error: "لا تملك صلاحية إرسال ملف في هذه المحادثة." };
  }
  if (roomDoc.systemRoom) {
    return { success: false, status: 403, error: "حساب TOMI الرسمي مخصص لاستقبال رسائل المنصة فقط." };
  }
  if (!file || file.uploader !== actor || file.roomId !== rId) {
    return { success: false, status: 400, error: "الملف غير صالح أو لم يتم رفعه لهذه المحادثة." };
  }

  if (!roomDoc.isPrivate) {
    const banCheck = checkRoomBan(rId, actor);
    if (banCheck.banned) {
      return { success: false, status: 403, error: "أنت محظور من هذه الغرفة", ban: banCheck };
    }
  }

  // Idempotency across mobile retries. A request can finish on the server while
  // Android temporarily suspends the browser and the client retries. The same
  // msgId must never create a second chat message, even if the retry produced a
  // new temporary upload record.
  const requestedMsgId = String(msgId || "").trim();
  if (requestedMsgId) {
    const existingByMsgId = (db.roomHistory[rId] || []).find(m => m.msgId === requestedMsgId);
    if (existingByMsgId) return { success: true, messageData: existingByMsgId, duplicate: true };
  }
  if (file.messageId) {
    const existing = (db.roomHistory[rId] || []).find(m => m.msgId === file.messageId || m.fileId === fileId);
    if (existing) return { success: true, messageData: existing, duplicate: true };
  }

  const createdAt = new Date().toISOString();
  const displayTime = time || new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
  const user = db.users[actor] || {};
  const safeReply = replyTo && typeof replyTo === "object" ? replyTo : null;

  const messageData = {
    roomId: rId,
    type: "media",
    msgId: msgId || ("msg-" + Date.now() + "-" + crypto.randomBytes(4).toString("hex")),
    fileId,
    fileUrl: `/api/files/${encodeURIComponent(fileId)}`,
    fileName: file.originalName,
    fileType: file.fileType,
    mimeType: file.mimeType,
    fileSize: file.size,
    playbackStatus: file.fileType === "video" ? (file.playbackStatus || "queued") : null,
    userId: actor,
    username: actor,
    displayName: user.displayName || actor,
    time: displayTime,
    createdAt,
    replyTo: safeReply,
    reactions: [],
    deliveredTo: [{ userId: actor, username: actor, time: displayTime, at: createdAt }],
    readBy: [{ userId: actor, username: actor, time: displayTime, at: createdAt }],
    status: "sent"
  };
  if (file.fileType === "audio" && /^voice[-_]/i.test(String(file.originalName || ""))) {
    const duration = Math.max(0, Math.min(60 * 60 * 1000, Number(voiceDurationMs || 0) || 0));
    let waveform = Array.isArray(voiceWaveform) ? voiceWaveform : [];
    waveform = waveform.map(v => Math.max(0.06, Math.min(1, Number(v) || 0.06))).slice(0, 80);
    if (duration) messageData.voiceDurationMs = duration;
    if (waveform.length) messageData.voiceWaveform = waveform;
    messageData.voiceNote = true;
  }

  appendRoomMessage(rId, messageData);
  roomDoc.updatedAt = createdAt;
  file.sentAt = createdAt;
  file.messageId = messageData.msgId;
  saveDB(db);

  if (telegramLoggingEnabled) {
    enqueueTelegramTask(rId, () => sendTelegramStoredUpload({
      roomId: rId,
      userId: actor,
      username: actor,
      time: displayTime,
      record: file
    }));
  }
  if (!roomDoc.isPrivate) {
    logMessageToFile(
      rId,
      `[ملف - ${file.fileType}] ${user.displayName || actor} (${actor}) أرسل ${file.originalName} (${file.size} bytes)`
    );
  }

  // Broadcast after persistence. Clients currently inside the room receive the
  // media immediately, while other online participants refresh their chat list.
  io.to(rId).emit("receive-media", messageData);
  for (const participant of getRoomAudience(rId)) {
    if (participant !== actor) {
      // Deliver through the user's personal Socket.IO room as a second reliable
      // path. The client de-duplicates by msgId, so this is safe even when that
      // user's socket is also joined to the conversation room. It fixes media
      // disappearing when a mobile browser briefly lost its room membership.
      io.to(`user_${participant}`).emit("receive-media", messageData);
      io.to(`user_${participant}`).emit("conversation-updated", {
        roomId: rId,
        message: messageData
      });
    }
  }
  notifyRoomParticipants(rId, actor, {
    title: user.displayName || actor,
    body: mediaNotificationBody(messageData.fileType, messageData.fileName),
    url: `/room.html?roomId=${encodeURIComponent(rId)}`,
    tag: `msg-${messageData.msgId}`,
    type: "media"
  }).catch(() => {});

  return { success: true, messageData };
}

// 📎 Resumable HTTP uploads.
// Files are written directly to disk instead of being converted to Base64.
// A mobile browser can lose focus while the system picker is open; resumable
// chunks let it continue from the last confirmed byte instead of restarting a
// large video or leaving a false 100% progress card behind.
function validateUploadSessionScope(uploader, roomIdOrCode, context) {
  let roomId = null;
  if (roomIdOrCode) {
    roomId = getCanonicalRoomId(roomIdOrCode);
    if (!canUserAccessRoom(roomId, uploader)) {
      return { error: "لا تملك صلاحية رفع ملف لهذه المحادثة", status: 403 };
    }
    if (isPlatformSystemRoom(roomId)) {
      return { error: "حساب المنصة مخصص لاستقبال الرسائل الرسمية فقط", status: 403 };
    }
  } else if (!["report", "avatar", "frame", "voice-room-image"].includes(context)) {
    return { error: "معرّف المحادثة مطلوب", status: 400 };
  }

  if (context === "frame" && uploader !== PLATFORM_OWNER_USERNAME) {
    return { error: "رفع الإطارات متاح لمالك المنصة فقط", status: 403 };
  }
  return { roomId };
}

function uploadSessionPublicResult(session, record, message = null, extra = {}) {
  const fileId = session.fileId || record?.fileId;
  return {
    success: true,
    fileId,
    fileName: record?.originalName || session.originalName,
    fileType: record?.fileType || session.fileType,
    mimeType: record?.mimeType || session.mimeType,
    size: Number(record?.size || session.fileSize || 0),
    url: `/api/files/${encodeURIComponent(fileId)}`,
    playbackStatus: record?.fileType === "video" ? (record.playbackStatus || "queued") : null,
    playbackUrl: record?.fileType === "video"
      && record.playbackStatus === "ready"
      && record.playbackMode === "compatibility"
      ? `/api/files/${encodeURIComponent(fileId)}?playback=compatible`
      : null,
    message,
    ...extra
  };
}

function uploadSessionParts(session) {
  if (!(session?.r2Parts instanceof Map)) return [];
  return [...session.r2Parts.entries()]
    .map(([partNumber, part]) => ({
      partNumber: Number(partNumber),
      etag: String(part?.etag || ""),
      size: Number(part?.size || 0)
    }))
    .filter(part => Number.isInteger(part.partNumber) && part.partNumber > 0 && part.etag)
    .sort((a, b) => a.partNumber - b.partNumber);
}

function uploadSessionState(session) {
  const directR2 = session?.mode === "r2-multipart";
  return {
    success: true,
    sessionId: session.id,
    mode: session.mode || "server",
    directUpload: directR2,
    chunkSize: directR2 ? objectStorage.getPartSize() : UPLOAD_CHUNK_SIZE,
    partSize: directR2 ? objectStorage.getPartSize() : null,
    received: Number(session.received || 0),
    fileSize: Number(session.fileSize || 0),
    status: session.status,
    ...(directR2 ? { uploadedParts: uploadSessionParts(session) } : {}),
    result: ["completed", "uploaded"].includes(session.status) ? session.result : null,
    expiresAt: new Date(session.expiresAt).toISOString()
  };
}

app.post("/api/upload/session", uploadLimiter, requireHttpAuth, limitConcurrentUploads, async (req, res) => {
  let pendingR2Upload = null;
  try {
    const uploader = req.authUser;
    const body = req.body || {};
    const context = String(body.context || "chat").trim();
    const fileSize = Number(body.fileSize);
    if (!Number.isSafeInteger(fileSize) || fileSize < 0 || fileSize > MAX_UPLOAD_BYTES) {
      return res.status(413).json({ error: "حجم الملف أكبر من الحد المسموح على هذا الخادم", maxBytes: MAX_UPLOAD_BYTES });
    }

    const scope = validateUploadSessionScope(uploader, String(body.roomId || "").trim(), context);
    if (scope.error) return res.status(scope.status || 400).json({ error: scope.error });

    const originalName = String(body.originalName || "file").trim().slice(0, 180) || "file";
    const mimeType = String(body.mimeType || "application/octet-stream").trim().slice(0, 160) || "application/octet-stream";
    const clientFileType = String(body.clientFileType || "").trim().toLowerCase().slice(0, 24);
    const fileType = classifyFileType(mimeType, originalName, clientFileType);
    const storedMimeType = normalizeMediaMimeType(fileType, mimeType, originalName);
    const requestedMsgId = String(body.msgId || "").trim().slice(0, 180);

    // The POST response itself can be lost when Android backgrounds the page
    // immediately after the picker closes. Reusing the same message id makes a
    // repeated session-init request idempotent and prevents an orphaned second
    // copy of the video from starting at byte zero.
    if (requestedMsgId) {
      for (const existing of uploadSessions.values()) {
        if (!existing
          || existing.uploader !== uploader
          || existing.context !== context
          || existing.roomId !== scope.roomId
          || existing.msgId !== requestedMsgId
          || Number(existing.fileSize) !== fileSize
          || existing.originalName !== originalName
          || !["uploading", "completing", "completed", "uploaded"].includes(existing.status)) continue;
        existing.expiresAt = Date.now() + UPLOAD_SESSION_TTL_MS;
        return res.status(200).json(uploadSessionState(existing));
      }

      // The previous process may have completed and published the message just
      // before a Render restart, which clears the in-memory session map. The
      // persistent message id is enough to recover the already-uploaded file
      // and avoid forcing the phone to send it a second time.
      if (context === "chat" && scope.roomId) {
        const existingMessage = (db.roomHistory?.[scope.roomId] || [])
          .find(message => message?.msgId === requestedMsgId);
        const existingFile = existingMessage?.fileId ? db.uploads?.[existingMessage.fileId] : null;
        if (existingFile && existingFile.uploader === uploader && Number(existingFile.size) === fileSize) {
          const recoveredSession = {
            fileId: existingFile.fileId,
            originalName: existingFile.originalName,
            fileType: existingFile.fileType,
            mimeType: existingFile.mimeType,
            fileSize: existingFile.size
          };
          return res.status(200).json({
            ...uploadSessionPublicResult(recoveredSession, existingFile, existingMessage),
            sessionId: "done_" + existingFile.fileId,
            chunkSize: UPLOAD_CHUNK_SIZE,
            received: existingFile.size,
            fileSize: existingFile.size,
            status: "completed",
            result: uploadSessionPublicResult(recoveredSession, existingFile, existingMessage)
          });
        }
      }
    }
    const sessionId = "ups_" + crypto.randomBytes(18).toString("hex");
    const fileId = "upl_" + crypto.randomBytes(16).toString("hex");
    const directR2 = objectStorage.isConfigured() && fileSize > 0;
    let tempName = null;
    let tempPath = null;
    let r2Key = null;
    let r2UploadId = null;
    if (directR2) {
      r2Key = objectStorage.buildObjectKey({
        fileId,
        originalName,
        context,
        roomId: scope.roomId || ""
      });
      r2UploadId = await objectStorage.createMultipartUpload({
        key: r2Key,
        contentType: storedMimeType,
        metadata: { fileId, context }
      });
      pendingR2Upload = { key: r2Key, uploadId: r2UploadId };
    } else {
      tempName = `${sessionId}.part`;
      tempPath = path.join(UPLOAD_DIR, tempName);
      await fs.promises.writeFile(tempPath, Buffer.alloc(0));
    }
    const now = new Date().toISOString();
    const session = {
      id: sessionId,
      uploader,
      roomId: scope.roomId,
      context,
      originalName,
      mimeType: storedMimeType,
      clientFileType,
      fileType,
      fileSize,
      received: 0,
      mode: directR2 ? "r2-multipart" : "server",
      tempName,
      tempPath,
      r2Key,
      r2UploadId,
      r2Parts: new Map(),
      r2DeleteQueued: false,
      r2Completed: false,
      msgId: requestedMsgId,
      time: String(body.time || "").trim().slice(0, 80),
      replyTo: body.replyTo && typeof body.replyTo === "object" ? body.replyTo : null,
      voiceDurationMs: Math.max(0, Math.min(60 * 60 * 1000, Number(body.voiceDurationMs || 0) || 0)),
      voiceWaveform: Array.isArray(body.voiceWaveform) ? body.voiceWaveform.slice(0, 80) : [],
      status: "uploading",
      createdAt: now,
      expiresAt: Date.now() + UPLOAD_SESSION_TTL_MS,
      writing: false,
      fileId,
      result: null,
      completionPromise: null,
      gridFsUploadStream: null,
      gridFsId: null,
      gridFsUploadFailed: false,
      gridFsUploadFinished: false,
      gridFsDeleteQueued: false,
      gridFsError: null
    };
    uploadSessions.set(sessionId, session);
    pendingR2Upload = null;
    // With R2 enabled, the browser sends each part directly to the object store
    // and this service only authorizes parts, records metadata, and publishes
    // the chat message. The server-side file path remains for old deployments
    // and zero-byte compatibility uploads.
    analyticsService?.track("upload_started", {
      userId: uploader,
      bytes: fileSize,
      page: "/api/upload/session",
      feature: context
    });

    res.status(201).json(uploadSessionState(session));
  } catch (err) {
    if (pendingR2Upload) {
      await objectStorage.abortMultipartUpload(pendingR2Upload).catch(() => {});
    }
    console.error("Upload session creation failed:", err?.message || err);
    const status = objectStorage.isConfigured() && /R2|object|multipart/i.test(String(err?.message || "")) ? 503 : 500;
    res.status(status).json({ error: status === 503 ? "تعذر الاتصال بتخزين الملفات الخارجي، حاول بعد لحظة" : "تعذر بدء رفع الملف" });
  }
});

app.get("/api/upload/session/:sessionId", requireHttpAuth, (req, res) => {
  const session = uploadSessions.get(String(req.params.sessionId || ""));
  if (!session || session.uploader !== req.authUser) return res.status(404).json({ error: "جلسة الرفع غير موجودة" });
  if (session.status !== "completed" && session.expiresAt <= Date.now()) {
    if (session.status !== "uploaded") queuePartialResumableUploadDelete(session);
    safeUnlink(session.tempPath);
    uploadSessions.delete(session.id);
    return res.status(410).json({ error: "انتهت صلاحية جلسة الرفع" });
  }
  res.json(uploadSessionState(session));
});

app.get("/api/upload/session/:sessionId/part-url", uploadLimiter, requireHttpAuth, async (req, res) => {
  const session = uploadSessions.get(String(req.params.sessionId || ""));
  if (!session || session.uploader !== req.authUser) return res.status(404).json({ error: "جلسة الرفع غير موجودة" });
  if (session.mode !== "r2-multipart" || !session.r2Key || !session.r2UploadId) {
    return res.status(409).json({ error: "هذه الجلسة تستخدم رفعاً عادياً" });
  }
  if (session.expiresAt <= Date.now()) {
    queuePartialResumableUploadDelete(session);
    uploadSessions.delete(session.id);
    return res.status(410).json({ error: "انتهت صلاحية جلسة الرفع" });
  }
  if (!["uploading", "completing"].includes(session.status)) {
    return res.status(409).json({ error: "الملف قيد المعالجة" });
  }
  const partNumber = Number.parseInt(req.query.partNumber, 10);
  const totalParts = Math.max(1, Math.ceil(session.fileSize / objectStorage.getPartSize()));
  if (!Number.isInteger(partNumber) || partNumber < 1 || partNumber > totalParts) {
    return res.status(400).json({ error: "رقم مقطع الرفع غير صحيح" });
  }
  try {
    const url = await objectStorage.getSignedPartUploadUrl({
      key: session.r2Key,
      uploadId: session.r2UploadId,
      partNumber
    });
    res.json({ success: true, partNumber, url, expiresIn: 900 });
  } catch (err) {
    console.warn("R2 part URL failed:", err?.message || err);
    res.status(503).json({ error: "تعذر تجهيز رابط رفع المقطع، حاول بعد لحظة" });
  }
});

app.post("/api/upload/session/:sessionId/part", uploadLimiter, requireHttpAuth, async (req, res) => {
  const session = uploadSessions.get(String(req.params.sessionId || ""));
  if (!session || session.uploader !== req.authUser) return res.status(404).json({ error: "جلسة الرفع غير موجودة" });
  if (session.mode !== "r2-multipart" || !session.r2Key || !session.r2UploadId) {
    return res.status(409).json({ error: "هذه الجلسة تستخدم رفعاً عادياً" });
  }
  if (session.expiresAt <= Date.now()) {
    queuePartialResumableUploadDelete(session);
    uploadSessions.delete(session.id);
    return res.status(410).json({ error: "انتهت صلاحية جلسة الرفع" });
  }
  const partNumber = Number(req.body?.partNumber);
  const etag = String(req.body?.etag || "").trim();
  const size = Number(req.body?.size || 0);
  const totalParts = Math.max(1, Math.ceil(session.fileSize / objectStorage.getPartSize()));
  if (!Number.isInteger(partNumber) || partNumber < 1 || partNumber > totalParts || !etag || !Number.isSafeInteger(size) || size <= 0) {
    return res.status(400).json({ error: "بيانات مقطع الرفع غير صحيحة" });
  }
  const expectedSize = partNumber === totalParts
    ? session.fileSize - objectStorage.getPartSize() * (totalParts - 1)
    : objectStorage.getPartSize();
  if (size !== expectedSize) {
    return res.status(400).json({ error: "حجم مقطع الرفع غير صحيح" });
  }
  session.r2Parts.set(partNumber, { etag: etag.slice(0, 512), size });
  session.received = [...session.r2Parts.values()].reduce((total, part) => total + Number(part.size || 0), 0);
  session.expiresAt = Date.now() + UPLOAD_SESSION_TTL_MS;
  res.json({ success: true, ...uploadSessionState(session) });
});

app.put("/api/upload/session/:sessionId/chunk", uploadLimiter, requireHttpAuth, limitConcurrentUploads, async (req, res) => {
  const session = uploadSessions.get(String(req.params.sessionId || ""));
  if (!session || session.uploader !== req.authUser) return res.status(404).json({ error: "جلسة الرفع غير موجودة" });
  if (session.expiresAt <= Date.now()) {
    if (session.status !== "uploaded") queuePartialResumableUploadDelete(session);
    safeUnlink(session.tempPath);
    uploadSessions.delete(session.id);
    return res.status(410).json({ error: "انتهت صلاحية جلسة الرفع" });
  }
  if (session.mode === "r2-multipart") {
    return res.status(409).json({ error: "هذه الجلسة ترفع مباشرة إلى التخزين الخارجي" });
  }
  if (session.status === "completed") return res.json({ success: true, received: session.received, done: true });
  if (session.status !== "uploading") return res.status(409).json({ error: "الملف قيد المعالجة", received: session.received });
  if (session.writing) return res.status(409).json({ error: "يوجد مقطع آخر قيد الرفع", received: session.received });

  const offset = Number.parseInt(req.query.offset, 10);
  const expected = Math.min(UPLOAD_CHUNK_SIZE, Math.max(0, session.fileSize - session.received));
  if (!Number.isInteger(offset) || offset !== session.received || expected <= 0) {
    return res.status(409).json({ error: "ترتيب مقطع الرفع غير صحيح", received: session.received });
  }

  session.writing = true;
  let requestBytes = 0;
  try {
    const output = fs.createWriteStream(session.tempPath, { flags: "r+", start: session.received });
    let outputError = null;
    // Keep one listener for the lifetime of this chunk so an asynchronous disk
    // error cannot become an unhandled process error on a mobile upload.
    output.on("error", err => { outputError = err; });
    const directCloud = ["video", "audio"].includes(session.fileType)
      && session.gridFsUploadStream
      && !session.gridFsUploadFailed;

    if (directCloud) {
      const requestBytesRef = { value: 0 };
      const tee = createUploadTee(session, output, requestBytesRef);
      try {
        await pipeline(req, tee);
        await new Promise((resolve, reject) => {
          let settled = false;
          const finish = err => {
            if (settled) return;
            settled = true;
            err ? reject(err) : resolve();
          };
          output.once("error", finish);
          output.end(() => finish(outputError));
        });
      } catch (err) {
        try { output.destroy(); } catch (_) {}
        throw err;
      }
      requestBytes = requestBytesRef.value;
    } else {
      const counter = new Transform({
        transform(chunk, _encoding, callback) {
          requestBytes += chunk.length;
          callback(null, chunk);
        }
      });
      await pipeline(req, counter, output);
    }
    if (requestBytes !== expected) {
      if (directCloud) {
        session.gridFsUploadFailed = true;
        session.gridFsError = new Error("المقطع لم يصل بالحجم المتوقع");
        queuePartialResumableUploadDelete(session);
      }
      await fs.promises.truncate(session.tempPath, session.received).catch(() => {});
      return res.status(400).json({ error: "المقطع لم يصل كاملاً", received: session.received, expected });
    }
    session.received += requestBytes;
    session.expiresAt = Date.now() + UPLOAD_SESSION_TTL_MS;
    // Do not wait for GridFS to write its final files document here. The local
    // copy is complete and is served immediately by the completion response;
    // cloud finalisation is queued after the upload record is created.
    res.json({ success: true, received: session.received, done: session.received >= session.fileSize });
  } catch (err) {
    await fs.promises.truncate(session.tempPath, session.received).catch(() => {});
    if (session.fileType === "video" && session.gridFsId && !db.uploads?.[session.fileId]) {
      queuePartialResumableUploadDelete(session);
    }
    console.warn("Upload chunk failed:", err?.message || err);
    res.status(502).json({ error: "انقطع رفع المقطع ويمكن إعادة المحاولة", received: session.received });
  } finally {
    session.writing = false;
  }
});

app.post("/api/upload/session/:sessionId/complete", uploadLimiter, requireHttpAuth, limitConcurrentUploads, async (req, res) => {
  const session = uploadSessions.get(String(req.params.sessionId || ""));
  if (!session || session.uploader !== req.authUser) return res.status(404).json({ error: "جلسة الرفع غير موجودة" });
  if (["completed", "uploaded"].includes(session.status) && session.result) return res.json(session.result);
  if (session.status === "completing") {
    // Mobile browsers may retry after losing the response while the server is
    // copying the temporary file to GridFS. Join the same operation instead of
    // starting a second remote copy of the video.
    if (session.completionPromise) {
      try {
        const result = await session.completionPromise;
        return res.json(result);
      } catch (_) {
        return res.status(500).json({ error: "تعذر تثبيت الملف على الخادم، ويمكن إعادة المحاولة" });
      }
    }
    return res.status(409).json({ error: "الملف قيد التثبيت، أعد المحاولة بعد لحظة", status: "completing" });
  }
  if (session.expiresAt <= Date.now()) {
    if (session.status !== "uploaded") queuePartialResumableUploadDelete(session);
    safeUnlink(session.tempPath);
    uploadSessions.delete(session.id);
    return res.status(410).json({ error: "انتهت صلاحية جلسة الرفع" });
  }
  if (session.received !== session.fileSize) {
    return res.status(409).json({ error: "لم يكتمل رفع الملف بعد", received: session.received, fileSize: session.fileSize });
  }
  if (session.writing) return res.status(409).json({ error: "انتظر اكتمال آخر مقطع" });

  const completionPromise = (async () => {
    session.status = "completing";
    const fileId = session.fileId || ("upl_" + crypto.randomBytes(16).toString("hex"));
    let record = db.uploads?.[fileId] || null;
    const sessionFileType = classifyFileType(session.mimeType, session.originalName, session.clientFileType);
    const keepLocalCache = ["image", "gif", "video", "audio"].includes(sessionFileType)
      && session.fileSize <= MEDIA_LOCAL_CACHE_MAX_FILE_BYTES;

    if (!record) {
      if (["background", "avatar", "frame", "voice-room-image"].includes(session.context) && !["image", "gif"].includes(sessionFileType)) {
        const error = new Error("خلفية المحادثة يجب أن تكون صورة");
        error.statusCode = 400;
        throw error;
      }

      let cloudFile;
      if (session.mode === "r2-multipart") {
        const totalParts = Math.max(1, Math.ceil(session.fileSize / objectStorage.getPartSize()));
        const parts = uploadSessionParts(session);
        const expectedPartNumbers = Array.from({ length: totalParts }, (_value, index) => index + 1);
        const receivedBytes = parts.reduce((total, part) => total + Number(part.size || 0), 0);
        if (parts.length !== totalParts
          || parts.some((part, index) => part.partNumber !== expectedPartNumbers[index])
          || receivedBytes !== session.fileSize) {
          const error = new Error("لم تكتمل مقاطع التخزين الخارجي بعد");
          error.statusCode = 409;
          throw error;
        }
        if (!session.r2Completed) {
          await objectStorage.completeMultipartUpload({
            key: session.r2Key,
            uploadId: session.r2UploadId,
            parts
          });
          session.r2Completed = true;
        }
        // The multipart upload is now a completed object; never abort it as a
        // partial upload if a later chat-publish retry takes a moment.
        session.r2UploadId = null;
        cloudFile = {
          storage: "r2",
          storedName: null,
          cacheStoredName: null,
          cacheExpiresAt: null,
          gridFsId: null,
          r2Key: session.r2Key,
          size: session.fileSize,
          cloudPending: false
        };
      } else {
        const reqFile = {
          path: session.tempPath,
          filename: session.tempName,
          originalname: session.originalName,
          mimetype: session.mimeType,
          size: session.fileSize
        };
        // Old deployments without R2 keep the existing local/GridFS path.
        const localFirstChatMedia = session.context === "chat" && ["video", "audio"].includes(sessionFileType);
        cloudFile = localFirstChatMedia
          ? localFirstVideoFile(session, fileId, keepLocalCache)
          : await persistUploadedFileToCloud(reqFile, fileId, {
            keepLocalCache,
            context: session.context,
            roomId: session.roomId || ""
          });
      }
      record = {
        fileId,
        storedName: cloudFile.storedName,
        cacheStoredName: cloudFile.cacheStoredName || null,
        cacheExpiresAt: cloudFile.cacheExpiresAt || null,
        gridFsId: cloudFile.gridFsId,
        r2Key: cloudFile.r2Key || null,
        storage: cloudFile.storage,
        originalName: session.originalName,
        mimeType: session.mimeType,
        fileType: sessionFileType,
        size: session.fileSize,
        uploader: session.uploader,
        roomId: session.roomId,
        context: session.context,
        createdAt: new Date().toISOString(),
        cloudPending: Boolean(cloudFile.cloudPending),
        cloudLastErrorAt: null
      };
      db.uploads[fileId] = record;
      session.fileId = fileId;

      if (session.context === "avatar" && db.users[session.uploader]) {
        db.users[session.uploader].avatar = `/api/files/${encodeURIComponent(fileId)}`;
        db.users[session.uploader].avatarFileId = fileId;
      }
      saveDB(db);
    } else {
      session.fileId = fileId;
    }

    if (["video", "audio"].includes(sessionFileType) && record.storage === "local" && record.cloudPending) {
      queueResumableVideoCloudPersistence(session, fileId, record, { keepLocalCache });
    }
    if (sessionFileType === "video") queueVideoCompatibilityJob(fileId);

    let publishedMessage = null;
    if (session.context === "chat" && session.roomId) {
      const publishResult = publishStoredUploadMessage({
        actor: session.uploader,
        roomIdOrCode: session.roomId,
        fileId,
        msgId: session.msgId || undefined,
        time: session.time || undefined,
        replyTo: session.replyTo,
        voiceDurationMs: session.voiceDurationMs,
        voiceWaveform: session.voiceWaveform
      });
      if (!publishResult.success) {
        // The bytes are safe and retained. The client can use the compatibility
        // Socket.IO publish path, so a temporary DB/socket hiccup never deletes
        // the completed upload.
        session.status = "uploaded";
        session.result = uploadSessionPublicResult(session, record, null, {
          uploaded: true,
          publishError: publishResult.error || "تم رفع الملف لكن تعذر إرساله للمحادثة"
        });
        analyticsService?.track("upload_complete", {
          userId: session.uploader,
          bytes: session.fileSize,
          page: "/api/upload/session/complete",
          feature: session.context
        });
        return session.result;
      }
      publishedMessage = publishResult.messageData;
    }

    session.status = "completed";
    session.result = uploadSessionPublicResult(session, record, publishedMessage);
    analyticsService?.track("upload_complete", {
      userId: session.uploader,
      bytes: session.fileSize,
      page: "/api/upload/session/complete",
      feature: session.context
    });
    return session.result;
  })();

  session.completionPromise = completionPromise;
  try {
    const result = await completionPromise;
    return res.json(result);
  } catch (err) {
    session.status = "uploading";
    analyticsService?.track("upload_failed", {
      userId: session.uploader,
      bytes: session.fileSize,
      page: "/api/upload/session/complete",
      feature: session.context,
      metadata: { statusCode: Number(err?.statusCode) || 500 }
    });
    console.error("Resumable upload completion failed:", err?.stack || err?.message || err);
    const statusCode = Number(err?.statusCode) >= 400 && Number(err?.statusCode) < 500 ? Number(err.statusCode) : 500;
    return res.status(statusCode).json({
      error: statusCode === 400 ? err.message : "تعذر حفظ أو إرسال الملف، ويمكن إعادة المحاولة"
    });
  } finally {
    if (session.completionPromise === completionPromise) session.completionPromise = null;
  }
});

app.delete("/api/upload/session/:sessionId", requireHttpAuth, (req, res) => {
  const session = uploadSessions.get(String(req.params.sessionId || ""));
  if (!session || session.uploader !== req.authUser) return res.status(404).json({ error: "جلسة الرفع غير موجودة" });
  if (session.status !== "completed" && session.status !== "uploaded") queuePartialResumableUploadDelete(session);
  safeUnlink(session.tempPath);
  uploadSessions.delete(session.id);
  res.json({ success: true });
});

// 📎 Legacy/small-file HTTP upload path. It remains available for old clients
// and small avatars while current chat media uses the resumable route above.
app.post("/api/upload", uploadLimiter, requireHttpAuth, limitConcurrentUploads, singleUpload, async (req, res) => {
  try {
    if (!req.file) return res.status(400).json({ error: "لم يتم اختيار ملف" });

    const uploader = req.authUser;
    const roomIdOrCode = String(req.body.roomId || "").trim();
    const context = String(req.body.context || "chat").trim();
    let roomId = null;

    if (roomIdOrCode) {
      roomId = getCanonicalRoomId(roomIdOrCode);
      if (!canUserAccessRoom(roomId, uploader)) {
        safeUnlink(req.file.path);
        return res.status(403).json({ error: "لا تملك صلاحية رفع ملف لهذه المحادثة" });
      }
      if (isPlatformSystemRoom(roomId)) {
        safeUnlink(req.file.path);
        return res.status(403).json({ error: "حساب المنصة مخصص لاستقبال الرسائل الرسمية فقط" });
      }
    } else if (!["report", "avatar", "frame", "voice-room-image"].includes(context)) {
      safeUnlink(req.file.path);
      return res.status(400).json({ error: "معرّف المحادثة مطلوب" });
    }

    if (context === "frame" && uploader !== PLATFORM_OWNER_USERNAME) {
      safeUnlink(req.file.path);
      return res.status(403).json({ error: "رفع الإطارات متاح لمالك المنصة فقط" });
    }

    const clientFileType = String(req.body.clientFileType || "").trim().toLowerCase();
    const fileType = classifyFileType(req.file.mimetype, req.file.originalname, clientFileType);
    const storedMimeType = normalizeMediaMimeType(fileType, req.file.mimetype, req.file.originalname);
    if (["background", "avatar", "frame", "voice-room-image"].includes(context) && !["image", "gif"].includes(fileType)) {
      safeUnlink(req.file.path);
      return res.status(400).json({ error: "خلفية المحادثة يجب أن تكون صورة" });
    }

    const fileId = req.generatedUploadId || path.parse(req.file.filename).name;
    const keepLocalCache = ["image", "gif", "video", "audio"].includes(fileType)
      && Number(req.file.size || 0) <= MEDIA_LOCAL_CACHE_MAX_FILE_BYTES;
    analyticsService?.track("upload_started", {
      userId: uploader,
      bytes: Number(req.file.size || 0),
      page: "/api/upload",
      feature: context
    });
    const localFirstChatMedia = !objectStorage.isConfigured()
      && context === "chat" && ["video", "audio"].includes(fileType);
    const localFirstSession = localFirstChatMedia ? {
      id: "legacy_" + fileId,
      fileId,
      tempName: req.file.filename,
      tempPath: req.file.path,
      originalName: String(req.file.originalname || "file").slice(0, 180),
      mimeType: storedMimeType,
      fileSize: Number(req.file.size || 0),
      roomId,
      context,
      cloudPersisting: false,
      cloudRetryScheduled: false,
      gridFsUploadStream: null,
      gridFsUploadFailed: false,
      gridFsUploadFinished: false,
      gridFsDeleteQueued: false,
      gridFsId: null,
      gridFsError: null
    } : null;
    const cloudFile = localFirstSession
      ? localFirstVideoFile(localFirstSession, fileId, keepLocalCache)
      : await persistUploadedFileToCloud(req.file, fileId, {
        keepLocalCache,
        context,
        roomId: roomId || ""
      });
    db.uploads[fileId] = {
      fileId,
      storedName: cloudFile.storedName,
      cacheStoredName: cloudFile.cacheStoredName || null,
      cacheExpiresAt: cloudFile.cacheExpiresAt || null,
      gridFsId: cloudFile.gridFsId,
      r2Key: cloudFile.r2Key || null,
      storage: cloudFile.storage,
      originalName: String(req.file.originalname || "file").slice(0, 180),
      mimeType: storedMimeType,
      fileType,
      size: req.file.size,
      uploader,
      roomId,
      context,
      createdAt: new Date().toISOString(),
      cloudPending: Boolean(cloudFile.cloudPending)
    };

    if (context === "avatar" && db.users[uploader]) {
      db.users[uploader].avatar = `/api/files/${encodeURIComponent(fileId)}`;
      db.users[uploader].avatarFileId = fileId;
    }

    saveDB(db);
    if (localFirstSession && db.uploads[fileId].storage === "local" && db.uploads[fileId].cloudPending) {
      queueResumableVideoCloudPersistence(localFirstSession, fileId, db.uploads[fileId], { keepLocalCache });
    }
    if (fileType === "video") queueVideoCompatibilityJob(fileId);
    analyticsService?.track("upload_complete", {
      userId: uploader,
      bytes: Number(req.file.size || 0),
      page: "/api/upload",
      feature: context
    });

    let publishedMessage = null;
    const publishToChat = context === "chat" && roomId && String(req.body.publishToChat || "") === "1";
    if (publishToChat) {
      let replyTo = null;
      if (req.body.replyTo) {
        try { replyTo = JSON.parse(String(req.body.replyTo)); } catch (_) { replyTo = null; }
      }
      let voiceWaveform = [];
      if (req.body.voiceWaveform) {
        try {
          const parsed = JSON.parse(String(req.body.voiceWaveform));
          if (Array.isArray(parsed)) voiceWaveform = parsed;
        } catch (_) {}
      }
      const publishResult = publishStoredUploadMessage({
        actor: uploader,
        roomIdOrCode: roomId,
        fileId,
        msgId: String(req.body.msgId || "").trim() || undefined,
        time: String(req.body.time || "").trim() || undefined,
        replyTo,
        voiceDurationMs: Number(req.body.voiceDurationMs || 0) || 0,
        voiceWaveform
      });
      if (!publishResult.success) {
        return res.status(publishResult.status || 400).json({
          success: false,
          uploaded: true,
          fileId,
          error: publishResult.error || "تم رفع الملف لكن تعذر إرساله للمحادثة"
        });
      }
      publishedMessage = publishResult.messageData;
    }

    res.json({
      success: true,
      fileId,
      fileName: db.uploads[fileId].originalName,
      fileType,
      mimeType: db.uploads[fileId].mimeType,
      size: req.file.size,
      url: `/api/files/${encodeURIComponent(fileId)}`,
      playbackStatus: fileType === "video" ? (db.uploads[fileId].playbackStatus || "queued") : null,
      message: publishedMessage
    });
  } catch (err) {
    safeUnlink(req.file?.path);
    console.error("Upload/publish failed:", err?.stack || err?.message || err);
    res.status(500).json({ error: "تعذر حفظ أو إرسال الملف" });
  }
});

function canViewerOpenUpload(record, viewer) {
  if (!record || !viewer) return false;
  let allowed = record.uploader === viewer;
  if (!allowed && record.roomId) allowed = canUserAccessRoom(record.roomId, viewer);
  if (!allowed && ["avatar", "frame", "voice-room-image"].includes(record.context)) allowed = true;
  if (!allowed && record.context === "report") {
    allowed = viewer === PLATFORM_OWNER_USERNAME || hasPermission(viewer, "manage_reports");
  }
  return allowed;
}

function effectiveStoredMimeType(record) {
  const name = String(record?.originalName || "").toLowerCase();
  const ext = path.extname(name);
  const mimeType = String(record?.mimeType || "application/octet-stream").toLowerCase().split(";", 1)[0].trim();
  const isVoice = /^voice[-_]/i.test(path.basename(name));
  const looksLikeVideoLabel = /^(?:mp4|video|vid)[._-]/i.test(path.basename(name));
  const audioExts = new Set([".m4a", ".mp3", ".aac", ".wav", ".ogg", ".opus", ".flac", ".weba"]);
  const audioByExtension = {
    ".m4a": "audio/mp4",
    ".mp3": "audio/mpeg",
    ".aac": "audio/aac",
    ".wav": "audio/wav",
    ".ogg": "audio/ogg",
    ".opus": "audio/ogg",
    ".flac": "audio/flac",
    ".weba": "audio/webm"
  };
  if (record?.fileType === "audio") {
    return mimeType.startsWith("audio/") ? mimeType : (audioByExtension[ext] || "audio/webm");
  }
  // Repair already-stored Android gallery videos that arrived as audio/mp4.
  if (!isVoice && [".mp4", ".m4v"].includes(ext)) return "video/mp4";
  if (!isVoice && ext === ".mov") return "video/quicktime";
  if (!isVoice && ext === ".webm" && record?.fileType === "video") return "video/webm";
  if (!isVoice && record?.fileType === "video") return normalizeMediaMimeType("video", mimeType, name);
  if (!isVoice && looksLikeVideoLabel && !audioExts.has(ext)
    && ["", "application/octet-stream", "audio/mp4", "audio/quicktime"].includes(mimeType)) return "video/mp4";
  return mimeType || "application/octet-stream";
}

function selectVideoPlaybackRecord(record, req) {
  const requested = String(req?.query?.playback || "").toLowerCase();
  if (requested === "original" || record?.fileType !== "video") return record;
  if (record?.playbackStatus !== "ready" || record?.playbackMode !== "compatibility") return record;
  return videoCompatibilityVariant(record) || record;
}

function setStoredFileResponseHeaders(record, res) {
  const fileId = String(record.fileId || "file");
  const totalSize = Number(record.size || 0);
  res.type(effectiveStoredMimeType(record));
  res.setHeader("Accept-Ranges", "bytes");
  res.setHeader("Cache-Control", "private, max-age=86400, immutable");
  res.setHeader("ETag", `\"${fileId}-${totalSize}\"`);
  if (record.createdAt) {
    const createdMs = Date.parse(record.createdAt);
    if (Number.isFinite(createdMs)) res.setHeader("Last-Modified", new Date(createdMs).toUTCString());
  }
  const inline = ["image", "gif", "video", "audio", "pdf"].includes(record.fileType);
  const safeName = String(record.originalName || "file").replace(/["\r\n]/g, "_");
  res.setHeader(
    "Content-Disposition",
    `${inline ? "inline" : "attachment"}; filename*=UTF-8''${encodeURIComponent(safeName)}`
  );
}

function setVideoCompatibilityCachePolicy(record, playbackRecord, req, res) {
  const requestedCompatibility = String(req?.query?.playback || "").toLowerCase() === "compatible";
  const variantReady = record?.fileType === "video"
    && record.playbackStatus === "ready"
    && record.playbackMode === "compatibility"
    && playbackRecord !== record;
  // Before conversion completes, do not let the browser keep the original
  // HEVC response forever under the compatibility URL. The ready event also
  // adds a version query, but this short cache makes refresh/reopen reliable.
  if (requestedCompatibility && !variantReady) {
    res.setHeader("Cache-Control", "private, max-age=5, must-revalidate");
  }
}

function serveLocalStoredFile(fullPath, record, req, res) {
  let totalSize = Number(record.size || 0);
  try {
    if (!totalSize) totalSize = fs.statSync(fullPath).size;
  } catch {
    return false;
  }
  const range = parseHttpByteRange(req.headers.range, totalSize);
  if (range?.invalid) {
    res.status(416).setHeader("Content-Range", `bytes */${totalSize}`);
    res.end();
    return true;
  }
  if (range) {
    res.status(206);
    res.setHeader("Content-Range", `bytes ${range.start}-${range.end}/${totalSize}`);
    res.setHeader("Content-Length", String(range.end - range.start + 1));
    const stream = fs.createReadStream(fullPath, { start: range.start, end: range.end });
    res.on("close", () => stream.destroy());
    stream.pipe(res);
    return true;
  }
  res.setHeader("Content-Length", String(totalSize));
  const stream = fs.createReadStream(fullPath);
  res.on("close", () => stream.destroy());
  stream.pipe(res);
  return true;
}

async function redirectR2StoredFile(record, req, res) {
  if (record?.storage !== "r2" || !record.r2Key || !objectStorage.isConfigured()) return false;
  try {
    if (req.method === "HEAD") {
      const metadata = await objectStorage.headObject({ key: record.r2Key });
      if (metadata.size > 0) res.setHeader("Content-Length", String(metadata.size));
      res.status(200).end();
      return true;
    }
    const url = await objectStorage.getSignedDownloadUrl({
      key: record.r2Key,
      mimeType: effectiveStoredMimeType(record),
      fileName: record.originalName,
      inline: ["image", "gif", "video", "audio", "pdf"].includes(record.fileType)
    });
    // The browser follows this short-lived signed URL directly to R2. Media
    // bytes therefore bypass the Node process and its hosting bandwidth.
    res.redirect(302, url);
    return true;
  } catch (err) {
    console.warn("R2 media access failed:", err?.message || err);
    if (!res.headersSent) res.status(404).json({ error: "الملف غير موجود في التخزين الخارجي" });
    return true;
  }
}

function resolveAuthorizedUpload(req, res) {
  const record = db.uploads[req.params.fileId];
  if (!record) {
    res.status(404).json({ error: "الملف غير موجود" });
    return null;
  }
  if (!canViewerOpenUpload(record, req.authUser)) {
    res.status(403).json({ error: "لا تملك صلاحية فتح هذا الملف" });
    return null;
  }
  return record;
}

app.head("/api/files/:fileId", requireHttpAuth, async (req, res) => {
  const record = resolveAuthorizedUpload(req, res);
  if (!record) return;
  if (record.fileType === "video" && !record.playbackStatus) queueVideoCompatibilityJob(record.fileId);
  const playbackRecord = selectVideoPlaybackRecord(record, req);
  setStoredFileResponseHeaders(playbackRecord, res);
  setVideoCompatibilityCachePolicy(record, playbackRecord, req, res);
  if (await redirectR2StoredFile(playbackRecord, req, res)) return;
  if (Number(playbackRecord.size || 0) > 0) res.setHeader("Content-Length", String(playbackRecord.size));
  res.status(200).end();
});

app.get("/api/files/:fileId", requireHttpAuth, async (req, res) => {
  const record = resolveAuthorizedUpload(req, res);
  if (!record) return;
  if (record.fileType === "video" && !record.playbackStatus) queueVideoCompatibilityJob(record.fileId);

  const playbackRecord = selectVideoPlaybackRecord(record, req);
  setStoredFileResponseHeaders(playbackRecord, res);
  setVideoCompatibilityCachePolicy(record, playbackRecord, req, res);
  const etag = `\"${String(playbackRecord.fileId || "file")}-${Number(playbackRecord.size || 0)}\"`;
  if (!req.headers.range && req.headers["if-none-match"] === etag) return res.status(304).end();

  if (await redirectR2StoredFile(playbackRecord, req, res)) return;

  // Prefer the bounded ephemeral cache immediately after upload. This avoids a
  // remote GridFS round-trip for every browser byte-range seek while a newly
  // shared video is being watched. If the cache has expired or Render restarted,
  // transparently fall back to GridFS.
  if (playbackRecord.cacheStoredName) {
    const cachePath = path.join(UPLOAD_DIR, path.basename(playbackRecord.cacheStoredName));
    if (fs.existsSync(cachePath)) {
      return serveLocalStoredFile(cachePath, playbackRecord, req, res);
    }
  }

  if (playbackRecord.storage === "gridfs" && playbackRecord.gridFsId) {
    if (!streamGridFsFile(playbackRecord, req, res)) {
      return res.status(404).json({ error: "الملف غير موجود في التخزين السحابي" });
    }
    return;
  }

  const fullPath = path.join(UPLOAD_DIR, path.basename(playbackRecord.storedName || ""));
  if (!playbackRecord.storedName || !fs.existsSync(fullPath)) {
    return res.status(404).json({ error: "الملف غير موجود على الخادم" });
  }
  serveLocalStoredFile(fullPath, playbackRecord, req, res);
});

