// Account settings + owner-managed avatar frames
// =========================================================
app.get("/api/settings/me", requireHttpAuth, (req, res) => {
  const profile = publicUserProfile(req.authUser);
  res.json({
    success: true,
    ...profile,
    permissions: getUserPermissions(req.authUser)
  });
});

app.post("/api/settings/profile", requireHttpAuth, (req, res) => {
  try {
    const user = db.users[req.authUser];
    const displayName = String(req.body.displayName || "").trim();
    if (displayName.length < 1 || displayName.length > 60) {
      return res.status(400).json({ error: "الاسم يجب أن يكون بين 1 و60 حرفاً" });
    }
    user.displayName = displayName;
    saveDB(db);
    io.to(`user_${req.authUser}`).emit("profile-updated", publicUserProfile(req.authUser));
    res.json({ success: true, profile: publicUserProfile(req.authUser) });
  } catch (err) {
    res.status(500).json({ error: "تعذر تحديث الاسم" });
  }
});

app.post("/api/settings/password", authLimiter, requireHttpAuth, (req, res) => {
  try {
    const user = db.users[req.authUser];
    const currentPassword = String(req.body.currentPassword || "");
    const newPassword = String(req.body.newPassword || "");
    if (!verifyPassword(currentPassword, user.password)) {
      return res.status(401).json({ error: "كلمة المرور الحالية غير صحيحة" });
    }
    const validation = validatePassword(newPassword);
    if (!validation.valid) return res.status(400).json({ error: validation.error });
    if (currentPassword === newPassword) {
      return res.status(400).json({ error: "اختر كلمة مرور جديدة مختلفة" });
    }
    user.password = hashPassword(newPassword);
    user.passwordChangedAt = new Date().toISOString();

    // Keep only the current browser session.
    for (const [token, session] of Object.entries(db.sessions || {})) {
      if (session.username === req.authUser && token !== req.sessionToken) delete db.sessions[token];
    }
    saveDB(db);
    res.json({ success: true, message: "تم تغيير كلمة المرور" });
  } catch (err) {
    res.status(500).json({ error: "تعذر تغيير كلمة المرور" });
  }
});

app.post("/api/settings/avatar", requireHttpAuth, (req, res) => {
  const user = db.users[req.authUser];
  const fileId = String(req.body.fileId || "");
  const file = db.uploads[fileId];
  if (!file || file.uploader !== req.authUser || file.context !== "avatar") {
    return res.status(400).json({ error: "صورة الحساب غير صالحة" });
  }
  user.avatar = `/api/files/${encodeURIComponent(fileId)}`;
  user.avatarFileId = fileId;
  saveDB(db);
  const profile = publicUserProfile(req.authUser);
  io.emit("profile-updated", profile);
  res.json({ success: true, profile });
});

app.get("/api/frames", requireHttpAuth, (_req, res) => {
  const list = Object.values(db.frames || {})
    .filter(Boolean)
    .sort((a, b) => Date.parse(b.createdAt || 0) - Date.parse(a.createdAt || 0));
  res.json({ success: true, frames: list });
});

function canManageAvatarFrames(username) {
  return username === PLATFORM_OWNER_USERNAME || hasPermission(username, "manage_frames");
}

function canManageFrameAssignment(actor, targetUser) {
  if (!canManageAvatarFrames(actor)) return false;
  // Only the platform owner can change the owner's frame. This keeps a
  // delegated frame manager from modifying the highest-privilege account.
  return actor === PLATFORM_OWNER_USERNAME || targetUser !== PLATFORM_OWNER_USERNAME;
}

app.post("/api/admin/frames", requireHttpAuth, (req, res) => {
  if (req.authUser !== PLATFORM_OWNER_USERNAME) {
    return res.status(403).json({ error: "إدارة الإطارات متاحة للمالك فقط" });
  }
  const fileId = String(req.body.fileId || "");
  const name = String(req.body.name || "إطار جديد").trim().slice(0, 60);
  const file = db.uploads[fileId];
  if (!file || file.context !== "frame" || file.uploader !== req.authUser) {
    return res.status(400).json({ error: "ملف الإطار غير صالح" });
  }
  const frameId = "frm_" + crypto.randomBytes(8).toString("hex");
  db.frames[frameId] = {
    frameId,
    name: name || "إطار جديد",
    fileId,
    url: `/api/files/${encodeURIComponent(fileId)}`,
    animated: file.fileType === "gif",
    createdBy: req.authUser,
    createdAt: new Date().toISOString()
  };
  saveDB(db);
  res.json({ success: true, frame: db.frames[frameId] });
});

app.delete("/api/admin/frames/:frameId", requireHttpAuth, (req, res) => {
  if (req.authUser !== PLATFORM_OWNER_USERNAME) {
    return res.status(403).json({ error: "إدارة الإطارات متاحة للمالك فقط" });
  }
  const frameId = req.params.frameId;
  if (!db.frames?.[frameId]) return res.status(404).json({ error: "الإطار غير موجود" });
  delete db.frames[frameId];
  for (const user of Object.values(db.users || {})) {
    if (user?.frameAssignment?.frameId === frameId) delete user.frameAssignment;
  }
  saveDB(db);
  io.emit("frames-updated");
  res.json({ success: true });
});

app.post("/api/admin/frames/assign", requireHttpAuth, (req, res) => {
  const username = String(req.body.username || "").trim();
  const frameId = String(req.body.frameId || "").trim();
  if (!canManageFrameAssignment(req.authUser, username)) {
    return res.status(403).json({ error: "لا تملك صلاحية منح الإطارات" });
  }
  const permanent = !!req.body.permanent;
  const durationDays = Math.max(1, Math.min(3650, Number.parseInt(req.body.durationDays, 10) || 1));

  if (!db.users?.[username]) return res.status(404).json({ error: "المستخدم غير موجود" });
  if (!db.frames?.[frameId]) return res.status(404).json({ error: "الإطار غير موجود" });

  const assignedAt = new Date();
  db.users[username].frameAssignment = {
    frameId,
    assignedBy: req.authUser,
    assignedAt: assignedAt.toISOString(),
    permanent,
    expiresAt: permanent ? null : new Date(assignedAt.getTime() + durationDays * 86400000).toISOString()
  };
  saveDB(db);
  const profile = publicUserProfile(username);
  io.emit("profile-updated", profile);
  res.json({ success: true, profile });
});

app.post("/api/admin/frames/remove", requireHttpAuth, (req, res) => {
  const username = String(req.body.username || "").trim();
  if (!canManageFrameAssignment(req.authUser, username)) {
    return res.status(403).json({ error: "لا تملك صلاحية سحب الإطارات" });
  }
  if (!db.users?.[username]) return res.status(404).json({ error: "المستخدم غير موجود" });
  delete db.users[username].frameAssignment;
  saveDB(db);
  const profile = publicUserProfile(username);
  io.emit("profile-updated", profile);
  res.json({ success: true, profile });
});

// 🆕 NEW API: Get all public rooms
app.get("/api/public-rooms", (req, res) => {
  try {
    const rooms = [];
    for (const rId in db.rooms) {
      const room = db.rooms[rId];
      if (!room.isPrivate) {
        rooms.push({
          roomId: rId,
          roomName: room.roomName || "غرفة عامة",
          owner: room.owner,
          maxUsers: room.maxUsers || 24,
          memberCount: room.members ? room.members.length : 0,
          shareCode: room.shareCode || null,
          createdAt: room.createdAt
        });
      }
    }
    res.json(rooms);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// 🆕 NEW API: Join room by share code
app.post("/api/join-by-code", requireHttpAuth, (req, res) => {
  try {
    const { shareCode } = req.body;
    const userId = req.authUser;
    if (!shareCode) return res.status(400).json({ error: "رمز الغرفة مطلوب" });

    const found = findPublicRoomByIdOrCode(shareCode);
    if (!found) return res.status(404).json({ error: "رمز المشاركة غير صالح" });

    const { roomId, room } = found;
    const banCheck = checkRoomBan(roomId, userId);
    if (banCheck.banned) {
      return res.status(403).json({ error: "أنت محظور من هذه الغرفة", ban: banCheck });
    }

    if (!Array.isArray(room.members)) room.members = [];
    const limit = normalizeMaxUsers(room.maxUsers, 24);

    if (!room.members.includes(userId) && room.members.length >= limit) {
      return res.status(409).json({ error: "الغرفة ممتلئة." });
    }

    if (!room.members.includes(userId)) {
      room.members.push(userId);
      room.updatedAt = new Date().toISOString();
      saveDB(db);
    }

    res.json({
      success: true,
      roomId,
      roomName: room.roomName,
      shareCode: room.shareCode || roomId,
      maxUsers: limit,
      isHost: room.owner === userId
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// 🆕 NEW API: Get room by share code
app.get("/api/room-by-code/:shareCode", (req, res) => {
  try {
    const found = findPublicRoomByIdOrCode(req.params.shareCode);
    if (!found) return res.status(404).json({ error: "الغرفة غير موجودة" });

    const { roomId, room } = found;
    return res.json({
      roomId,
      roomName: room.roomName,
      owner: room.owner,
      maxUsers: normalizeMaxUsers(room.maxUsers, 24),
      memberCount: Array.isArray(room.members) ? room.members.length : 0,
      shareCode: room.shareCode || roomId
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// 🆕 NEW API: Get user's chat history / conversations window
app.get("/api/my-conversations/:username", requireHttpAuth, (req, res) => {
  try {
    const username = req.params.username;
    if (username !== req.authUser && req.authUser !== PLATFORM_OWNER_USERNAME) {
      return res.status(403).json({ error: "لا تملك صلاحية عرض محادثات مستخدم آخر" });
    }
    const conversations = [];

    // 1. Private chats (friends)
    for (const key in db.friends) {
      const f = db.friends[key];
      if (f.user1 === username || f.user2 === username) {
        const partner = f.user1 === username ? f.user2 : f.user1;
        const roomId = getPrivateRoomId(username, partner);
        const history = db.roomHistory[roomId] || [];
        const lastMsg = history.length > 0 ? history[history.length - 1] : null;

        conversations.push({
          roomId,
          name: db.users[partner] ? (db.users[partner].displayName || partner) : partner,
          type: "private",
          partner,
          isOnline: activeOnlineUsers.has(partner),
          lastMessage: lastMsg ? (lastMsg.type === "text" ? lastMsg.msg : "[ميديا]") : "ابدأ المحادثة الآن",
          time: lastMsg ? lastMsg.time : "",
          unread: countUnreadMessages(roomId, username)
        });
      }
    }

    // 2. Official TOMI platform inbox — exactly one canonical conversation per user.
    if (username !== PLATFORM_OWNER_USERNAME) {
      const rId = getPlatformInboxRoomId(username);
      const room = db.rooms[rId];
      if (room?.systemRoom && room.isPrivate && Array.isArray(room.members) && room.members.includes(username)) {
        const history = db.roomHistory[rId] || [];
        const lastMsg = history.length > 0 ? history[history.length - 1] : null;
        conversations.push({
          roomId: rId,
          name: "TOMI • حساب المنصة",
          roomName: "TOMI • حساب المنصة",
          type: "system",
          partner: null,
          isPrivate: true,
          systemRoom: true,
          isOnline: true,
          lastMessage: lastMsg ? (lastMsg.type === "text" ? lastMsg.msg : "[ميديا]") : "رسائل رسمية من TOMI",
          time: lastMsg ? lastMsg.time : "",
          updatedAt: getLastActivityIso(rId, room.updatedAt || room.createdAt || null),
          unread: countUnreadMessages(rId, username)
        });
      }
    }

    // 3. Public rooms
    for (const rId in db.rooms) {
      const room = db.rooms[rId];
      if (!room.isPrivate && room.members && room.members.includes(username)) {
        const history = db.roomHistory[rId] || [];
        const lastMsg = history.length > 0 ? history[history.length - 1] : null;

        conversations.push({
          roomId: rId,
          name: room.roomName || "غرفة عامة",
          type: "public",
          owner: room.owner,
          shareCode: room.shareCode || null,
          maxUsers: room.maxUsers || 24,
          memberCount: room.members ? room.members.length : 0,
          lastMessage: lastMsg ? (lastMsg.type === "text" ? lastMsg.msg : "[ميديا]") : "لا توجد رسائل بعد",
          time: lastMsg ? lastMsg.time : "",
          unread: countUnreadMessages(rId, username)
        });
      }
    }

    // Sort by last message time (newest first)
    conversations.sort((a, b) => {
      if (!a.time) return 1;
      if (!b.time) return -1;
      return new Date(b.time) - new Date(a.time);
    });

    res.json({ conversations, hasChats: conversations.length > 0 });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

