// =========================================================
// 5. Socket.io Events
// =========================================================
function bindSocketUser(socket, username) {
  const user = db.users[username];
  if (!user) return false;

  socket.username = username;
  socket.userId = username;
  socket.role = getPublicRole(username);
  socket.join(`user_${username}`);

  if (!activeOnlineUsers.has(username)) {
    activeOnlineUsers.set(username, new Set());
  }
  activeOnlineUsers.get(username).add(socket.id);

  user.lastSeen = new Date().toISOString();
  user.status = "online";
  analyticsService?.socketConnected(socket.id, username);
  saveDB(db);
  // Invitations are persisted, so a phone that was offline can still receive
  // its room invitation as soon as the Socket.IO session is restored.
  setImmediate(() => emitPendingVoiceRoomInvites(username));
  return true;
}

io.use((socket, next) => {
  try {
    const cookieToken = parseCookies(socket.handshake.headers.cookie || "").chat_session;
    const authToken = socket.handshake.auth?.sessionToken;
    const session = getSession(authToken || cookieToken);

    if (session && db.users[session.username]) {
      const ban = checkPlatformBan(session.username);
      if (!ban.banned) {
        socket.sessionToken = authToken || cookieToken;
        socket.sessionUser = session.username;
        socket.userId = session.username;
        socket.username = session.username;
        socket.role = getPublicRole(session.username);
      }
    }
  } catch (err) {
    console.error("Socket session check failed:", err.message);
  }
  next();
});

function attachSocketToConversation(socket, roomId) {
  if (!socket || !roomId) return;

  const previousRoomId = socket.roomId;

  if (previousRoomId && previousRoomId !== roomId) {
    socket.leave(previousRoomId);
  }

  socket.join(roomId);
  socket.roomId = roomId;

  if (previousRoomId && previousRoomId !== roomId) {
    setImmediate(() => broadcastRoomUsers(previousRoomId));
  }
}


// =========================================================
// Voice Rooms: public server-wide rooms with seats + room moderation
// =========================================================
const VOICE_ROOM_SEAT_COUNT = 8;
const VOICE_ROOM_EMPTY_TTL_MS = Math.max(
  60 * 1000,
  Number(process.env.VOICE_ROOM_EMPTY_TTL_MS || 10 * 60 * 1000) || 10 * 60 * 1000
);
const VOICE_ROOM_INVITE_TTL_MS = Math.max(
  5 * 60 * 1000,
  Number(process.env.VOICE_ROOM_INVITE_TTL_MS || 30 * 60 * 1000) || 30 * 60 * 1000
);
const voiceRoomRuntime = new Map();

function getVoiceRoomRuntime(roomId) {
  if (!voiceRoomRuntime.has(roomId)) {
    voiceRoomRuntime.set(roomId, {
      members: new Map(), // username -> Set(socket.id)
      seats: new Map(),   // seat number -> username
      lockedSeats: new Set(),
      mutedUsers: new Set()
    });
  }
  return voiceRoomRuntime.get(roomId);
}

function hashVoiceRoomCode(value) {
  return crypto.createHash("sha256").update(String(value || "")).digest("hex");
}

function isVoiceRoomModerator(room, username) {
  if (!room || !username) return false;
  return canManagePlatformRooms(username) ||
    room.owner === username ||
    (Array.isArray(room.moderators) && room.moderators.includes(username));
}

function mayActOnVoiceRoomTarget(room, actor, target) {
  if (!room || !actor || !target || actor === target) return false;
  if (actor === PLATFORM_OWNER_USERNAME) return true;
  if (isProtectedPlatformUser(target)) return false;
  if (room.owner === actor) return target !== room.owner;
  if (hasPermission(actor, "manage_rooms")) {
    // Platform staff can manage a room without replacing its owner. The
    // platform owner remains the escalation path for removing room owners.
    return target !== room.owner;
  }
  if (!Array.isArray(room.moderators) || !room.moderators.includes(actor)) return false;
  // A room moderator can manage normal members, but cannot act on owner or
  // another room moderator.
  if (room.owner === target) return false;
  if (room.moderators.includes(target)) return false;
  return true;
}

function getActiveVoiceRoomBan(roomId, username) {
  const entry = db.voiceRoomBans?.[roomId]?.[username];
  if (!entry?.banned) return null;

  if (entry.expiresAt) {
    const expiresAtMs = Date.parse(entry.expiresAt);
    if (Number.isFinite(expiresAtMs) && expiresAtMs <= Date.now()) {
      delete db.voiceRoomBans[roomId][username];
      if (Object.keys(db.voiceRoomBans[roomId] || {}).length === 0) {
        delete db.voiceRoomBans[roomId];
      }
      saveDB(db);
      return null;
    }
  }

  return entry;
}

function voiceRoomMemberProfile(room, username) {
  const user = db.users?.[username] || {};
  return {
    username,
    displayName: user.displayName || username,
    avatar: user.avatar || "",
    role: username === room.owner ? "owner" :
      (Array.isArray(room.moderators) && room.moderators.includes(username) ? "moderator" : "listener"),
    platformRole: getPublicRole(username),
    platformProtected: isProtectedPlatformUser(username)
  };
}

function voiceRoomPublic(roomId) {
  const room = db.voiceRooms?.[roomId];
  if (!room) return null;
  const runtime = getVoiceRoomRuntime(roomId);
  const members = Array.from(runtime.members.keys());
  const seats = Array.from({ length: VOICE_ROOM_SEAT_COUNT }, (_, i) => {
    const seatNo = i + 1;
    const username = runtime.seats.get(seatNo) || null;
    const user = username ? (db.users[username] || {}) : null;
    return {
      seat: seatNo,
      locked: runtime.lockedSeats.has(seatNo),
      username,
      displayName: username ? (user?.displayName || username) : "",
      avatar: username ? (user?.avatar || "") : "",
      frame: username ? getActiveFrame(username) : null,
      muted: username ? runtime.mutedUsers.has(username) : false,
      role: username ? (
        username === room.owner ? "owner" :
        (room.moderators || []).includes(username) ? "moderator" : "user"
      ) : null
    };
  });
  return {
    id: roomId,
    name: room.name || "غرفة صوتية",
    owner: room.owner,
    moderators: Array.isArray(room.moderators) ? room.moderators : [],
    image: room.imageFileId ? `/api/files/${encodeURIComponent(room.imageFileId)}` : (room.image || ""),
    protected: Boolean(room.codeHash),
    createdAt: room.createdAt,
    memberCount: members.length,
    members,
    memberProfiles: members.map(username => voiceRoomMemberProfile(room, username)),
    seats
  };
}

function listVoiceRooms() {
  return Object.keys(db.voiceRooms || {})
    .map(id => voiceRoomPublic(id))
    .filter(Boolean)
    .sort((a, b) => String(b.createdAt || "").localeCompare(String(a.createdAt || "")));
}

function emitVoiceRoomsList() {
  io.emit("voice-rooms-list", listVoiceRooms());
}

function emitVoiceRoomState(roomId) {
  const state = voiceRoomPublic(roomId);
  if (!state) return;
  io.to(`voice_${roomId}`).emit("voice-room-state", state);
  emitVoiceRoomsList();
}

function markVoiceRoomPresence(roomId, hasMembers) {
  const room = db.voiceRooms?.[roomId];
  if (!room) return;
  const now = new Date().toISOString();
  if (hasMembers) {
    if (room.emptySince) delete room.emptySince;
    room.lastActiveAt = now;
  } else if (!room.emptySince) {
    room.emptySince = now;
  }
  room.updatedAt = now;
  saveDB(db);
}

function hashVoiceInviteToken(value) {
  return crypto.createHash("sha256").update(String(value || "")).digest("hex");
}

function cleanVoiceRoomInvites(now = Date.now()) {
  if (!db.voiceRoomInvites || typeof db.voiceRoomInvites !== "object") {
    db.voiceRoomInvites = {};
    return false;
  }
  let changed = false;
  for (const [username, invites] of Object.entries(db.voiceRoomInvites)) {
    const next = (Array.isArray(invites) ? invites : []).filter(invite => {
      const valid = invite && db.voiceRooms?.[invite.roomId] && Date.parse(invite.expiresAt || "") > now;
      if (!valid) changed = true;
      return valid;
    }).slice(-20);
    if (next.length) {
      if (next.length !== (Array.isArray(invites) ? invites.length : 0)) changed = true;
      db.voiceRoomInvites[username] = next;
    } else if (db.voiceRoomInvites[username]) {
      delete db.voiceRoomInvites[username];
      changed = true;
    }
  }
  return changed;
}

function voiceInvitePayload(invite, room) {
  const inviter = publicUserProfile(invite.invitedBy);
  return {
    inviteId: invite.id,
    roomId: invite.roomId,
    roomName: room?.name || "غرفة صوتية",
    owner: room?.owner || "",
    roomProtected: Boolean(room?.codeHash),
    invitedBy: invite.invitedBy,
    inviter,
    expiresAt: invite.expiresAt,
    inviteToken: invite.token,
    url: `/voice-rooms.html?room=${encodeURIComponent(invite.roomId)}&inviteId=${encodeURIComponent(invite.id)}&inviteToken=${encodeURIComponent(invite.token)}`
  };
}

function emitPendingVoiceRoomInvites(username) {
  const invites = Array.isArray(db.voiceRoomInvites?.[username]) ? db.voiceRoomInvites[username] : [];
  const now = Date.now();
  for (const invite of invites) {
    const room = db.voiceRooms?.[invite.roomId];
    if (!room || Date.parse(invite.expiresAt || "") <= now) continue;
    io.to(`user_${username}`).emit("voice-room-invitation", voiceInvitePayload(invite, room));
  }
}

function consumeVoiceRoomInvite(username, roomId, inviteId, token) {
  const invites = Array.isArray(db.voiceRoomInvites?.[username]) ? db.voiceRoomInvites[username] : [];
  const index = invites.findIndex(invite =>
    invite?.id === inviteId && invite.roomId === roomId &&
    Date.parse(invite.expiresAt || "") > Date.now() &&
    (invite.tokenHash === hashVoiceInviteToken(token) || invite.token === token)
  );
  if (index < 0) return false;
  invites.splice(index, 1);
  if (invites.length) db.voiceRoomInvites[username] = invites;
  else delete db.voiceRoomInvites[username];
  saveDB(db);
  return true;
}

function cleanupVoiceRoomSocket(socket) {
  const roomId = socket.voiceRoomId;
  const username = socket.userId;
  if (!roomId || !username) return;
  const runtime = voiceRoomRuntime.get(roomId);
  if (!runtime) return;

  const sockets = runtime.members.get(username);
  if (sockets) {
    sockets.delete(socket.id);
    if (sockets.size === 0) {
      runtime.members.delete(username);
      for (const [seatNo, occupant] of runtime.seats.entries()) {
        if (occupant === username) runtime.seats.delete(seatNo);
      }
      runtime.mutedUsers.delete(username);
      io.to(`voice_${roomId}`).emit("voice-room-peer-left", { roomId, username });
    }
  }
  socket.leave(`voice_${roomId}`);
  socket.voiceRoomId = null;
  if (runtime.members.size === 0) markVoiceRoomPresence(roomId, false);
  emitVoiceRoomState(roomId);
}

app.get("/api/voice-rooms", requireHttpAuth, (_req, res) => {
  res.json({ success: true, rooms: listVoiceRooms() });
});

io.on("connection", (socket) => {
  // Lightweight server-side activity counters. Payload contents are ignored;
  // only the event category and room id are sent to the analytics service.
  socket.onAny((eventName, payload = {}) => {
    const actor = socket.userId || socket.sessionUser || "";
    if (!actor || !analyticsService) return;
    const roomId = typeof payload === "object" ? String(payload.roomId || "").slice(0, 120) : "";
    if (eventName === "user-message" || eventName === "send-uploaded-file") {
      analyticsService.track("message_sent", { userId: actor, roomId, feature: eventName });
    } else if (["join-room", "join-room-by-code", "voice-room-join"].includes(eventName)) {
      analyticsService.track("room_join", { userId: actor, roomId, feature: eventName });
    } else if (eventName === "call-offer") {
      analyticsService.track("call_start", { userId: actor, roomId, feature: "call" });
    }
  });

  if (socket.sessionUser) {
    bindSocketUser(socket, socket.sessionUser);
    broadcastOnlineUsers();
  }

  // 📝 Register via Socket
  socket.on("register", ({ username, password, displayName, refCode } = {}) => {
    try {
      const uVal = validateUsername(username);
      if (!uVal.valid) {
        socket.emit("register_result", { success: false, error: uVal.error });
        return;
      }

      const pVal = validatePassword(password);
      if (!pVal.valid) {
        socket.emit("register_result", { success: false, error: pVal.error });
        return;
      }

      if (db.users[uVal.username]) {
        socket.emit("register_result", { success: false, error: "اسم المستخدم موجود مسبقاً" });
        return;
      }

      db.users[uVal.username] = {
        username: uVal.username,
        password: hashPassword(password),
        role: "user",
        displayName: (displayName || uVal.username).trim().slice(0, 60),
        staffApproved: false,
        permissions: [],
        registeredAt: new Date().toISOString(),
        status: "online",
        lastSeen: new Date().toISOString()
      };
      analyticsService?.track("register", {
        userId: uVal.username,
        refCode: String(refCode || "").slice(0, 40),
        page: "/index.html"
      });
      saveDB(db);

      const sessionToken = issueSession(uVal.username);
      bindSocketUser(socket, uVal.username);

      socket.emit("register_result", {
        success: true,
        username: uVal.username,
        role: "user",
        displayName: db.users[uVal.username].displayName,
        badge: null,
        permissions: [],
        avatar: db.users[uVal.username].avatar || "",
        frame: getActiveFrame(uVal.username),
        referralCode: db.users[uVal.username].referralCode || "",
        sessionToken,
        message: "تم إنشاء الحساب بنجاح"
      });
      broadcastOnlineUsers();
    } catch (err) {
      socket.emit("register_result", { success: false, error: err.message });
    }
  });

  // 🔐 Login via Socket
  socket.on("login", ({ username, password, sessionToken } = {}) => {
    try {
      let cleanUsername = username?.trim() || socket.sessionUser || socket.userId || "";
      let user = db.users[cleanUsername];

      if (sessionToken) {
        const session = getSession(sessionToken);
        if (session && db.users[session.username]) {
          cleanUsername = session.username;
          user = db.users[cleanUsername];
          socket.sessionToken = sessionToken;
          socket.sessionUser = cleanUsername;
        }
      }

      // If the Socket.IO handshake already carried the HttpOnly session
      // cookie, a passwordless reconnect is allowed for that same account.
      const sessionAuthenticated =
        !!user &&
        (socket.sessionUser === cleanUsername || socket.userId === cleanUsername);

      if (!sessionAuthenticated) {
        if (!user || !password || !verifyPassword(password, user.password)) {
          socket.emit("login_result", {
            success: false,
            error: "اسم المستخدم أو كلمة المرور غير صحيحة"
          });
          return;
        }
        upgradePasswordHashIfNeeded(user, password);
      }

      const platformBan = checkPlatformBan(cleanUsername);
      if (platformBan.banned) {
        socket.emit("login_result", {
          success: false,
          error: "هذا الحساب محظور على المنصة",
          ban: platformBan
        });
        return;
      }

      bindSocketUser(socket, cleanUsername);
      analyticsService?.track("login", { userId: cleanUsername, page: "/index.html" });

      const stats = getUserStats(cleanUsername);
      socket.emit("login_result", {
        success: true,
        username: user.username,
        role: getPublicRole(user.username),
        displayName: user.displayName,
        badge: getPlatformBadge(user.username),
        permissions: getUserPermissions(user.username),
        avatar: user.avatar || "",
        frame: getActiveFrame(user.username),
        referralCode: user.referralCode || "",
        sessionToken: socket.sessionToken || null,
        stats
      });
      broadcastOnlineUsers();
    } catch (err) {
      socket.emit("login_result", { success: false, error: err.message });
    }
  });

  // --- 1. Friends Management ---

  socket.on("search_users", ({ query, currentUser }) => {
    try {
      const actor = socket.userId || currentUser;
      if (!actor) return socket.emit("search_results", []);

      const searchQuery = query ? query.trim().toLowerCase() : "";
      const results = [];

      for (const username in db.users) {
        if (username === actor) continue;
        const user = db.users[username];

        if (
          !searchQuery ||
          username.toLowerCase().includes(searchQuery) ||
          (user.displayName && user.displayName.toLowerCase().includes(searchQuery))
        ) {
          const role = getPublicRole(username);
          results.push({
            username: user.username,
            displayName: user.displayName,
            role,
            badge: getPlatformBadge(username),
            avatar: user.avatar || "",
            frame: getActiveFrame(username),
            isOnline: activeOnlineUsers.has(user.username),
            isModerator: ["owner", "admin", "moderator"].includes(role)
          });
        }
      }

      results.sort((a, b) => {
        const rank = { owner: 0, admin: 1, moderator: 2, user: 3 };
        return (rank[a.role] ?? 9) - (rank[b.role] ?? 9);
      });

      socket.emit("search_results", results.slice(0, 30));
    } catch (err) {
      console.error("خطأ في البحث:", err.message);
      socket.emit("search_results", []);
    }
  });

  socket.on("send_friend_request", ({ fromUser, toUser }) => {
    const actor = socket.userId;
    if (!actor || !toUser || actor === toUser) return;
    if (fromUser && fromUser !== actor) return;
    try {
      fromUser = actor;
      const key = fromUser + "_" + toUser;
      if (!db.friendRequests) db.friendRequests = {};
      if (!db.friendRequests[key]) {
        db.friendRequests[key] = { fromUser, toUser, createdAt: new Date().toISOString() };
        saveDB(db);
      }
      io.to(`user_${toUser}`).emit("new_friend_request_received", { fromUser, toUser });

      const fromStats = getUserStats(fromUser);
      const toStats = getUserStats(toUser);
      socket.emit("user_stats", fromStats);
      io.to(`user_${toUser}`).emit("user_stats", toStats);
    } catch (err) {
      console.error("خطأ إرسال طلب الصداقة:", err.message);
    }
  });

  socket.on("get_friend_requests", (username) => {
    const actor = socket.userId;
    if (!actor) return;
    if (username && username !== actor) return;
    username = actor;
    try {
      const requests = [];
      for (const key in db.friendRequests) {
        if (db.friendRequests[key].toUser === username) {
          requests.push(db.friendRequests[key].fromUser);
        }
      }
      socket.emit("friend_requests_list", requests);
    } catch (err) {
      console.error("خطأ جلب طلبات الصداقة:", err.message);
    }
  });

  socket.on("accept_friend_request", ({ currentUser, targetUser }) => {
    const actor = socket.userId;
    if (!actor || !targetUser) return;
    if (currentUser && currentUser !== actor) return;
    currentUser = actor;
    try {
      const [u1, u2] = [currentUser, targetUser].sort();
      const friendKey = u1 + "_" + u2;
      if (!db.friends) db.friends = {};
      if (!db.friends[friendKey]) {
        db.friends[friendKey] = { user1: u1, user2: u2, createdAt: new Date().toISOString() };
      }

      // Remove friend request
      const reqKey1 = targetUser + "_" + currentUser;
      const reqKey2 = currentUser + "_" + targetUser;
      if (db.friendRequests[reqKey1]) delete db.friendRequests[reqKey1];
      if (db.friendRequests[reqKey2]) delete db.friendRequests[reqKey2];
      saveDB(db);

      const roomId = getPrivateRoomId(currentUser, targetUser);

      // Explicit server-side membership for the one-to-one private room.
      if (!db.privateChats[roomId]) {
        db.privateChats[roomId] = {
          roomId,
          members: [u1, u2],
          isPrivate: true,
          createdAt: new Date().toISOString()
        };
      }

      ensurePrivateRoomDocument(roomId);
      saveDB(db);

      socket.emit("friend_request_accepted", { user1: currentUser, user2: targetUser, roomId });
      io.to(`user_${targetUser}`).emit("friend_request_accepted", { user1: currentUser, user2: targetUser, roomId });

      socket.emit("chat_created", { roomId, partner: targetUser });
      io.to(`user_${targetUser}`).emit("chat_created", { roomId, partner: currentUser });

      socket.emit("friends_updated");
      io.to(`user_${targetUser}`).emit("friends_updated");

      const currentStats = getUserStats(currentUser);
      const targetStats = getUserStats(targetUser);
      socket.emit("user_stats", currentStats);
      io.to(`user_${targetUser}`).emit("user_stats", targetStats);
    } catch (err) {
      console.error("خطأ قبول طلب الصداقة:", err.message);
    }
  });

  socket.on("reject_friend_request", ({ currentUser, targetUser }) => {
    const actor = socket.userId;
    if (!actor || !targetUser) return;
    if (currentUser && currentUser !== actor) return;
    currentUser = actor;
    try {
      const reqKey = targetUser + "_" + currentUser;
      if (db.friendRequests[reqKey]) delete db.friendRequests[reqKey];
      saveDB(db);

      const requests = [];
      for (const key in db.friendRequests) {
        if (db.friendRequests[key].toUser === currentUser) {
          requests.push(db.friendRequests[key].fromUser);
        }
      }
      socket.emit("friend_requests_list", requests);

      const stats = getUserStats(currentUser);
      socket.emit("user_stats", stats);
    } catch (err) {
      console.error("خطأ رفض طلب الصداقة:", err.message);
    }
  });

  // 🧾 نافذة المحادثات: الخاصة + الغرف العامة
  socket.on("get_my_chats", (currentUser) => {
    const actor = socket.userId;
    if (!actor) return;
    if (currentUser && currentUser !== actor) return;
    currentUser = actor;

    try {
      const userChats = [];

      // 1) Private chats between accepted friends
      for (const key in db.friends) {
        const f = db.friends[key];
        if (!f || (f.user1 !== currentUser && f.user2 !== currentUser)) continue;

        const partner = f.user1 === currentUser ? f.user2 : f.user1;
        const roomId = getPrivateRoomId(currentUser, partner);

        if (!db.privateChats[roomId]) {
          db.privateChats[roomId] = {
            roomId,
            members: [f.user1, f.user2],
            isPrivate: true,
            createdAt: f.createdAt || new Date().toISOString()
          };
        }

        ensurePrivateRoomDocument(roomId);

        const history = db.roomHistory[roomId] || [];
        const lastMsg = history.length > 0 ? history[history.length - 1] : null;

        userChats.push({
          roomId,
          partner,
          roomName: db.users[partner] ? (db.users[partner].displayName || partner) : partner,
          type: "private",
          isPrivate: true,
          isOnline: activeOnlineUsers.has(partner),
          isHost: false,
          lastMessage: lastMsg
            ? (lastMsg.type === "text" ? lastMsg.msg : "[ميديا]")
            : "ابدأ المحادثة الآن",
          time: lastMsg ? (lastMsg.time || "") : "",
          updatedAt: getLastActivityIso(roomId, f.createdAt || null),
          unread: countUnreadMessages(roomId, currentUser)
        });
      }

      // 2) Official TOMI platform inbox — exactly one canonical conversation per user.
      if (currentUser !== PLATFORM_OWNER_USERNAME) {
        const rId = getPlatformInboxRoomId(currentUser);
        const room = db.rooms[rId];
        if (room?.systemRoom && room.isPrivate) {
          const members = Array.isArray(room.members) ? room.members : [];
          if (members.includes(currentUser)) {
            const history = db.roomHistory[rId] || [];
            const lastMsg = history.length > 0 ? history[history.length - 1] : null;
            userChats.push({
              roomId: rId,
              partner: null,
              roomName: "TOMI • حساب المنصة",
              type: "system",
              isPrivate: true,
              systemRoom: true,
              isOnline: true,
              isHost: false,
              lastMessage: lastMsg ? (lastMsg.type === "text" ? lastMsg.msg : "[ميديا]") : "رسائل رسمية من TOMI",
              time: lastMsg ? (lastMsg.time || "") : "",
              updatedAt: getLastActivityIso(rId, room.updatedAt || room.createdAt || null),
              unread: countUnreadMessages(rId, currentUser)
            });
          }
        }
      }

      // 3) Public rooms owned/joined by the user
      for (const rId in db.rooms) {
        const room = db.rooms[rId];
        if (!room || room.isPrivate) continue;

        const members = Array.isArray(room.members) ? room.members : [];
        if (!members.includes(currentUser)) continue;

        const history = db.roomHistory[rId] || [];
        const lastMsg = history.length > 0 ? history[history.length - 1] : null;

        userChats.push({
          roomId: rId,
          partner: null,
          roomName: room.roomName || "غرفة عامة",
          type: "public",
          isPrivate: false,
          owner: room.owner || null,
          isHost: room.owner === currentUser,
          maxUsers: normalizeMaxUsers(room.maxUsers, 24),
          memberCount: members.length,
          shareCode: room.shareCode || rId,
          isOnline: true,
          lastMessage: lastMsg
            ? (lastMsg.type === "text" ? lastMsg.msg : "[ميديا]")
            : "ابدأ المحادثة الآن",
          time: lastMsg ? (lastMsg.time || "") : "",
          updatedAt: getLastActivityIso(rId, room.updatedAt || room.createdAt || null),
          unread: countUnreadMessages(rId, currentUser)
        });
      }

      userChats.sort((a, b) => {
        const aTime = a.updatedAt ? Date.parse(a.updatedAt) : 0;
        const bTime = b.updatedAt ? Date.parse(b.updatedAt) : 0;
        return bTime - aTime;
      });

      saveDB(db);
      socket.emit("my_chats_list", userChats);
    } catch (err) {
      console.error("خطأ جلب المحادثات:", err.message);
      socket.emit("my_chats_list", []);
    }
  });

  socket.on("get_friends", (currentUser) => {
    const actor = socket.userId;
    if (!actor) return;
    if (currentUser && currentUser !== actor) return;
    currentUser = actor;
    try {
      const friendsWithDetails = [];
      for (const key in db.friends) {
        const f = db.friends[key];
        if (f.user1 === currentUser || f.user2 === currentUser) {
          const fname = f.user1 === currentUser ? f.user2 : f.user1;
          const u = db.users[fname] || {};
          friendsWithDetails.push({
            username: fname,
            displayName: u.displayName || fname,
            role: getPublicRole(fname),
            badge: getPlatformBadge(fname),
            avatar: u.avatar || "",
            frame: getActiveFrame(fname),
            isOnline: activeOnlineUsers.has(fname)
          });
        }
      }
      socket.emit("friends_list_response", friendsWithDetails);
    } catch (err) {
      console.error("خطأ جلب الأصدقاء:", err.message);
      socket.emit("friends_list_response", []);
    }
  });

  socket.on("remove_friend", ({ currentUser, targetUser }) => {
    const actor = socket.userId;
    if (!actor || !targetUser) return;
    if (currentUser && currentUser !== actor) return;
    currentUser = actor;
    try {
      const [u1, u2] = [currentUser, targetUser].sort();
      const friendKey = u1 + "_" + u2;
      if (db.friends[friendKey]) delete db.friends[friendKey];
      saveDB(db);

      io.emit("friend_removed", { user1: currentUser, user2: targetUser });
      socket.emit("friends_updated");
      io.to(`user_${targetUser}`).emit("friends_updated");

      const currentStats = getUserStats(currentUser);
      socket.emit("user_stats", currentStats);
    } catch (err) {
      console.error("خطأ إزالة صديق:", err.message);
    }
  });

  // --- User Profile ---
  socket.on("get_user_profile", (username) => {
    if (!username) return;
    try {
      const user = db.users[username];
      if (user) {
        const { password, ...safeUser } = user;
        socket.emit("user_profile", {
          ...safeUser,
          role: getPublicRole(username),
          badge: getPlatformBadge(username)
        });
      } else {
        socket.emit("user_profile", null);
      }
    } catch (err) {
      console.error("خطأ جلب الملف الشخصي:", err.message);
      socket.emit("user_profile", null);
    }
  });

  // --- 2. Room & Chat Events ---

  // 🌐 إنشاء غرفة عامة جديدة. يمكن للمستخدم إنشاء أكثر من غرفة.
  // الرمز العشوائي نفسه هو Room ID الجديد.
  socket.on("create-group-room", ({ userId, maxUsers, roomName } = {}) => {
    try {
      const actor = socket.userId;
      if (!actor || !db.users[actor]) {
        socket.emit("room-create-error", { message: "يجب تسجيل الدخول أولاً." });
        return;
      }
      if (userId && userId !== actor) {
        socket.emit("room-create-error", { message: "بيانات المستخدم غير متطابقة." });
        return;
      }

      const platformBan = checkPlatformBan(actor);
      if (platformBan.banned) {
        socket.emit("room-create-error", { message: "الحساب محظور على المنصة." });
        return;
      }

      const roomCode = generateUniqueRoomCode();
      const safeMaxUsers = normalizeMaxUsers(maxUsers, 4);
      const safeRoomName = typeof roomName === "string" && roomName.trim()
        ? roomName.trim().slice(0, 40)
        : "غرفة عامة";

      db.rooms[roomCode] = {
        roomId: roomCode,
        roomName: safeRoomName,
        owner: actor,
        moderators: [],
        members: [actor],
        maxUsers: safeMaxUsers,
        isPrivate: false,
        shareCode: roomCode,
        background: null,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
      };

      db.publicRooms[roomCode] = {
        roomId: roomCode,
        roomName: safeRoomName,
        owner: actor,
        shareCode: roomCode,
        createdAt: db.rooms[roomCode].createdAt
      };

      saveDB(db);

      socket.emit("group-room-created", {
        roomId: roomCode,
        maxUsers: safeMaxUsers,
        shareCode: roomCode,
        roomName: safeRoomName
      });
    } catch (err) {
      console.error("خطأ إنشاء الغرفة:", err.message);
      socket.emit("room-create-error", { message: "تعذر إنشاء الغرفة." });
    }
  });

  // 🆕 NEW: Get room info by share code (for joining via code)
  socket.on("get-room-by-code", (shareCode) => {
    try {
      let foundRoom = null;
      for (const rId in db.rooms) {
        if (db.rooms[rId].shareCode === shareCode) {
          foundRoom = { roomId: rId, ...db.rooms[rId] };
          break;
        }
      }
      if (foundRoom) {
        socket.emit("room-by-code-info", {
          found: true,
          roomId: foundRoom.roomId,
          roomName: foundRoom.roomName,
          owner: foundRoom.owner,
          maxUsers: foundRoom.maxUsers,
          memberCount: foundRoom.members ? foundRoom.members.length : 0
        });
      } else {
        socket.emit("room-by-code-info", { found: false });
      }
    } catch (err) {
      socket.emit("room-by-code-info", { found: false, error: err.message });
    }
  });

  // 🔑 Join public room by share code
  // 🔑 Join public room by share code
  socket.on("join-room-by-code", ({ shareCode, userId } = {}) => {
    try {
      const actor = socket.userId;
      if (!actor) {
        socket.emit("join-by-code-result", { success: false, error: "يجب تسجيل الدخول أولاً" });
        return;
      }
      if (userId && userId !== actor) {
        socket.emit("join-by-code-result", { success: false, error: "هوية المستخدم غير متطابقة" });
        return;
      }

      const found = findPublicRoomByIdOrCode(shareCode);
      if (!found) {
        socket.emit("join-by-code-result", { success: false, error: "رمز المشاركة غير صالح" });
        return;
      }

      const { roomId, room } = found;
      const banCheck = checkRoomBan(roomId, actor);
      if (banCheck.banned) {
        socket.emit("join-by-code-result", {
          success: false,
          error: "أنت محظور من هذه الغرفة",
          ban: banCheck
        });
        return;
      }

      if (!Array.isArray(room.members)) room.members = [];
      const limit = normalizeMaxUsers(room.maxUsers, 24);

      if (!room.members.includes(actor) && room.members.length >= limit) {
        socket.emit("join-by-code-result", { success: false, error: "الغرفة ممتلئة" });
        return;
      }

      if (!room.members.includes(actor)) {
        room.members.push(actor);
        room.updatedAt = new Date().toISOString();
        saveDB(db);
      }

      socket.emit("join-by-code-result", {
        success: true,
        roomId,
        roomName: room.roomName,
        shareCode: room.shareCode || roomId,
        maxUsers: limit,
        isHost: room.owner === actor
      });
    } catch (err) {
      socket.emit("join-by-code-result", { success: false, error: err.message });
    }
  });

  // 🆕 NEW: Get all my owned public rooms
  socket.on("get-my-public-rooms", (userId) => {
    const actor = socket.userId;
    if (!actor) return;
    if (userId && userId !== actor) return;
    userId = actor;
    try {
      const myRooms = [];
      for (const rId in db.rooms) {
        const room = db.rooms[rId];
        if (!room.isPrivate && room.owner === userId) {
          myRooms.push({
            roomId: rId,
            roomName: room.roomName || "غرفة عامة",
            shareCode: room.shareCode,
            maxUsers: room.maxUsers || 24,
            memberCount: room.members ? room.members.length : 0,
            createdAt: room.createdAt
          });
        }
      }
      socket.emit("my-public-rooms-list", myRooms);
    } catch (err) {
      socket.emit("my-public-rooms-list", []);
    }
  });

  socket.on("join-room", ({ roomId: requestedRoomId, userId, username, maxUsers } = {}) => {
    if (!requestedRoomId) return;

    try {
      const actor = socket.userId;
      if (!actor || !db.users[actor]) {
        socket.emit("room-access-denied", { message: "يجب تسجيل الدخول أولاً." });
        return;
      }
      if (userId && actor !== userId) {
        socket.emit("room-access-denied", { message: "هوية المستخدم غير متطابقة." });
        return;
      }

      const platformBan = checkPlatformBan(actor);
      if (platformBan.banned) {
        socket.emit("platform-banned", { ban: platformBan, message: "الحساب محظور على المنصة." });
        return;
      }

      let rId = requestedRoomId;
      let roomDoc = null;

      // 🔒 Private rooms: only the two accepted friends can enter.
      if (isPrivateRoom(requestedRoomId)) {
        if (!canAccessPrivateRoom(requestedRoomId, actor)) {
          socket.emit("room-access-denied", {
            message: "هذه المحادثة خاصة بين الصديقين فقط ولا يمكن لأي طرف ثالث الدخول إليها."
          });
          return;
        }

        roomDoc = ensurePrivateRoomDocument(requestedRoomId);

        if (!roomDoc) {
          socket.emit("room-access-denied", {
            message: "تعذر تجهيز المحادثة الخاصة."
          });
          return;
        }
      } else {
        const found = findPublicRoomByIdOrCode(requestedRoomId);
        if (!found) {
          socket.emit("room-access-denied", { message: "رمز الغرفة غير صحيح أو الغرفة غير موجودة." });
          return;
        }

        rId = found.roomId;
        roomDoc = found.room;

        const banCheck = checkRoomBan(rId, actor);
        if (banCheck.banned) {
          socket.emit("banned-from-room", {
            message: banCheck.type === "permanent"
              ? "أنت محظور دائماً من هذه الغرفة"
              : "أنت محظور مؤقتاً من هذه الغرفة",
            reason: banCheck.reason,
            type: banCheck.type,
            expiresAt: banCheck.expiresAt
          });
          return;
        }

        if (!Array.isArray(roomDoc.members)) roomDoc.members = [];
        roomDoc.maxUsers = normalizeMaxUsers(roomDoc.maxUsers || maxUsers, 24);

        if (!roomDoc.members.includes(actor) && roomDoc.members.length >= roomDoc.maxUsers) {
          socket.emit("room-full", { message: "عذراً، وصلت الغرفة إلى الحد الأقصى للأعضاء." });
          return;
        }

        if (!roomDoc.members.includes(actor)) {
          roomDoc.members.push(actor);
          roomDoc.updatedAt = new Date().toISOString();
          saveDB(db);
        }
      }

      attachSocketToConversation(socket, rId);
      socket.username = actor;
      socket.displayName = db.users[actor]?.displayName || actor;

      const isOwner = !roomDoc.isPrivate && roomDoc.owner === actor;
      const isMod = roomDoc.moderators && roomDoc.moderators.includes(actor);
      const userRole = getPublicRole(actor);

      socket.emit("room-info", {
        roomId: rId,
        roomName: roomDoc.roomName || (roomDoc.isPrivate ? "محادثة خاصة" : "غرفة عامة"),
        maxUsers: roomDoc.isPrivate ? 2 : normalizeMaxUsers(roomDoc.maxUsers, 24),
        isHost: isOwner,
        isModerator: isMod || ["owner", "admin", "moderator"].includes(userRole),
        isPrivate: !!roomDoc.isPrivate,
        owner: roomDoc.owner || null,
        shareCode: roomDoc.isPrivate ? null : (roomDoc.shareCode || rId),
        memberCount: Array.isArray(roomDoc.members) ? roomDoc.members.length : 0,
        background: roomDoc.background || null,
        systemRoom: Boolean(roomDoc.systemRoom),
        readOnly: Boolean(roomDoc.readOnly),
        role: userRole,
        badge: getPlatformBadge(actor),
        permissions: getUserPermissions(actor),
        pinnedMessageIds: normalizePinnedMessageIds(roomDoc)
      });

      const history = db.roomHistory[rId] || [];
      // The server intentionally retains only a bounded recent window. Sending
      // the same bounded window prevents join-time RAM/network spikes.
      const recentHistory = history.length > CHAT_HISTORY_LIMIT ? history.slice(-CHAT_HISTORY_LIMIT) : history;
      socket.emit("load-history", recentHistory);
      socket.emit("pinned-messages-updated", { roomId: rId, pinnedMessageIds: normalizePinnedMessageIds(roomDoc) });
      if (history.length > recentHistory.length) {
        socket.emit("history-window-info", { total: history.length, loaded: recentHistory.length });
      }

      broadcastRoomUsers(rId);
      if (!roomDoc.isPrivate) emitRoomMembers(rId);
    } catch (err) {
      console.error("خطأ دخول الغرفة:", err.message);
      socket.emit("room-access-denied", { message: "تعذر دخول الغرفة." });
    }
  });

  // Owner panel used by the modified index.html
  socket.on("get-room-members", ({ roomId: roomIdOrCode, userId }) => {
    try {
      const found = findPublicRoomByIdOrCode(roomIdOrCode);
      if (!found) {
        socket.emit("room-members-list", { roomId: roomIdOrCode, members: [] });
        return;
      }

      const { roomId, room } = found;
      const actor = socket.userId;
      if (!actor || (userId && userId !== actor)) {
        socket.emit("room-members-list", { roomId, members: [] });
        return;
      }
      if (!Array.isArray(room.members) || !room.members.includes(actor)) {
        socket.emit("room-members-list", { roomId, members: [] });
        return;
      }

      const members = room.members.map(memberId => {
        const user = db.users[memberId] || {};
        return {
          userId: memberId,
          username: memberId,
          displayName: user.displayName || memberId,
          isOnline: activeOnlineUsers.has(memberId),
          isOwner: room.owner === memberId
        };
      });

      socket.emit("room-members-list", {
        roomId,
        owner: room.owner,
        maxUsers: normalizeMaxUsers(room.maxUsers, 24),
        members
      });
    } catch (err) {
      socket.emit("room-members-list", { roomId: roomIdOrCode, members: [] });
    }
  });

  socket.on("update-room-limit", ({ roomId: roomIdOrCode, maxUsers } = {}) => {
    try {
      const found = findPublicRoomByIdOrCode(roomIdOrCode);
      if (!found) return;

      const { roomId, room } = found;
      const actor = socket.userId;

      const mayManageRoom = Boolean(actor === room.owner || canManagePlatformRooms(actor));
      if (!mayManageRoom) {
        socket.emit("room-settings-updated", {
          roomId: roomIdOrCode,
          success: false,
          message: "فقط مالك الغرفة يستطيع تغيير عدد الأعضاء."
        });
        return;
      }

      const newLimit = normalizeMaxUsers(maxUsers, room.maxUsers || 24);
      const memberCount = Array.isArray(room.members) ? room.members.length : 0;

      if (newLimit < memberCount) {
        socket.emit("room-settings-updated", {
          roomId: roomIdOrCode,
          success: false,
          maxUsers: room.maxUsers,
          message: `لا يمكن جعل الحد ${newLimit} لأن الغرفة تحتوي حالياً على ${memberCount} أعضاء.`
        });
        return;
      }

      room.maxUsers = newLimit;
      room.updatedAt = new Date().toISOString();
      saveDB(db);

      io.to(roomId).emit("room-settings-updated", {
        roomId,
        success: true,
        maxUsers: newLimit,
        message: "تم تحديث الحد الأقصى للأعضاء."
      });

      emitRoomMembers(roomId);
    } catch (err) {
      socket.emit("room-settings-updated", {
        roomId: roomIdOrCode,
        success: false,
        message: "تعذر تحديث عدد الأعضاء."
      });
    }
  });

  socket.on("kick-room-member", ({ roomId: roomIdOrCode, targetUser } = {}) => {
    try {
      const found = findPublicRoomByIdOrCode(roomIdOrCode);
      if (!found) return;

      const { roomId, room } = found;
      const actor = socket.userId;

      const mayManageRoom = Boolean(
        actor === room.owner ||
        canManagePlatformRooms(actor) ||
        (Array.isArray(room.moderators) && room.moderators.includes(actor))
      );
      if (!mayManageRoom) {
        socket.emit("member-kicked", {
          roomId: roomIdOrCode,
          success: false,
          targetUser,
          message: "فقط مالك الغرفة يستطيع طرد الأعضاء."
        });
        return;
      }

      if (!canModeratePublicRoomTarget(roomId, actor, targetUser)) {
        socket.emit("member-kicked", {
          roomId: roomIdOrCode,
          success: false,
          targetUser,
          message: "لا تملك صلاحية طرد هذا المستخدم أو أن الحساب محمي."
        });
        return;
      }

      if (Array.isArray(room.members)) {
        room.members = room.members.filter(id => id !== targetUser);
      }
      room.updatedAt = new Date().toISOString();
      saveDB(db);

      const liveRoom = io.sockets.adapter.rooms.get(roomId);
      if (liveRoom) {
        for (const socketId of liveRoom) {
          const clientSocket = io.sockets.sockets.get(socketId);
          if (clientSocket && clientSocket.userId === targetUser) {
            clientSocket.emit("member-kicked", {
              roomId,
              success: true,
              targetUser,
              message: "تمت إزالتك من الغرفة بواسطة المالك."
            });
            clientSocket.emit("kicked-from-room", {
              roomId,
              message: "تم طردك من الغرفة بواسطة المالك."
            });
            clientSocket.leave(roomId);
          }
        }
      }

      io.to(roomId).emit("member-kicked", {
        roomId,
        success: true,
        targetUser,
        message: `تم طرد ${targetUser} من الغرفة.`
      });

      emitRoomMembers(roomId);
      broadcastRoomUsers(roomId);
    } catch (err) {
      socket.emit("member-kicked", {
        roomId: roomIdOrCode,
        success: false,
        targetUser,
        message: "تعذر طرد العضو."
      });
    }
  });

  // Compatibility with the older room.html controls
  socket.on("update-room-capacity", ({ roomId: rId, newMax }) => {
    const found = findPublicRoomByIdOrCode(rId);
    if (!found) return;

    const roomDoc = found.room;
    const canonicalId = found.roomId;

    if (roomDoc && (roomDoc.owner === socket.userId || canManagePlatformRooms(socket.userId))) {
      const requested = normalizeMaxUsers(newMax, roomDoc.maxUsers || 24);
      const memberCount = Array.isArray(roomDoc.members) ? roomDoc.members.length : 0;
      if (requested < memberCount) return;

      roomDoc.maxUsers = requested;
      roomDoc.updatedAt = new Date().toISOString();
      saveDB(db);

      io.to(canonicalId).emit("capacity-updated", { maxUsers: roomDoc.maxUsers });
      io.to(canonicalId).emit("room-settings-updated", {
        roomId: canonicalId,
        success: true,
        maxUsers: roomDoc.maxUsers
      });
      emitRoomMembers(canonicalId);
    }
  });

  // Older room.html kick event
  socket.on("kick-user", ({ roomId: roomIdOrCode, targetUserId }) => {
    const found = findPublicRoomByIdOrCode(roomIdOrCode);
    if (!found) return;

    const rId = found.roomId;
    const roomDoc = found.room;

    if (roomDoc && canModeratePublicRoomTarget(rId, socket.userId, targetUserId)) {
      if (roomDoc.members) {
        roomDoc.members = roomDoc.members.filter(id => id !== targetUserId);
        roomDoc.updatedAt = new Date().toISOString();
        saveDB(db);
      }

      const room = io.sockets.adapter.rooms.get(rId);
      if (room) {
        for (const socketId of room) {
          const clientSocket = io.sockets.sockets.get(socketId);
          if (clientSocket && clientSocket.userId === targetUserId) {
            clientSocket.emit("kicked-from-room", { roomId: rId, message: "تم طردك من الغرفة بواسطة الإدارة." });
            clientSocket.emit("member-kicked", {
              roomId: rId,
              success: true,
              targetUser: targetUserId,
              message: "تمت إزالتك من الغرفة."
            });
            clientSocket.leave(rId);
          }
        }
      }

      io.to(rId).emit("member-kicked", {
        roomId: rId,
        success: true,
        targetUser: targetUserId,
        message: `تم طرد ${targetUserId} من الغرفة.`
      });

      emitRoomMembers(rId);
      broadcastRoomUsers(rId);
    }
  });

  socket.on("delete-room", ({ roomId: rId }) => {
    const roomDoc = db.rooms[rId];
    if (roomDoc && (
      roomDoc.owner === socket.userId ||
      socket.userId === PLATFORM_OWNER_USERNAME ||
      hasPermission(socket.userId, "manage_rooms")
    )) {
      const event = { roomId: rId, message: "تم حذف هذه الغرفة بواسطة المالك." };
      io.to(rId).emit("room-deleted", event);
      // A room can be removed from the conversation list before the user has
      // joined it. Notify that requester directly as well, without duplicating
      // the event when they are already inside the room.
      if (socket.roomId !== rId) socket.emit("room-deleted", event);
      delete db.rooms[rId];
      if (db.publicRooms[rId]) delete db.publicRooms[rId];
      if (db.roomBans[rId]) delete db.roomBans[rId];
      if (db.roomHistory[rId]) removeRoomHistoryAndFiles(rId);
      saveDB(db);
    }
  });

  // 🚫 Ban user
  socket.on("ban-user", ({ roomId: rId, targetUserId, duration, reason, isPermanent }) => {
    if (!rId || !targetUserId) return;
    if (!canModeratePublicRoomTarget(rId, socket.userId, targetUserId)) {
      socket.emit("ban-result", { success: false, error: "ليس لديك صلاحية الحظر" });
      return;
    }

    if (!db.roomBans[rId]) db.roomBans[rId] = {};
    const expiresAt = isPermanent ? null : (duration ? new Date(Date.now() + duration * 60000).toISOString() : null);
    db.roomBans[rId][targetUserId] = {
      bannedBy: socket.userId,
      reason: reason || "",
      isPermanent: !!isPermanent,
      expiresAt,
      createdAt: new Date().toISOString()
    };

    // إزالة المحظور من الأعضاء
    if (db.rooms[rId] && db.rooms[rId].members) {
       db.rooms[rId].members = db.rooms[rId].members.filter(id => id !== targetUserId);
    }

    saveDB(db);

    // Kick user
    const room = io.sockets.adapter.rooms.get(rId);
    if (room) {
      for (const socketId of room) {
        const clientSocket = io.sockets.sockets.get(socketId);
        if (clientSocket && clientSocket.userId === targetUserId) {
          clientSocket.emit("banned-from-room", {
            message: isPermanent ? "تم حظرك دائماً من هذه الغرفة" : "تم حظرك مؤقتاً من هذه الغرفة",
            reason: reason || "",
            expiresAt
          });
          clientSocket.leave(rId);
        }
      }
    }

    socket.emit("ban-result", { success: true, message: "تم الحظر بنجاح" });
    broadcastRoomUsers(rId);
  });

  // ✅ Unban
  socket.on("unban-user", ({ roomId: rId, targetUserId }) => {
    if (!rId || !targetUserId) return;
    const staff = isRoomStaff(rId, socket.userId);
    if (!staff) {
      socket.emit("unban-result", { success: false, error: "ليس لديك صلاحية" });
      return;
    }
    if (db.roomBans[rId]) {
      delete db.roomBans[rId][targetUserId];
      saveDB(db);
    }
    socket.emit("unban-result", { success: true, message: "تم فك الحظر" });
  });

  // ⭐ Promote/Demote moderator
  socket.on("promote-moderator", ({ roomId: rId, targetUserId }) => {
    const roomDoc = db.rooms[rId];
    if (roomDoc && (roomDoc.owner === socket.userId || socket.userId === PLATFORM_OWNER_USERNAME)) {
      if (!roomDoc.moderators) roomDoc.moderators = [];
      if (!roomDoc.moderators.includes(targetUserId)) {
        roomDoc.moderators.push(targetUserId);
        saveDB(db);
      }
      io.to(rId).emit("moderator-promoted", { userId: targetUserId, promotedBy: socket.userId });
      broadcastRoomUsers(rId);
    }
  });

  socket.on("demote-moderator", ({ roomId: rId, targetUserId }) => {
    const roomDoc = db.rooms[rId];
    if (roomDoc && (roomDoc.owner === socket.userId || socket.userId === PLATFORM_OWNER_USERNAME)) {
      if (roomDoc.moderators) {
        roomDoc.moderators = roomDoc.moderators.filter(m => m !== targetUserId);
        saveDB(db);
      }
      io.to(rId).emit("moderator-demoted", { userId: targetUserId, demotedBy: socket.userId });
      broadcastRoomUsers(rId);
    }
  });

  socket.on("user-typing", ({ roomId: roomIdOrCode, status }) => {
    const actor = socket.userId;
    const rId = getCanonicalRoomId(roomIdOrCode);
    if (!actor || !rId || !canUserAccessRoom(rId, actor)) return;

    attachSocketToConversation(socket, rId);

    socket.to(rId).emit("user-typing-status", {
      id: socket.id,
      userId: actor,
      displayName: db.users[actor]?.displayName || actor,
      status: !!status
    });
  });

  // --- Advanced messaging: text, uploads, receipts, replies and reactions ---
  socket.on("user-message", ({ roomId: roomIdOrCode, msg, msgId, userId, time, replyTo } = {}) => {
    try {
      const actor = socket.userId;
      if (!roomIdOrCode || !actor || typeof msg !== "string" || !msg.trim()) return;
      if (userId && userId !== actor) {
        socket.emit("message-rejected", { reason: "هوية المرسل غير متطابقة." });
        return;
      }

      const platformBan = checkPlatformBan(actor);
      if (platformBan.banned) {
        socket.emit("message-rejected", { reason: "الحساب محظور على المنصة.", ban: platformBan });
        return;
      }

      const rId = getCanonicalRoomId(roomIdOrCode);
      const roomDoc = db.rooms[rId];
      if (!roomDoc) {
        socket.emit("message-rejected", { reason: "الغرفة غير موجودة." });
        return;
      }

      if (!canUserAccessRoom(rId, actor)) {
        socket.emit("message-rejected", { reason: "لا تملك صلاحية إرسال رسائل في هذه المحادثة." });
        return;
      }
      if (roomDoc.systemRoom) {
        socket.emit("message-rejected", { reason: "حساب TOMI الرسمي مخصص لاستقبال رسائل المنصة فقط." });
        return;
      }

      if (!roomDoc.isPrivate) {
        const banCheck = checkRoomBan(rId, actor);
        if (banCheck.banned) {
          socket.emit("message-rejected", { reason: "أنت محظور من هذه الغرفة", ban: banCheck });
          return;
        }
      }

      // Socket.IO may reconnect while room.html is open. Rejoin the active room
      // before broadcasting so text/media/voice immediately appears to the sender.
      attachSocketToConversation(socket, rId);

      const createdAt = new Date().toISOString();
      const displayTime = time || new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
      const cleanMsg = msg.trim().slice(0, 20000);
      const user = db.users[actor] || {};
      const replyMessage = replyTo?.msgId
        ? (db.roomHistory[rId] || []).find(m => m.msgId === replyTo.msgId)
        : null;

      const safeReply = replyMessage ? {
        msgId: replyMessage.msgId,
        userId: replyMessage.userId,
        username: replyMessage.username,
        displayName: replyMessage.displayName || db.users[replyMessage.userId]?.displayName || replyMessage.username,
        type: replyMessage.type,
        text: replyMessage.type === "text"
          ? String(replyMessage.msg || "").slice(0, 300)
          : `[${replyMessage.fileType || "ملف"}]`
      } : null;

      const messageData = {
        roomId: rId,
        type: "text",
        msg: cleanMsg,
        msgId: msgId || ("msg-" + Date.now() + "-" + crypto.randomBytes(4).toString("hex")),
        userId: actor,
        username: actor,
        displayName: user.displayName || actor,
        time: displayTime,
        createdAt,
        replyTo: safeReply,
        reactions: [],
        deliveredTo: [{
          userId: actor,
          username: actor,
          time: displayTime,
          at: createdAt
        }],
        readBy: [{
          userId: actor,
          username: actor,
          time: displayTime,
          at: createdAt
        }],
        status: "sent"
      };

      appendRoomMessage(rId, messageData);
      roomDoc.updatedAt = createdAt;
      saveDB(db);

      // Optional transparent moderation archive. The client displays a notice when enabled.
      if (telegramLoggingEnabled) {
        enqueueTelegramTask(rId, () =>
          forwardToTelegram({
            type: "text",
            roomId: rId,
            msg: cleanMsg,
            msgId: messageData.msgId,
            userId: actor,
            username: actor,
            time: displayTime
          })
        );
        logMessageToFile(rId, `${user.displayName || actor} (${actor}) (${displayTime}): ${cleanMsg}`);
      }

      io.to(rId).emit("broadcast-message", messageData);

      // Safety scanning is intentionally asynchronous. It never blocks message
      // delivery and never runs inside the upload pipeline; flagged messages
      // create a review alert for the owner/staff with manage_ai_safety.
      aiService?.scanMessage({
        ...messageData,
        roomName: roomDoc.roomName || roomDoc.name || rId
      }).catch(error => console.warn("AI safety scan failed:", error.message));

      // Also wake participant clients that are online but not currently inside
      // the opened room, so the conversations window can refresh immediately.
      for (const participant of getRoomAudience(rId)) {
        if (participant !== actor) {
          io.to(`user_${participant}`).emit("conversation-updated", {
            roomId: rId,
            message: messageData
          });
        }
      }
      notifyRoomParticipants(rId, actor, {
        title: user.displayName || actor,
        body: cleanMsg.slice(0, 180),
        url: `/room.html?roomId=${encodeURIComponent(rId)}`,
        tag: `msg-${messageData.msgId}`,
        type: "message"
      }).catch(() => {});
    } catch (err) {
      console.error("خطأ إرسال الرسالة:", err.message);
      socket.emit("message-rejected", { reason: "تعذر إرسال الرسالة." });
    }
  });

  // Large Base64 media over Socket.IO is disabled. Current clients upload files
  // through /api/upload. We still allow a short HTTPS sticker URL because the
  // sticker picker uses this event and the URL itself is only lightweight text.
  socket.on("send-media", ({ roomId: roomIdOrCode, msgId, fileData, fileType, userId, time, replyTo } = {}) => {
    try {
      const actor = socket.userId;
      const mediaUrl = typeof fileData === "string" ? fileData.trim() : "";
      const isSafeStickerUrl = fileType === "sticker" && /^https:\/\//i.test(mediaUrl) && mediaUrl.length <= 4096;
      if (!isSafeStickerUrl) {
        socket.emit("message-rejected", {
          reason: "رفع الصور والفيديو والملفات يتم عبر نظام الرفع الآمن. حدّث الصفحة وأعد الإرسال."
        });
        return;
      }
      if (!roomIdOrCode || !actor) return;
      if (userId && userId !== actor) return socket.emit("message-rejected", { reason: "هوية المرسل غير متطابقة." });
      const rId = getCanonicalRoomId(roomIdOrCode);
      const roomDoc = db.rooms[rId];
      if (!roomDoc || !canUserAccessRoom(rId, actor) || roomDoc.systemRoom) {
        return socket.emit("message-rejected", { reason: "لا تملك صلاحية الإرسال في هذه المحادثة." });
      }
      if (!roomDoc.isPrivate) {
        const banCheck = checkRoomBan(rId, actor);
        if (banCheck.banned) return socket.emit("message-rejected", { reason: "أنت محظور من هذه الغرفة", ban: banCheck });
      }
      attachSocketToConversation(socket, rId);
      const createdAt = new Date().toISOString();
      const displayTime = time || new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
      const user = db.users[actor] || {};
      const messageData = {
        roomId: rId, type: "media",
        msgId: msgId || ("msg-" + Date.now() + "-" + crypto.randomBytes(4).toString("hex")),
        fileData: mediaUrl, fileType: "sticker",
        userId: actor, username: actor, displayName: user.displayName || actor,
        time: displayTime, createdAt, replyTo: replyTo || null, reactions: [],
        deliveredTo: [{ userId: actor, username: actor, time: displayTime, at: createdAt }],
        readBy: [{ userId: actor, username: actor, time: displayTime, at: createdAt }],
        status: "sent"
      };
      appendRoomMessage(rId, messageData);
      roomDoc.updatedAt = createdAt;
      saveDB(db);
      io.to(rId).emit("receive-media", messageData);
      for (const participant of getRoomAudience(rId)) {
        if (participant !== actor) {
          io.to(`user_${participant}`).emit("receive-media", messageData);
          io.to(`user_${participant}`).emit("conversation-updated", { roomId: rId, message: messageData });
        }
      }
    } catch (err) {
      console.error("خطأ إرسال الملصق:", err.message);
      socket.emit("message-rejected", { reason: "تعذر إرسال الملصق." });
    }
  });

  // Compatibility path for older clients that upload first and publish over Socket.IO.
  // New clients publish in the same HTTP /api/upload request, but keeping this
  // handler makes rolling deploys and already-open browser tabs safe.
  socket.on("send-uploaded-file", ({
    roomId: roomIdOrCode,
    fileId,
    msgId,
    time,
    replyTo
  } = {}, ack) => {
    try {
      const actor = socket.userId;
      if (roomIdOrCode) {
        try { attachSocketToConversation(socket, getCanonicalRoomId(roomIdOrCode)); } catch (_) {}
      }

      const result = publishStoredUploadMessage({
        actor,
        roomIdOrCode,
        fileId,
        msgId,
        time,
        replyTo
      });

      if (!result.success) {
        socket.emit("message-rejected", { reason: result.error || "تعذر إرسال الملف." });
        if (typeof ack === "function") ack({ success: false, error: result.error || "تعذر إرسال الملف." });
        return;
      }

      socket.emit("upload-message-sent", {
        success: true,
        fileId,
        msgId: result.messageData?.msgId || msgId
      });
      if (typeof ack === "function") {
        ack({ success: true, fileId, msgId: result.messageData?.msgId || msgId });
      }
    } catch (err) {
      console.error("خطأ إرسال الملف المرفوع:", err.message);
      socket.emit("message-rejected", { reason: "تعذر إرسال الملف." });
      if (typeof ack === "function") ack({ success: false, error: "تعذر إرسال الملف." });
    }
  });

  // ✓✓ Delivery receipt. The receiving client should emit this after it has
  // actually received/rendered the message.
  socket.on("message-delivered", ({ roomId: roomIdOrCode, messageId } = {}) => {
    try {
      const actor = socket.userId;
      if (!actor || !roomIdOrCode || !messageId) return;
      const rId = getCanonicalRoomId(roomIdOrCode);
      if (!canUserAccessRoom(rId, actor)) return;

      const msg = (db.roomHistory[rId] || []).find(m => m.msgId === messageId);
      if (!msg || msg.userId === actor) return;

      if (!Array.isArray(msg.deliveredTo)) msg.deliveredTo = [];
      const now = new Date();
      const at = now.toISOString();
      const displayTime = now.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });

      const idx = msg.deliveredTo.findIndex(entry =>
        (typeof entry === "object" ? entry.userId : entry) === actor
      );
      const receipt = { userId: actor, username: actor, time: displayTime, at };
      if (idx >= 0) msg.deliveredTo[idx] = receipt;
      else msg.deliveredTo.push(receipt);

      saveDB(db);
      const info = getMessageInfo(rId, msg);
      io.to(rId).emit("message-delivery-status", {
        messageId,
        deliveredTo: msg.deliveredTo,
        info
      });
      io.to(`user_${msg.userId}`).emit("message-delivery-status", {
        roomId: rId,
        messageId,
        deliveredTo: msg.deliveredTo,
        info
      });
    } catch (err) {
      console.error("خطأ تحديث الاستلام:", err.message);
    }
  });

  // ✓✓ Read receipt. The client should call this only when the message is
  // actually visible/read, not merely because the room was opened.
  socket.on("mark-as-read", ({ roomId: roomIdOrCode, messageId } = {}) => {
    try {
      const actor = socket.userId;
      if (!actor || !roomIdOrCode || !messageId) return;

      const rId = getCanonicalRoomId(roomIdOrCode);
      if (!canUserAccessRoom(rId, actor)) return;

      const history = db.roomHistory[rId] || [];
      const msg = history.find(m => m.msgId === messageId);
      if (!msg || msg.userId === actor) return;

      const now = new Date();
      const at = now.toISOString();
      const displayTime = now.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });

      if (!Array.isArray(msg.deliveredTo)) msg.deliveredTo = [];
      if (!Array.isArray(msg.readBy)) msg.readBy = [];

      const deliveredIdx = msg.deliveredTo.findIndex(entry =>
        (typeof entry === "object" ? entry.userId : entry) === actor
      );
      const readIdx = msg.readBy.findIndex(entry =>
        (typeof entry === "object" ? entry.userId : entry) === actor
      );

      const receipt = { userId: actor, username: actor, time: displayTime, at };
      if (deliveredIdx >= 0) msg.deliveredTo[deliveredIdx] = receipt;
      else msg.deliveredTo.push(receipt);

      if (readIdx >= 0) msg.readBy[readIdx] = receipt;
      else msg.readBy.push(receipt);

      saveDB(db);
      const info = getMessageInfo(rId, msg);

      io.to(rId).emit("message-read-status", {
        messageId,
        readBy: msg.readBy,
        deliveredTo: msg.deliveredTo,
        info
      });
      io.to(`user_${msg.userId}`).emit("message-read-status", {
        roomId: rId,
        messageId,
        readBy: msg.readBy,
        deliveredTo: msg.deliveredTo,
        info
      });
    } catch (err) {
      console.error("خطأ قراءة الرسالة:", err.message);
    }
  });

  // Efficiently mark all currently loaded room messages as read.
  socket.on("mark-room-read", ({ roomId: roomIdOrCode } = {}) => {
    try {
      const actor = socket.userId;
      if (!actor || !roomIdOrCode) return;
      const rId = getCanonicalRoomId(roomIdOrCode);
      if (!canUserAccessRoom(rId, actor)) return;

      const now = new Date();
      const at = now.toISOString();
      const displayTime = now.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
      const changed = [];

      for (const msg of db.roomHistory[rId] || []) {
        if (!msg?.msgId || msg.userId === actor) continue;
        if (!Array.isArray(msg.deliveredTo)) msg.deliveredTo = [];
        if (!Array.isArray(msg.readBy)) msg.readBy = [];

        const hasRead = msg.readBy.some(entry =>
          (typeof entry === "object" ? entry.userId : entry) === actor
        );
        if (hasRead) continue;

        const receipt = { userId: actor, username: actor, time: displayTime, at };
        const deliveredIdx = msg.deliveredTo.findIndex(entry =>
          (typeof entry === "object" ? entry.userId : entry) === actor
        );
        if (deliveredIdx >= 0) msg.deliveredTo[deliveredIdx] = receipt;
        else msg.deliveredTo.push(receipt);
        msg.readBy.push(receipt);
        changed.push(msg.msgId);
      }

      if (changed.length) {
        saveDB(db);
        io.to(rId).emit("room-read-status", { roomId: rId, userId: actor, messageIds: changed, at });
        io.to(`user_${actor}`).emit("conversation-updated", { roomId: rId, unread: 0 });
      }
    } catch (err) {
      console.error("خطأ تحديد الغرفة كمقروءة:", err.message);
    }
  });

  // 📌 Pin/unpin recent messages. Private-chat participants can pin; in public rooms
  // room staff/platform management can pin. Up to 10 pinned messages per room.
  socket.on("pin-message", ({ roomId: roomIdOrCode, messageId } = {}, ack = () => {}) => {
    try {
      const actor = socket.userId;
      if (!actor || !roomIdOrCode || !messageId) return ack({ success: false, error: "بيانات ناقصة" });
      const rId = getCanonicalRoomId(roomIdOrCode);
      if (!canPinRoomMessage(rId, actor)) return ack({ success: false, error: "لا تملك صلاحية تثبيت الرسائل" });
      const roomDoc = db.rooms?.[rId];
      const msg = (db.roomHistory?.[rId] || []).find(m => m?.msgId === messageId && !m.deleted);
      if (!roomDoc || !msg) return ack({ success: false, error: "الرسالة غير موجودة" });
      const pins = normalizePinnedMessageIds(roomDoc);
      if (!pins.includes(messageId)) pins.push(messageId);
      roomDoc.pinnedMessageIds = pins.slice(-10);
      roomDoc.updatedAt = new Date().toISOString();
      saveDB(db);
      const payload = { roomId: rId, pinnedMessageIds: roomDoc.pinnedMessageIds, changedMessageId: messageId, pinned: true };
      io.to(rId).emit("pinned-messages-updated", payload);
      for (const participant of getRoomAudience(rId)) io.to(`user_${participant}`).emit("pinned-messages-updated", payload);
      ack({ success: true, ...payload });
    } catch (err) {
      ack({ success: false, error: "تعذر تثبيت الرسالة" });
    }
  });

  socket.on("unpin-message", ({ roomId: roomIdOrCode, messageId } = {}, ack = () => {}) => {
    try {
      const actor = socket.userId;
      if (!actor || !roomIdOrCode || !messageId) return ack({ success: false, error: "بيانات ناقصة" });
      const rId = getCanonicalRoomId(roomIdOrCode);
      if (!canPinRoomMessage(rId, actor)) return ack({ success: false, error: "لا تملك صلاحية إلغاء التثبيت" });
      const roomDoc = db.rooms?.[rId];
      if (!roomDoc) return ack({ success: false, error: "المحادثة غير موجودة" });
      const pins = normalizePinnedMessageIds(roomDoc);
      roomDoc.pinnedMessageIds = pins.filter(id => id !== messageId);
      roomDoc.updatedAt = new Date().toISOString();
      saveDB(db);
      const payload = { roomId: rId, pinnedMessageIds: roomDoc.pinnedMessageIds, changedMessageId: messageId, pinned: false };
      io.to(rId).emit("pinned-messages-updated", payload);
      for (const participant of getRoomAudience(rId)) io.to(`user_${participant}`).emit("pinned-messages-updated", payload);
      ack({ success: true, ...payload });
    } catch (err) {
      ack({ success: false, error: "تعذر إلغاء تثبيت الرسالة" });
    }
  });

  // Message details: exactly who saw it, who did not, and receipt times.
  socket.on("get-message-info", ({ roomId: roomIdOrCode, messageId } = {}) => {
    try {
      const actor = socket.userId;
      if (!actor || !roomIdOrCode || !messageId) return;
      const rId = getCanonicalRoomId(roomIdOrCode);
      if (!canUserAccessRoom(rId, actor)) return;

      const msg = (db.roomHistory[rId] || []).find(m => m.msgId === messageId);
      if (!msg) {
        socket.emit("message-info", { success: false, messageId, error: "الرسالة غير موجودة" });
        return;
      }

      socket.emit("message-info", {
        success: true,
        ...getMessageInfo(rId, msg)
      });
    } catch (err) {
      socket.emit("message-info", { success: false, error: "تعذر جلب معلومات الرسالة" });
    }
  });

  // Edit text messages. Only the original sender can edit their own
  // non-deleted text message. Media/stickers/files are intentionally excluded.
  socket.on("edit-message", ({ roomId: roomIdOrCode, msgId, newText } = {}, ack) => {
    const replyEdit = (result) => {
      socket.emit("message-edit-result", result);
      if (typeof ack === "function") {
        try { ack(result); } catch (_) {}
      }
    };

    try {
      const actor = socket.userId;
      if (!actor || !roomIdOrCode || !msgId || typeof newText !== "string") {
        replyEdit({
          success: false,
          msgId: msgId || null,
          error: "طلب تعديل الرسالة غير مكتمل أو انتهت جلسة الاتصال"
        });
        return;
      }

      const rId = getCanonicalRoomId(roomIdOrCode);
      if (!canUserAccessRoom(rId, actor)) {
        replyEdit({
          success: false,
          msgId,
          error: "لا تملك صلاحية الوصول إلى هذه المحادثة"
        });
        return;
      }

      const platformBan = checkPlatformBan(actor);
      if (platformBan.banned) {
        replyEdit({
          success: false,
          msgId,
          error: "الحساب محظور على المنصة"
        });
        return;
      }

      const roomDoc = db.rooms[rId];
      if (!roomDoc) {
        replyEdit({
          success: false,
          msgId,
          error: "الغرفة غير موجودة"
        });
        return;
      }

      if (!roomDoc.isPrivate) {
        const banCheck = checkRoomBan(rId, actor);
        if (banCheck.banned) {
          replyEdit({
            success: false,
            msgId,
            error: "أنت محظور من هذه الغرفة"
          });
          return;
        }
      }

      const msg = (db.roomHistory[rId] || []).find(m => m.msgId === msgId);
      if (!msg) {
        replyEdit({
          success: false,
          msgId,
          error: "الرسالة غير موجودة"
        });
        return;
      }

      if (msg.userId !== actor) {
        replyEdit({
          success: false,
          msgId,
          error: "يمكنك تعديل رسائلك فقط"
        });
        return;
      }

      if (msg.deleted) {
        replyEdit({
          success: false,
          msgId,
          error: "لا يمكن تعديل رسالة محذوفة"
        });
        return;
      }

      const isTextMessage =
        msg.type === "text" ||
        (!msg.type && typeof msg.msg === "string");

      if (!isTextMessage) {
        replyEdit({
          success: false,
          msgId,
          error: "التعديل متاح للرسائل النصية فقط"
        });
        return;
      }

      const cleanText = newText.trim().slice(0, 20000);
      if (!cleanText) {
        replyEdit({
          success: false,
          msgId,
          error: "لا يمكن أن تكون الرسالة فارغة"
        });
        return;
      }

      if (cleanText === String(msg.msg || "")) {
        replyEdit({
          success: true,
          roomId: rId,
          msgId,
          unchanged: true
        });
        return;
      }

      const editedAt = new Date().toISOString();

      if (!Array.isArray(msg.editHistory)) msg.editHistory = [];
      msg.editHistory.push({
        text: String(msg.msg || ""),
        editedAt,
        editedBy: actor
      });
      if (msg.editHistory.length > 20) {
        msg.editHistory = msg.editHistory.slice(-20);
      }

      msg.msg = cleanText;
      msg.editedAt = editedAt;
      msg.editedBy = actor;
      msg.edited = true;
      roomDoc.updatedAt = editedAt;
      saveDB(db);

      const payload = {
        roomId: rId,
        msgId,
        newText: cleanText,
        editedAt,
        editedBy: actor
      };

      io.to(rId).emit("message-edited", payload);
      replyEdit({
        success: true,
        ...payload
      });

      for (const participant of getRoomAudience(rId)) {
        if (participant !== actor) {
          io.to(`user_${participant}`).emit("conversation-updated", {
            roomId: rId,
            message: msg
          });
        }
      }

      if (!roomDoc.isPrivate) {
        const user = db.users[actor] || {};
        logMessageToFile(
          rId,
          `[تعديل] ${user.displayName || actor} (${actor}) عدّل الرسالة ${msgId}: ${cleanText}`
        );
      }
    } catch (err) {
      console.error("خطأ تعديل الرسالة:", err.message);
      replyEdit({
        success: false,
        msgId,
        error: "تعذر تعديل الرسالة"
      });
    }
  });

  // WhatsApp-style one-reaction-per-user toggle.
  socket.on("send-reaction", ({ roomId: roomIdOrCode, msgId, emoji } = {}, ack) => {
    const replyReaction = (result) => {
      if (typeof ack === "function") {
        try { ack(result); } catch (_) {}
      }
    };

    try {
      const actor = socket.userId || socket.sessionUser;

      if (!actor || !msgId || typeof emoji !== "string") {
        replyReaction({
          success: false,
          msgId: msgId || null,
          error: "طلب التفاعل غير مكتمل أو انتهت جلسة الاتصال"
        });
        return;
      }

      const cleanEmoji = emoji.trim().slice(0, 24);
      if (!cleanEmoji) {
        replyReaction({ success: false, msgId, error: "التفاعل غير صالح" });
        return;
      }

      // Resolve the actual room that owns this message. The browser may use
      // a share code/private alias while Socket.IO is already attached to the
      // canonical room ID.
      const candidates = [];
      const addCandidate = (value) => {
        if (!value) return;
        const canonical = getCanonicalRoomId(value);
        for (const id of [canonical, value]) {
          if (id && !candidates.includes(id)) candidates.push(id);
        }
      };

      addCandidate(roomIdOrCode);
      addCandidate(socket.roomId);

      let targetRoomId = null;
      let msg = null;

      for (const candidate of candidates) {
        if (!canUserAccessRoom(candidate, actor)) continue;
        const found = (db.roomHistory[candidate] || []).find(m => m.msgId === msgId);
        if (found) {
          targetRoomId = candidate;
          msg = found;
          break;
        }
      }

      // Safe fallback for legacy/aliased room IDs: search only rooms this
      // authenticated user is allowed to access.
      if (!msg) {
        for (const [candidate, history] of Object.entries(db.roomHistory || {})) {
          if (!Array.isArray(history) || !canUserAccessRoom(candidate, actor)) continue;
          const found = history.find(m => m.msgId === msgId);
          if (found) {
            targetRoomId = candidate;
            msg = found;
            break;
          }
        }
      }

      if (!msg || !targetRoomId) {
        replyReaction({
          success: false,
          msgId,
          error: "الرسالة غير موجودة داخل المحادثة الحالية"
        });
        return;
      }

      if (!Array.isArray(msg.reactions)) msg.reactions = [];

      const previous = msg.reactions.find(r => r.userId === actor);
      msg.reactions = msg.reactions.filter(r => r.userId !== actor);

      // Same emoji again = remove. Different emoji = replace.
      if (!previous || previous.emoji !== cleanEmoji) {
        msg.reactions.push({
          emoji: cleanEmoji,
          userId: actor,
          username: actor,
          at: new Date().toISOString()
        });
      }

      saveDB(db);

      const result = {
        success: true,
        roomId: targetRoomId,
        requestedRoomId: roomIdOrCode || null,
        msgId,
        userId: actor,
        reactions: msg.reactions
      };

      io.to(targetRoomId).emit("receive-reaction", result);
      replyReaction(result);
    } catch (err) {
      console.error("خطأ إضافة التفاعل:", err.message);
      replyReaction({
        success: false,
        msgId: msgId || null,
        error: "تعذر إضافة التفاعل"
      });
    }
  });

  socket.on("delete-message", ({ roomId: roomIdOrCode, msgId } = {}) => {
    try {
      const actor = socket.userId;
      if (!actor || !roomIdOrCode || !msgId) return;
      const rId = getCanonicalRoomId(roomIdOrCode);
      if (!canUserAccessRoom(rId, actor)) return;

      const msg = (db.roomHistory[rId] || []).find(m => m.msgId === msgId);
      if (!msg) return;

      const mayDelete = msg.userId === actor || hasPermission(actor, "delete_messages");
      if (!mayDelete) {
        socket.emit("message-delete-result", { success: false, error: "لا تملك صلاحية حذف الرسالة" });
        return;
      }

      msg.deleted = true;
      msg.deletedAt = new Date().toISOString();
      msg.deletedBy = actor;
      msg.msg = "";
      delete msg.fileData;
      const roomDoc = db.rooms?.[rId];
      if (roomDoc && Array.isArray(roomDoc.pinnedMessageIds)) {
        roomDoc.pinnedMessageIds = roomDoc.pinnedMessageIds.filter(id => String(id) !== String(msgId));
      }
      saveDB(db);

      io.to(rId).emit("message-deleted", { roomId: rId, msgId, deletedBy: actor });
      if (roomDoc) {
        const pinPayload = { roomId: rId, pinnedMessageIds: normalizePinnedMessageIds(roomDoc), changedMessageId: msgId, pinned: false };
        io.to(rId).emit("pinned-messages-updated", pinPayload);
      }
      socket.emit("message-delete-result", { success: true, msgId });
    } catch (err) {
      socket.emit("message-delete-result", { success: false, error: "تعذر حذف الرسالة" });
    }
  });


  // =======================================================
  // Platform owner / staff permissions
  // =======================================================
  socket.on("admin-get-users", () => {
    const actor = socket.userId;
    if (!actor || !(actor === PLATFORM_OWNER_USERNAME || hasPermission(actor, "manage_moderators"))) {
      socket.emit("admin-users-list", { success: false, error: "لا تملك صلاحية إدارة المستخدمين" });
      return;
    }

    const users = Object.keys(db.users).map(username => {
      const user = db.users[username];
      const ban = checkPlatformBan(username);
      return {
        username,
        displayName: user.displayName || username,
        role: getPublicRole(username),
        badge: getPlatformBadge(username),
        staffApproved: isApprovedPlatformStaff(username),
        permissions: getUserPermissions(username),
        isOnline: activeOnlineUsers.has(username),
        isBanned: ban.banned,
        ban: ban.banned ? ban : null,
        registeredAt: user.registeredAt || null,
        lastSeen: user.lastSeen || null
      };
    });

    users.sort((a, b) => {
      const rank = { owner: 0, admin: 1, moderator: 2, user: 3 };
      return (rank[a.role] ?? 9) - (rank[b.role] ?? 9) || a.username.localeCompare(b.username);
    });

    socket.emit("admin-users-list", { success: true, users });
  });

  // Owner can create reserved short/special usernames for normal users or approved staff.
  socket.on("admin-create-staff-account", ({
    username,
    password,
    displayName,
    role = "moderator",
    permissions = []
  } = {}) => {
    const actor = socket.userId;
    if (actor !== PLATFORM_OWNER_USERNAME) {
      socket.emit("admin-action-result", { success: false, error: "فقط مالك المنصة يستطيع إنشاء حسابات مميزة" });
      return;
    }

    try {
      const uVal = validateUsername(username, { allowSpecial: true });
      if (!uVal.valid) {
        socket.emit("admin-action-result", { success: false, error: uVal.error });
        return;
      }
      const pVal = validatePassword(password);
      if (!pVal.valid) {
        socket.emit("admin-action-result", { success: false, error: pVal.error });
        return;
      }
      if (db.users[uVal.username]) {
        socket.emit("admin-action-result", { success: false, error: "اسم المستخدم موجود مسبقاً" });
        return;
      }

      const safeRole = ["user", "admin", "moderator"].includes(role) ? role : "user";
      db.users[uVal.username] = {
        username: uVal.username,
        password: hashPassword(password),
        role: safeRole,
        displayName: String(displayName || uVal.username).trim().slice(0, 60),
        staffApproved: safeRole !== "user",
        permissions: safeRole === "user" ? [] : normalizePermissions(permissions),
        createdByOwner: actor,
        registeredAt: new Date().toISOString(),
        status: "offline",
        lastSeen: null
      };
      saveDB(db);

      socket.emit("admin-action-result", {
        success: true,
        action: "create-staff-account",
        user: {
          username: uVal.username,
          displayName: db.users[uVal.username].displayName,
          role: safeRole,
          badge: getPlatformBadge(uVal.username),
          permissions: getUserPermissions(uVal.username)
        }
      });
    } catch (err) {
      socket.emit("admin-action-result", { success: false, error: "تعذر إنشاء الحساب المميز" });
    }
  });

  socket.on("admin-set-role", ({ targetUser, role } = {}) => {
    const actor = socket.userId;
    if (!actor || !(actor === PLATFORM_OWNER_USERNAME || hasPermission(actor, "manage_moderators"))) {
      socket.emit("admin-action-result", { success: false, error: "لا تملك صلاحية ترقية أو خفض المشرفين" });
      return;
    }

    if (!targetUser || !db.users[targetUser] || targetUser === PLATFORM_OWNER_USERNAME) {
      socket.emit("admin-action-result", { success: false, error: "لا يمكن تعديل هذا الحساب" });
      return;
    }

    const safeRole = ["user", "moderator", "admin"].includes(role) ? role : null;
    if (!safeRole) {
      socket.emit("admin-action-result", { success: false, error: "الدور غير صالح" });
      return;
    }

    const user = db.users[targetUser];
    user.role = safeRole;
    user.staffApproved = safeRole !== "user";
    if (safeRole === "user") user.permissions = [];
    else user.permissions = normalizePermissions(user.permissions);
    user.roleUpdatedBy = actor;
    user.roleUpdatedAt = new Date().toISOString();
    saveDB(db);

    io.to(`user_${targetUser}`).emit("my-role-updated", {
      role: getPublicRole(targetUser),
      badge: getPlatformBadge(targetUser),
      permissions: getUserPermissions(targetUser)
    });

    socket.emit("admin-action-result", {
      success: true,
      action: "set-role",
      targetUser,
      role: getPublicRole(targetUser),
      badge: getPlatformBadge(targetUser)
    });
  });

  // Per-moderator permissions are controlled only by the platform owner.
  socket.on("admin-set-permissions", ({ targetUser, permissions } = {}) => {
    const actor = socket.userId;
    if (actor !== PLATFORM_OWNER_USERNAME) {
      socket.emit("admin-action-result", { success: false, error: "فقط مالك المنصة يستطيع تعديل صلاحيات المشرفين" });
      return;
    }

    const user = db.users[targetUser];
    if (!user || targetUser === PLATFORM_OWNER_USERNAME || !isApprovedPlatformStaff(targetUser)) {
      socket.emit("admin-action-result", { success: false, error: "الحساب ليس مشرفاً معتمداً" });
      return;
    }

    user.permissions = normalizePermissions(permissions);
    user.permissionsUpdatedBy = actor;
    user.permissionsUpdatedAt = new Date().toISOString();
    saveDB(db);

    io.to(`user_${targetUser}`).emit("my-permissions-updated", {
      permissions: getUserPermissions(targetUser)
    });

    socket.emit("admin-action-result", {
      success: true,
      action: "set-permissions",
      targetUser,
      permissions: getUserPermissions(targetUser)
    });
  });

  socket.on("admin-get-permissions-catalog", () => {
    const actor = socket.userId;
    if (!actor || !isApprovedPlatformStaff(actor)) return;
    socket.emit("permissions-catalog", {
      permissions: [
        { id: "manage_platform_bans", label: "حظر المستخدمين على المنصة" },
        { id: "manage_moderators", label: "ترقية وخفض المشرفين" },
        { id: "manage_permissions", label: "إدارة الصلاحيات" },
        { id: "manage_reports", label: "مراجعة البلاغات" },
        { id: "manage_rooms", label: "إدارة الغرف" },
        { id: "manage_room_bans", label: "الحظر داخل الغرف" },
        { id: "delete_messages", label: "حذف الرسائل المخالفة" },
        { id: "manage_backgrounds", label: "إدارة الخلفيات" },
        { id: "manage_frames", label: "منح وسحب إطارات الحسابات" },
        { id: "create_special_staff_accounts", label: "إنشاء حسابات مشرفين مميزة" },
        { id: "send_platform_broadcast", label: "إرسال رسالة لجميع مستخدمي المنصة" },
        { id: "view_analytics", label: "عرض تحليلات المنصة" },
        { id: "view_system_metrics", label: "عرض مؤشرات السيرفر والذاكرة" },
        { id: "view_user_analytics", label: "عرض إحصائيات المستخدمين" },
        { id: "manage_referrals", label: "عرض وإدارة إحصائيات الإحالة" },
        { id: "manage_ai_safety", label: "مراجعة تنبيهات الأمان والسبام الذكية" }
      ]
    });
  });

  // 📣 Official platform-wide broadcast. The owner can grant this permission
  // to selected admins/moderators from the existing permissions editor.
  socket.on("admin-send-platform-broadcast", ({ message } = {}) => {
    const actor = socket.userId;
    if (!actor || !(actor === PLATFORM_OWNER_USERNAME || hasPermission(actor, "send_platform_broadcast"))) {
      socket.emit("platform-broadcast-result", { success: false, error: "لا تملك صلاحية إرسال رسائل المنصة" });
      return;
    }

    const cleanMessage = String(message || "").trim().slice(0, 4000);
    if (!cleanMessage) {
      socket.emit("platform-broadcast-result", { success: false, error: "اكتب الرسالة أولاً" });
      return;
    }

    try {
      const createdAt = new Date().toISOString();
      const displayTime = new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
      let delivered = 0;

      for (const username of Object.keys(db.users)) {
        if (!username || username === PLATFORM_OWNER_USERNAME) continue;
        const inbox = ensurePlatformInbox(username);
        if (!inbox) continue;

        const messageData = {
          roomId: inbox.roomId,
          type: "text",
          msg: cleanMessage,
          msgId: "platform-" + Date.now() + "-" + crypto.randomBytes(6).toString("hex"),
          userId: PLATFORM_OWNER_USERNAME,
          username: PLATFORM_OWNER_USERNAME,
          displayName: "TOMI",
          platformAccount: true,
          systemBroadcast: true,
          sentBy: actor,
          time: displayTime,
          createdAt,
          replyTo: null,
          reactions: [],
          deliveredTo: [{ userId: PLATFORM_OWNER_USERNAME, username: PLATFORM_OWNER_USERNAME, time: displayTime, at: createdAt }],
          readBy: [{ userId: PLATFORM_OWNER_USERNAME, username: PLATFORM_OWNER_USERNAME, time: displayTime, at: createdAt }],
          status: "sent"
        };

        appendRoomMessage(inbox.roomId, messageData);
        inbox.room.updatedAt = createdAt;
        delivered += 1;

        io.to(inbox.roomId).emit("broadcast-message", messageData);
        io.to(`user_${username}`).emit("conversation-updated", { roomId: inbox.roomId, message: messageData });
        io.to(`user_${username}`).emit("platform-broadcast", { roomId: inbox.roomId, message: messageData });

        sendPushToUser(username, inbox.roomId, {
          title: "TOMI • حساب المنصة",
          body: cleanMessage.slice(0, 180),
          url: `/room.html?roomId=${encodeURIComponent(inbox.roomId)}`,
          tag: `platform-${messageData.msgId}`,
          type: "message",
          requireInteraction: false
        }).catch(() => {});
      }

      saveDB(db);
      socket.emit("platform-broadcast-result", { success: true, delivered, message: "تم إرسال رسالة المنصة" });
    } catch (error) {
      console.error("platform broadcast:", error);
      socket.emit("platform-broadcast-result", { success: false, error: "تعذر إرسال رسالة المنصة" });
    }
  });

  // 🔑 Change password for the currently authenticated account.
  socket.on("change-password", ({ currentPassword, newPassword } = {}) => {
    const actor = socket.userId;
    const user = db.users[actor];
    if (!actor || !user) {
      socket.emit("change-password-result", { success: false, error: "يجب تسجيل الدخول أولاً" });
      return;
    }
    if (!verifyPassword(currentPassword || "", user.password)) {
      socket.emit("change-password-result", { success: false, error: "كلمة المرور الحالية غير صحيحة" });
      return;
    }
    const pVal = validatePassword(newPassword);
    if (!pVal.valid) {
      socket.emit("change-password-result", { success: false, error: pVal.error });
      return;
    }
    user.password = hashPassword(newPassword);
    user.passwordChangedAt = new Date().toISOString();
    saveDB(db);

    // Revoke other HTTP sessions for this user.
    for (const [token, session] of Object.entries(db.sessions || {})) {
      if (session.username === actor && token !== socket.sessionToken) delete db.sessions[token];
    }
    saveDB(db);

    socket.emit("change-password-result", { success: true, message: "تم تغيير كلمة المرور" });
  });

  // =======================================================
  // Platform-wide temporary/permanent bans
  // =======================================================
  socket.on("platform-ban-user", ({ targetUser, duration, reason, isPermanent } = {}) => {
    const actor = socket.userId;
    if (!actor || !(actor === PLATFORM_OWNER_USERNAME || hasPermission(actor, "manage_platform_bans"))) {
      socket.emit("platform-ban-result", { success: false, error: "لا تملك صلاحية حظر المستخدمين على المنصة" });
      return;
    }

    if (!targetUser || !db.users[targetUser] || targetUser === PLATFORM_OWNER_USERNAME) {
      socket.emit("platform-ban-result", { success: false, error: "لا يمكن حظر هذا الحساب" });
      return;
    }

    const minutes = Math.max(1, Number.parseInt(duration, 10) || 60);
    const expiresAt = isPermanent ? null : new Date(Date.now() + minutes * 60_000).toISOString();

    db.platformBans[targetUser] = {
      targetUser,
      bannedBy: actor,
      reason: String(reason || "").trim().slice(0, 500),
      isPermanent: !!isPermanent,
      expiresAt,
      createdAt: new Date().toISOString()
    };
    saveDB(db);

    io.to(`user_${targetUser}`).emit("platform-banned", {
      message: isPermanent ? "تم حظر حسابك دائماً من المنصة" : "تم حظر حسابك مؤقتاً من المنصة",
      ban: db.platformBans[targetUser]
    });

    const userSockets = activeOnlineUsers.get(targetUser);
    if (userSockets) {
      for (const socketId of [...userSockets]) {
        const targetSocket = io.sockets.sockets.get(socketId);
        if (targetSocket) {
          setTimeout(() => targetSocket.disconnect(true), 300);
        }
      }
    }

    socket.emit("platform-ban-result", { success: true, targetUser, ban: db.platformBans[targetUser] });
  });

  socket.on("platform-unban-user", ({ targetUser } = {}) => {
    const actor = socket.userId;
    if (!actor || !(actor === PLATFORM_OWNER_USERNAME || hasPermission(actor, "manage_platform_bans"))) {
      socket.emit("platform-ban-result", { success: false, error: "لا تملك صلاحية فك الحظر" });
      return;
    }
    if (db.platformBans[targetUser]) {
      delete db.platformBans[targetUser];
      saveDB(db);
    }
    socket.emit("platform-ban-result", { success: true, targetUser, unbanned: true });
  });

  socket.on("get-platform-bans", () => {
    const actor = socket.userId;
    if (!actor || !(actor === PLATFORM_OWNER_USERNAME || hasPermission(actor, "manage_platform_bans"))) return;

    const bans = Object.keys(db.platformBans)
      .map(username => ({ username, ...db.platformBans[username] }))
      .filter(entry => checkPlatformBan(entry.username).banned);
    socket.emit("platform-bans-list", bans);
  });

  // =======================================================
  // User reports with optional uploaded evidence image
  // =======================================================
  socket.on("submit-report", ({ targetUser, reason, details, attachmentFileId } = {}) => {
    try {
      const actor = socket.userId;
      if (!actor || !targetUser || actor === targetUser || !db.users[targetUser]) {
        socket.emit("report-submit-result", { success: false, error: "بيانات البلاغ غير صالحة" });
        return;
      }

      const cleanReason = String(reason || "").trim().slice(0, 120);
      const cleanDetails = String(details || "").trim().slice(0, 2000);
      if (!cleanReason) {
        socket.emit("report-submit-result", { success: false, error: "يرجى اختيار أو كتابة سبب البلاغ" });
        return;
      }

      let attachment = null;
      if (attachmentFileId) {
        const file = db.uploads[attachmentFileId];
        if (!file || file.uploader !== actor || file.context !== "report") {
          socket.emit("report-submit-result", { success: false, error: "مرفق البلاغ غير صالح" });
          return;
        }
        attachment = {
          fileId: file.fileId,
          fileName: file.originalName,
          mimeType: file.mimeType,
          fileType: file.fileType,
          url: `/api/files/${encodeURIComponent(file.fileId)}`
        };
      }

      const reportId = "rpt_" + crypto.randomBytes(10).toString("hex");
      const report = {
        reportId,
        reporter: actor,
        targetUser,
        reason: cleanReason,
        details: cleanDetails,
        attachment,
        status: "pending",
        createdAt: new Date().toISOString(),
        reviewedAt: null,
        reviewedBy: null,
        resolution: null
      };
      db.reports[reportId] = report;
      saveDB(db);

      emitToStaffWithPermission("manage_reports", "new-report", report);
      socket.emit("report-submit-result", { success: true, reportId, message: "تم إرسال البلاغ إلى الإدارة" });
    } catch (err) {
      socket.emit("report-submit-result", { success: false, error: "تعذر إرسال البلاغ" });
    }
  });

  socket.on("get-reports", ({ status = "pending" } = {}) => {
    const actor = socket.userId;
    if (!actor || !(actor === PLATFORM_OWNER_USERNAME || hasPermission(actor, "manage_reports"))) return;

    const reports = Object.values(db.reports)
      .filter(r => !status || status === "all" || r.status === status)
      .sort((a, b) => Date.parse(b.createdAt || 0) - Date.parse(a.createdAt || 0));
    socket.emit("reports-list", reports);
  });

  socket.on("review-report", ({ reportId, status, resolution } = {}) => {
    const actor = socket.userId;
    if (!actor || !(actor === PLATFORM_OWNER_USERNAME || hasPermission(actor, "manage_reports"))) {
      socket.emit("report-review-result", { success: false, error: "لا تملك صلاحية مراجعة البلاغات" });
      return;
    }

    const report = db.reports[reportId];
    if (!report) {
      socket.emit("report-review-result", { success: false, error: "البلاغ غير موجود" });
      return;
    }

    const safeStatus = ["reviewing", "actioned", "dismissed"].includes(status) ? status : "reviewing";
    report.status = safeStatus;
    report.resolution = String(resolution || "").trim().slice(0, 1000);
    report.reviewedBy = actor;
    report.reviewedAt = new Date().toISOString();
    saveDB(db);

    io.to(`user_${report.reporter}`).emit("report-status-updated", {
      reportId,
      status: report.status,
      resolution: report.resolution
    });
    socket.emit("report-review-result", { success: true, report });
  });

  // =======================================================
  // Shared chat backgrounds
  // Private: either participant can change it for both sides.
  // Public: only the room owner (or platform owner) can change it.
  // =======================================================
  socket.on("set-chat-background", ({ roomId: roomIdOrCode, fileId } = {}) => {
    try {
      const actor = socket.userId;
      if (!actor || !roomIdOrCode) return;

      const rId = getCanonicalRoomId(roomIdOrCode);
      const room = db.rooms[rId];
      if (!room || !canUserAccessRoom(rId, actor)) {
        socket.emit("background-update-result", { success: false, error: "لا تملك صلاحية الوصول لهذه المحادثة" });
        return;
      }

      const allowed = room.isPrivate
        ? canAccessPrivateRoom(rId, actor)
        : (room.owner === actor || actor === PLATFORM_OWNER_USERNAME);

      if (!allowed) {
        socket.emit("background-update-result", {
          success: false,
          error: room.isPrivate
            ? "لا تملك صلاحية تغيير الخلفية"
            : "فقط مالك الغرفة يستطيع تغيير خلفية المجموعة"
        });
        return;
      }

      if (!fileId) {
        room.background = null;
      } else {
        const file = db.uploads[fileId];
        if (
          !file ||
          file.uploader !== actor ||
          file.roomId !== rId ||
          !["image", "gif"].includes(file.fileType)
        ) {
          socket.emit("background-update-result", { success: false, error: "صورة الخلفية غير صالحة" });
          return;
        }

        room.background = {
          fileId,
          url: `/api/files/${encodeURIComponent(fileId)}`,
          updatedBy: actor,
          updatedAt: new Date().toISOString()
        };
      }

      room.updatedAt = new Date().toISOString();
      saveDB(db);

      io.to(rId).emit("chat-background-updated", {
        roomId: rId,
        background: room.background
      });
      for (const participant of getRoomAudience(rId)) {
        io.to(`user_${participant}`).emit("chat-background-updated", {
          roomId: rId,
          background: room.background
        });
      }
      socket.emit("background-update-result", { success: true, roomId: rId, background: room.background });
    } catch (err) {
      socket.emit("background-update-result", { success: false, error: "تعذر تغيير الخلفية" });
    }
  });

  socket.on("get-chat-background", ({ roomId: roomIdOrCode } = {}) => {
    const actor = socket.userId;
    if (!actor || !roomIdOrCode) return;
    const rId = getCanonicalRoomId(roomIdOrCode);
    if (!canUserAccessRoom(rId, actor)) return;
    socket.emit("chat-background", {
      roomId: rId,
      background: db.rooms[rId]?.background || null
    });
  });

  // Compatibility for room.html users popup.
  socket.on("query-room-users", ({ roomId: roomIdOrCode } = {}) => {
    const actor = socket.userId;
    if (!actor || !roomIdOrCode) return;
    const rId = getCanonicalRoomId(roomIdOrCode);
    if (!canUserAccessRoom(rId, actor)) return;
    broadcastRoomUsers(rId);
  });

  // =======================================================
  // WebRTC signaling - private chats only
  // =======================================================
  function validatePrivateCallTarget(roomIdOrCode, targetUser) {
    const actor = socket.userId;
    if (!actor || !roomIdOrCode) return null;

    const rId = getCanonicalRoomId(roomIdOrCode);
    const roomDoc = ensurePrivateRoomDocument(rId);
    if (!roomDoc || roomDoc.isPrivate !== true || !canAccessPrivateRoom(rId, actor)) return null;

    const members = Array.isArray(roomDoc.members) ? roomDoc.members : (getPrivateRoomParticipants(rId) || []);
    if (members.length !== 2) return null;

    const other = members.find(id => id !== actor);
    if (!other || (targetUser && targetUser !== other)) return null;
    return { rId, actor, targetUser: other, roomDoc };
  }

  function emitPrivateCallEvent(valid, eventName, payload = {}) {
    // Call signaling is delivered through the user's personal Socket.IO room.
    // Do not move the socket away from the conversation the user is currently browsing.
    io.to(`user_${valid.targetUser}`).emit(eventName, {
      roomId: valid.rId,
      fromUser: valid.actor,
      ...payload
    });
  }

  socket.on("call-offer", ({ roomId, targetUser, offer, callType = "audio", callId } = {}) => {
    const valid = validatePrivateCallTarget(roomId, targetUser);
    if (!valid || !offer) {
      socket.emit("call-error", { message: "المكالمات متاحة في المحادثات الخاصة فقط" });
      return;
    }
    if (!activeOnlineUsers.has(valid.targetUser)) {
      socket.emit("call-error", { message: "المستخدم الآخر غير متصل حالياً." });
      return;
    }

    const id = callId || ("call_" + crypto.randomBytes(10).toString("hex"));
    const normalizedCallType = callType === "video" ? "video" : "audio";
    emitPrivateCallEvent(valid, "incoming-call", {
      callId: id,
      fromDisplayName: db.users[valid.actor]?.displayName || valid.actor,
      callType: normalizedCallType,
      offer
    });
    sendPushToUser(valid.targetUser, valid.rId, {
      title: normalizedCallType === "video" ? "مكالمة فيديو واردة" : "مكالمة صوتية واردة",
      body: `${db.users[valid.actor]?.displayName || valid.actor} يتصل بك الآن`,
      url: `/room.html?roomId=${encodeURIComponent(valid.rId)}`,
      tag: `call-${id}`,
      type: "call",
      requireInteraction: true
    }).catch(() => {});
    socket.emit("call-offer-sent", { callId: id, roomId: valid.rId, targetUser: valid.targetUser });
  });

  socket.on("call-answer", ({ roomId, targetUser, answer, callId } = {}) => {
    const valid = validatePrivateCallTarget(roomId, targetUser);
    if (!valid || !answer || !callId) return;
    emitPrivateCallEvent(valid, "call-answered", { callId, answer });
  });

  socket.on("call-ice-candidate", ({ roomId, targetUser, candidate, callId } = {}) => {
    const valid = validatePrivateCallTarget(roomId, targetUser);
    if (!valid || !candidate || !callId) return;
    emitPrivateCallEvent(valid, "call-ice-candidate", { callId, candidate });
  });

  socket.on("call-reject", ({ roomId, targetUser, callId, reason } = {}) => {
    const valid = validatePrivateCallTarget(roomId, targetUser);
    if (!valid || !callId) return;
    emitPrivateCallEvent(valid, "call-rejected", {
      callId,
      reason: String(reason || "rejected").slice(0, 100)
    });
  });

  socket.on("call-end", ({ roomId, targetUser, callId } = {}) => {
    const valid = validatePrivateCallTarget(roomId, targetUser);
    if (!valid || !callId) return;
    emitPrivateCallEvent(valid, "call-ended", { callId });
  });

  socket.on("call-upgrade-request", ({ roomId, targetUser, callId } = {}) => {
    const valid = validatePrivateCallTarget(roomId, targetUser);
    if (!valid || !callId) return;
    emitPrivateCallEvent(valid, "call-upgrade-requested", { callId });
    sendPushToUser(valid.targetUser, valid.rId, {
      title: "طلب تحويل المكالمة إلى فيديو",
      body: `${db.users[valid.actor]?.displayName || valid.actor} يريد تشغيل الفيديو`,
      url: `/room.html?roomId=${encodeURIComponent(valid.rId)}`,
      tag: `upgrade-${callId}`,
      type: "call"
    }).catch(() => {});
  });

  socket.on("call-upgrade-response", ({ roomId, targetUser, callId, accepted, reason } = {}) => {
    const valid = validatePrivateCallTarget(roomId, targetUser);
    if (!valid || !callId) return;
    emitPrivateCallEvent(valid, "call-upgrade-result", {
      callId,
      accepted: accepted === true,
      reason: String(reason || "").slice(0, 100)
    });
  });

  socket.on("call-upgrade-abort", ({ roomId, targetUser, callId } = {}) => {
    const valid = validatePrivateCallTarget(roomId, targetUser);
    if (!valid || !callId) return;
    emitPrivateCallEvent(valid, "call-upgrade-aborted", { callId });
  });

  socket.on("call-renegotiate-offer", ({ roomId, targetUser, callId, offer, callType } = {}) => {
    const valid = validatePrivateCallTarget(roomId, targetUser);
    if (!valid || !callId || !offer) return;
    emitPrivateCallEvent(valid, "call-renegotiate-offer", {
      callId,
      offer,
      callType: callType === "video" ? "video" : "audio"
    });
  });

  socket.on("call-renegotiate-answer", ({ roomId, targetUser, callId, answer } = {}) => {
    const valid = validatePrivateCallTarget(roomId, targetUser);
    if (!valid || !callId || !answer) return;
    emitPrivateCallEvent(valid, "call-renegotiate-answered", { callId, answer });
  });

  socket.on("call-media-state", ({ roomId, targetUser, callId, microphoneMuted, cameraEnabled } = {}) => {
    const valid = validatePrivateCallTarget(roomId, targetUser);
    if (!valid || !callId) return;
    emitPrivateCallEvent(valid, "call-media-state", {
      callId,
      microphoneMuted: microphoneMuted === true,
      cameraEnabled: cameraEnabled !== false
    });
  });

  socket.on("call-screen-share-state", ({ roomId, targetUser, callId, active, aspectRatio } = {}) => {
    const valid = validatePrivateCallTarget(roomId, targetUser);
    if (!valid || !callId) return;
    emitPrivateCallEvent(valid, "call-screen-share-state", {
      callId,
      active: active === true,
      aspectRatio: Number(aspectRatio || 0) || null
    });
  });

  socket.on("leave-room-view", () => {
    const previousRoomId = socket.roomId;
    if (previousRoomId) {
      socket.leave(previousRoomId);
      socket.roomId = null;
      setImmediate(() => broadcastRoomUsers(previousRoomId));
    }
  });

  socket.on("clear-room-history", async (roomIdOrCode) => {
    const actor = socket.userId;
    const rId = getCanonicalRoomId(roomIdOrCode);
    const roomDoc = db.rooms[rId];

    if (!actor || !rId || !roomDoc) return;

    if (roomDoc.isPrivate) {
      if (!canAccessPrivateRoom(rId, actor)) return;
    } else {
      const mayClear =
        roomDoc.owner === actor ||
        actor === PLATFORM_OWNER_USERNAME ||
        hasPermission(actor, "manage_rooms");
      if (!mayClear) {
        socket.emit("clear-history-result", { success: false, error: "فقط مالك الغرفة أو الإدارة يستطيع مسح سجل الغرفة العامة" });
        return;
      }
      await waitForTelegramQueue(rId);
    }

    if (db.roomHistory[rId]) {
      removeRoomHistoryAndFiles(rId);
      db.roomHistory[rId] = [];
      roomDoc.updatedAt = new Date().toISOString();
      saveDB(db);
    }

    if (!roomDoc.isPrivate) {
      logMessageToFile(rId, `=== قام أحد المستخدمين بمسح الشاشة ===`);
    }

    io.to(rId).emit("chat-cleared", { roomId: rId });
    socket.emit("clear-history-result", { success: true, roomId: rId });
  });


  // ---------------- Voice rooms ----------------
  socket.on("voice-rooms-get", () => {
    if (!socket.userId) return;
    socket.emit("voice-rooms-list", listVoiceRooms());
  });

  socket.on("voice-room-create", ({ name, code } = {}, ack = () => {}) => {
    try {
      const actor = socket.userId;
      if (!actor) return ack({ success: false, error: "يجب تسجيل الدخول" });
      const roomId = "voice_" + Date.now().toString(36) + "_" + crypto.randomBytes(3).toString("hex");
      const cleanName = String(name || "غرفة صوتية").trim().slice(0, 60) || "غرفة صوتية";
      const cleanCode = String(code || "").trim().slice(0, 40);
      db.voiceRooms[roomId] = {
        id: roomId,
        name: cleanName,
        owner: actor,
        moderators: [],
        codeHash: cleanCode ? hashVoiceRoomCode(cleanCode) : "",
        imageFileId: null,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
        emptySince: new Date().toISOString()
      };
      saveDB(db);
      emitVoiceRoomsList();
      ack({ success: true, room: voiceRoomPublic(roomId) });
    } catch (err) {
      ack({ success: false, error: "تعذر إنشاء الغرفة الصوتية" });
    }
  });

  socket.on("voice-room-invite", ({ roomId, targetUser } = {}, ack = () => {}) => {
    try {
      const actor = socket.userId;
      const room = db.voiceRooms?.[roomId];
      const runtime = voiceRoomRuntime.get(roomId);
      const target = String(targetUser || "").trim();
      if (!actor || !room || !target || target === actor || !db.users?.[target]) {
        return ack({ success: false, error: "بيانات الدعوة غير صحيحة" });
      }
      if (!runtime?.members?.has(actor)) {
        return ack({ success: false, error: "ادخل الغرفة أولاً حتى ترسل دعوة" });
      }
      if (!areFriends(actor, target)) {
        return ack({ success: false, error: "يمكن دعوة الأصدقاء المضافين فقط" });
      }

      cleanVoiceRoomInvites();
      const token = crypto.randomBytes(24).toString("hex");
      const invite = {
        id: "vinv_" + crypto.randomBytes(14).toString("hex"),
        roomId,
        invitedBy: actor,
        targetUser: target,
        token,
        tokenHash: hashVoiceInviteToken(token),
        createdAt: new Date().toISOString(),
        expiresAt: new Date(Date.now() + VOICE_ROOM_INVITE_TTL_MS).toISOString()
      };
      if (!Array.isArray(db.voiceRoomInvites[target])) db.voiceRoomInvites[target] = [];
      // Replace a previous invite from the same room so the recipient sees the
      // newest token and the persistent state stays bounded.
      db.voiceRoomInvites[target] = db.voiceRoomInvites[target]
        .filter(item => item?.roomId !== roomId)
        .concat(invite)
        .slice(-20);
      saveDB(db);

      const payload = voiceInvitePayload(invite, room);
      io.to(`user_${target}`).emit("voice-room-invitation", payload);
      sendPushToUser(target, roomId, {
        title: "دعوة إلى غرفة صوتية",
        body: `${db.users[actor]?.displayName || actor} دعاك إلى ${room.name || "غرفة صوتية"}`,
        url: payload.url,
        tag: `voice-invite-${invite.id}`,
        type: "voice-invite",
        requireInteraction: true
      }).catch(() => {});
      ack({ success: true, inviteId: invite.id });
    } catch (err) {
      console.error("Voice room invite failed:", err?.message || err);
      ack({ success: false, error: "تعذر إرسال الدعوة" });
    }
  });

  socket.on("voice-room-join", ({ roomId, code, inviteId, inviteToken } = {}, ack = () => {}) => {
    try {
      const actor = socket.userId;
      const room = db.voiceRooms?.[roomId];
      if (!actor || !room) return ack({ success: false, error: "الغرفة غير موجودة" });
      const ban = getActiveVoiceRoomBan(roomId, actor);
      if (ban) {
        let error = "أنت محظور من هذه الغرفة الصوتية";
        if (ban.expiresAt) {
          const remainingMs = Math.max(0, Date.parse(ban.expiresAt) - Date.now());
          const remainingMinutes = Math.max(1, Math.ceil(remainingMs / 60000));
          error = `تم منعك مؤقتاً من دخول هذه الغرفة. المتبقي تقريباً ${remainingMinutes} دقيقة`;
        }
        return ack({ success: false, error, ban: { temporary: Boolean(ban.expiresAt), expiresAt: ban.expiresAt || null } });
      }
      const invited = inviteId && inviteToken
        ? consumeVoiceRoomInvite(actor, roomId, String(inviteId), String(inviteToken))
        : false;
      if (room.codeHash && actor !== room.owner && actor !== PLATFORM_OWNER_USERNAME && !invited) {
        if (hashVoiceRoomCode(String(code || "")) !== room.codeHash) {
          return ack({ success: false, error: "رمز الغرفة غير صحيح", codeRequired: true });
        }
      }

      if (socket.voiceRoomId && socket.voiceRoomId !== roomId) cleanupVoiceRoomSocket(socket);
      socket.join(`voice_${roomId}`);
      socket.voiceRoomId = roomId;
      const runtime = getVoiceRoomRuntime(roomId);
      if (!runtime.members.has(actor)) runtime.members.set(actor, new Set());
      runtime.members.get(actor).add(socket.id);
      markVoiceRoomPresence(roomId, true);

      const peers = Array.from(runtime.members.keys()).filter(u => u !== actor);
      ack({ success: true, room: voiceRoomPublic(roomId), peers });
      io.to(`voice_${roomId}`).emit("voice-room-peer-joined", { roomId, username: actor });
      emitVoiceRoomState(roomId);
    } catch (err) {
      ack({ success: false, error: "تعذر دخول الغرفة الصوتية" });
    }
  });

  socket.on("voice-room-leave", ({ roomId } = {}) => {
    if (roomId && socket.voiceRoomId === roomId) cleanupVoiceRoomSocket(socket);
  });

  socket.on("voice-room-take-seat", ({ roomId, seat } = {}, ack = () => {}) => {
    const actor = socket.userId;
    const room = db.voiceRooms?.[roomId];
    if (!actor || !room || socket.voiceRoomId !== roomId) return ack({ success: false, error: "ادخل الغرفة أولاً" });
    const runtime = getVoiceRoomRuntime(roomId);
    const requested = Number(seat || 0);
    let seatNo = requested >= 1 && requested <= VOICE_ROOM_SEAT_COUNT ? requested : null;
    if (!seatNo) {
      for (let i = 1; i <= VOICE_ROOM_SEAT_COUNT; i++) {
        if (!runtime.seats.has(i) && !runtime.lockedSeats.has(i)) { seatNo = i; break; }
      }
    }
    if (!seatNo || runtime.lockedSeats.has(seatNo) || runtime.seats.has(seatNo)) {
      return ack({ success: false, error: "لا يوجد مقعد متاح" });
    }
    for (const [n, u] of runtime.seats.entries()) if (u === actor) runtime.seats.delete(n);
    runtime.seats.set(seatNo, actor);
    runtime.mutedUsers.delete(actor);
    emitVoiceRoomState(roomId);
    io.to(`voice_${roomId}`).emit("voice-room-speaker-changed", { roomId, username: actor, seated: true });
    ack({ success: true, seat: seatNo });
  });

  socket.on("voice-room-leave-seat", ({ roomId } = {}, ack = () => {}) => {
    const actor = socket.userId;
    const runtime = voiceRoomRuntime.get(roomId);
    if (!actor || !runtime) return ack({ success: false });
    for (const [n, u] of runtime.seats.entries()) if (u === actor) runtime.seats.delete(n);
    runtime.mutedUsers.delete(actor);
    emitVoiceRoomState(roomId);
    io.to(`voice_${roomId}`).emit("voice-room-speaker-changed", { roomId, username: actor, seated: false });
    ack({ success: true });
  });

  socket.on("voice-room-seat-control", ({ roomId, seat, action } = {}, ack = () => {}) => {
    const actor = socket.userId;
    const room = db.voiceRooms?.[roomId];
    const runtime = voiceRoomRuntime.get(roomId);
    if (!actor || !room || !runtime || !isVoiceRoomModerator(room, actor)) {
      return ack({ success: false, error: "ليس لديك صلاحية" });
    }
    const seatNo = Number(seat);
    if (!(seatNo >= 1 && seatNo <= VOICE_ROOM_SEAT_COUNT)) return ack({ success: false, error: "مقعد غير صالح" });
    const occupant = runtime.seats.get(seatNo);

    if (action === "lock") {
      if (occupant && !mayActOnVoiceRoomTarget(room, actor, occupant)) return ack({ success: false, error: "لا يمكن تنفيذ هذا الإجراء" });
      runtime.lockedSeats.add(seatNo);
      if (occupant) {
        runtime.seats.delete(seatNo);
        runtime.mutedUsers.delete(occupant);
        io.to(`user_${occupant}`).emit("voice-room-seat-removed", { roomId, reason: "تم إغلاق المقعد" });
      }
    } else if (action === "unlock") {
      runtime.lockedSeats.delete(seatNo);
    } else if (action === "mute") {
      if (!occupant || !mayActOnVoiceRoomTarget(room, actor, occupant)) return ack({ success: false, error: "لا يمكن كتم هذا المستخدم" });
      runtime.mutedUsers.add(occupant);
      io.to(`user_${occupant}`).emit("voice-room-force-mute", { roomId, muted: true });
    } else if (action === "unmute") {
      if (!occupant || !mayActOnVoiceRoomTarget(room, actor, occupant)) return ack({ success: false, error: "لا يمكن إلغاء كتم هذا المستخدم" });
      runtime.mutedUsers.delete(occupant);
      io.to(`user_${occupant}`).emit("voice-room-force-mute", { roomId, muted: false });
    } else if (action === "remove") {
      if (!occupant || !mayActOnVoiceRoomTarget(room, actor, occupant)) return ack({ success: false, error: "لا يمكن إزالة هذا المستخدم" });
      runtime.seats.delete(seatNo);
      runtime.mutedUsers.delete(occupant);
      io.to(`user_${occupant}`).emit("voice-room-seat-removed", { roomId, reason: "تمت إزالتك من المقعد" });
    }
    emitVoiceRoomState(roomId);
    ack({ success: true });
  });

  socket.on("voice-room-kick", ({ roomId, targetUser, ban = false, tempMinutes = 0 } = {}, ack = () => {}) => {
    const actor = socket.userId;
    const room = db.voiceRooms?.[roomId];
    if (!room || !mayActOnVoiceRoomTarget(room, actor, targetUser)) {
      return ack({ success: false, error: "لا تملك صلاحية على هذا المستخدم" });
    }

    const requestedTempMinutes = Math.floor(Number(tempMinutes || 0));
    const temporaryKick = Number.isFinite(requestedTempMinutes) && requestedTempMinutes > 0;

    // The room owner (or platform owner) chooses temporary exclusion duration.
    if (temporaryKick && actor !== room.owner && actor !== PLATFORM_OWNER_USERNAME) {
      return ack({ success: false, error: "فقط مالك الغرفة يستطيع تحديد مدة الطرد المؤقت" });
    }

    let banRecord = null;
    if (ban || temporaryKick) {
      if (!db.voiceRoomBans[roomId]) db.voiceRoomBans[roomId] = {};
      const now = new Date();
      const safeMinutes = temporaryKick ? Math.min(10080, Math.max(1, requestedTempMinutes)) : 0;
      banRecord = {
        banned: true,
        by: actor,
        at: now.toISOString(),
        temporary: temporaryKick,
        expiresAt: temporaryKick ? new Date(now.getTime() + safeMinutes * 60000).toISOString() : null,
        durationMinutes: temporaryKick ? safeMinutes : null
      };
      db.voiceRoomBans[roomId][targetUser] = banRecord;
      saveDB(db);
    }

    const runtime = voiceRoomRuntime.get(roomId);
    if (runtime) {
      runtime.members.delete(targetUser);
      for (const [n, u] of runtime.seats.entries()) if (u === targetUser) runtime.seats.delete(n);
      runtime.mutedUsers.delete(targetUser);
    }

    io.to(`user_${targetUser}`).emit("voice-room-kicked", {
      roomId,
      banned: Boolean(ban),
      temporary: temporaryKick,
      expiresAt: banRecord?.expiresAt || null,
      durationMinutes: banRecord?.durationMinutes || null
    });

    for (const sid of io.sockets.adapter.rooms.get(`user_${targetUser}`) || []) {
      const s = io.sockets.sockets.get(sid);
      if (s?.voiceRoomId === roomId) {
        s.leave(`voice_${roomId}`);
        s.voiceRoomId = null;
      }
    }
    emitVoiceRoomState(roomId);
    ack({ success: true, temporary: temporaryKick, expiresAt: banRecord?.expiresAt || null });
  });

  socket.on("voice-room-role", ({ roomId, targetUser, action } = {}, ack = () => {}) => {
    const actor = socket.userId;
    const room = db.voiceRooms?.[roomId];
    if (!room || !actor) return ack({ success: false, error: "الغرفة غير موجودة" });
    // Only room owner or platform owner can promote/demote room moderators.
    if (actor !== room.owner && actor !== PLATFORM_OWNER_USERNAME) {
      return ack({ success: false, error: "فقط مالك الغرفة يستطيع إدارة المشرفين" });
    }
    if (targetUser === room.owner) return ack({ success: false, error: "لا يمكن تغيير رتبة مالك الغرفة" });
    room.moderators = Array.isArray(room.moderators) ? room.moderators : [];
    if (action === "promote") {
      if (!room.moderators.includes(targetUser)) room.moderators.push(targetUser);
    } else if (action === "demote") {
      room.moderators = room.moderators.filter(u => u !== targetUser);
    } else {
      return ack({ success: false, error: "إجراء غير معروف" });
    }
    room.updatedAt = new Date().toISOString();
    saveDB(db);
    emitVoiceRoomState(roomId);
    ack({ success: true });
  });

  socket.on("voice-room-update", ({ roomId, name, code, clearCode, imageFileId } = {}, ack = () => {}) => {
    const actor = socket.userId;
    const room = db.voiceRooms?.[roomId];
    if (!room || !isVoiceRoomModerator(room, actor)) return ack({ success: false, error: "ليس لديك صلاحية" });
    if (name != null) room.name = String(name || "").trim().slice(0, 60) || room.name;
    if (clearCode) room.codeHash = "";
    else if (code != null && String(code).trim()) room.codeHash = hashVoiceRoomCode(String(code).trim().slice(0, 40));
    if (imageFileId) {
      const file = db.uploads?.[imageFileId];
      if (!file || file.uploader !== actor || file.context !== "voice-room-image") {
        return ack({ success: false, error: "صورة الغرفة غير صالحة" });
      }
      room.imageFileId = imageFileId;
    }
    room.updatedAt = new Date().toISOString();
    saveDB(db);
    emitVoiceRoomState(roomId);
    ack({ success: true, room: voiceRoomPublic(roomId) });
  });

  socket.on("voice-room-delete", ({ roomId } = {}, ack = () => {}) => {
    const actor = socket.userId;
    const room = db.voiceRooms?.[roomId];
    if (!room || (actor !== room.owner && !canManagePlatformRooms(actor))) {
      return ack({ success: false, error: "فقط مالك الغرفة أو إدارة المنصة تستطيع إغلاقها" });
    }
    delete db.voiceRooms[roomId];
    delete db.voiceRoomBans[roomId];
    for (const [username, invites] of Object.entries(db.voiceRoomInvites || {})) {
      const remaining = (Array.isArray(invites) ? invites : []).filter(invite => invite?.roomId !== roomId);
      if (remaining.length) db.voiceRoomInvites[username] = remaining;
      else delete db.voiceRoomInvites[username];
    }
    saveDB(db);
    io.to(`voice_${roomId}`).emit("voice-room-deleted", { roomId });
    voiceRoomRuntime.delete(roomId);
    emitVoiceRoomsList();
    ack({ success: true });
  });

  // Voice-room WebRTC signaling (mesh). Signals are limited to members of the same voice room.
  const forwardVoiceSignal = (eventOut, payload = {}) => {
    const actor = socket.userId;
    const roomId = payload.roomId;
    const targetUser = payload.targetUser;
    const runtime = voiceRoomRuntime.get(roomId);
    if (!actor || !targetUser || !runtime?.members.has(actor) || !runtime.members.has(targetUser)) return;
    io.to(`user_${targetUser}`).emit(eventOut, { ...payload, fromUser: actor });
  };
  socket.on("voice-room-webrtc-offer", data => forwardVoiceSignal("voice-room-webrtc-offer", data));
  socket.on("voice-room-webrtc-answer", data => forwardVoiceSignal("voice-room-webrtc-answer", data));
  socket.on("voice-room-webrtc-ice", data => forwardVoiceSignal("voice-room-webrtc-ice", data));

  socket.on("disconnect", () => {
    try { cleanupVoiceRoomSocket(socket); } catch (_) {}
    analyticsService?.socketDisconnected(socket.id);
    if (socket.username && activeOnlineUsers.has(socket.username)) {
      const userSockets = activeOnlineUsers.get(socket.username);
      userSockets.delete(socket.id);
      if (userSockets.size === 0) {
        activeOnlineUsers.delete(socket.username);
        if (db.users[socket.username]) {
          db.users[socket.username].lastSeen = new Date().toISOString();
          db.users[socket.username].status = "offline";
          saveDB(db);
        }
      }
      broadcastOnlineUsers();
    }

    if (socket.roomId) {
      broadcastRoomUsers(socket.roomId);
    }
  });
});

// =========================================================
// 6. Helper Functions
// =========================================================

function emitRoomMembers(roomId) {
  const roomDoc = db.rooms[roomId];
  if (!roomDoc || roomDoc.isPrivate) return;

  const members = (Array.isArray(roomDoc.members) ? roomDoc.members : []).map(memberId => {
    const user = db.users[memberId] || {};
    return {
      userId: memberId,
      username: memberId,
      displayName: user.displayName || memberId,
      role: getPublicRole(memberId),
      badge: roomDoc.owner === memberId
        ? "owner"
        : (roomDoc.moderators?.includes(memberId) ? "moderator" : getPublicRole(memberId)),
      platformBadge: getPlatformBadge(memberId),
      isOnline: activeOnlineUsers.has(memberId),
      isOwner: roomDoc.owner === memberId,
      isModerator: roomDoc.moderators?.includes(memberId) || false,
      avatar: user.avatar || "",
      frame: getActiveFrame(memberId)
    };
  });

  io.to(roomId).emit("room-members-list", {
    roomId,
    owner: roomDoc.owner,
    maxUsers: normalizeMaxUsers(roomDoc.maxUsers, 24),
    members
  });
}

function broadcastRoomUsers(roomId) {
  const room = io.sockets.adapter.rooms.get(roomId);
  const users = [];
  const seen = new Set();

  const roomDoc = db.rooms[roomId];

  if (room) {
    for (const socketId of room) {
      const clientSocket = io.sockets.sockets.get(socketId);
      if (clientSocket && clientSocket.userId && !seen.has(clientSocket.userId)) {
        seen.add(clientSocket.userId);
        const user = db.users[clientSocket.userId] || {};
        let badge = null;
        if (roomDoc) {
          if (roomDoc.owner === clientSocket.userId) badge = "owner";
          else if (roomDoc.moderators && roomDoc.moderators.includes(clientSocket.userId)) badge = "moderator";
          else {
            const platformRole = getPublicRole(clientSocket.userId);
            if (platformRole !== "user") badge = platformRole;
          }
        }
        users.push({
          userId: clientSocket.userId,
          username: clientSocket.userId,
          displayName: user.displayName || clientSocket.userId,
          role: getPublicRole(clientSocket.userId),
          badge,
          platformBadge: getPlatformBadge(clientSocket.userId),
          permissions: getUserPermissions(clientSocket.userId),
          avatar: user.avatar || "",
          frame: getActiveFrame(clientSocket.userId)
        });
      }
    }
  }
  io.to(roomId).emit("room-users-list", users);
  io.to(roomId).emit("query-room-users-response", { roomId, users });

  if (roomDoc && !roomDoc.isPrivate) {
    emitRoomMembers(roomId);
  }
}

function broadcastOnlineUsers() {
  const onlineList = Array.from(activeOnlineUsers.keys());
  io.emit("online_users_list", onlineList);
}

// =========================================================
// 7. تشغيل الخادم
// =========================================================
const PORT = process.env.PORT || 9000;
// Allow large mobile uploads on slow networks while still bounding hung requests.
server.requestTimeout = Math.max(5 * 60 * 1000, Number(process.env.HTTP_REQUEST_TIMEOUT_MS || 15 * 60 * 1000) || 15 * 60 * 1000);
server.headersTimeout = 65_000;
server.keepAliveTimeout = 60_000;

function cleanupEmptyVoiceRooms(now = Date.now()) {
  let changed = false;
  const deletedRoomIds = [];
  for (const [roomId, room] of Object.entries(db.voiceRooms || {})) {
    const runtime = voiceRoomRuntime.get(roomId);
    if (runtime?.members?.size) {
      if (room.emptySince) {
        delete room.emptySince;
        room.lastActiveAt = new Date(now).toISOString();
        changed = true;
      }
      continue;
    }

    if (!room.emptySince) {
      room.emptySince = new Date(now).toISOString();
      changed = true;
      continue;
    }

    const emptySince = Date.parse(room.emptySince);
    if (Number.isFinite(emptySince) && now - emptySince >= VOICE_ROOM_EMPTY_TTL_MS) {
      delete db.voiceRooms[roomId];
      delete db.voiceRoomBans[roomId];
      for (const [username, invites] of Object.entries(db.voiceRoomInvites || {})) {
        const remaining = (Array.isArray(invites) ? invites : []).filter(invite => invite?.roomId !== roomId);
        if (remaining.length) db.voiceRoomInvites[username] = remaining;
        else delete db.voiceRoomInvites[username];
      }
      voiceRoomRuntime.delete(roomId);
      deletedRoomIds.push(roomId);
      changed = true;
    }
  }

  for (const roomId of deletedRoomIds) {
    io.to(`voice_${roomId}`).emit("voice-room-deleted", { roomId, reason: "empty-timeout" });
  }
  if (deletedRoomIds.length) emitVoiceRoomsList();
  return changed;
}

// Bounded runtime cleanup + memory guard for small Render instances.
function cleanupExpiredRuntimeState({ aggressive = false } = {}) {
  const now = Date.now();
  let changed = false;

  for (const [sessionId, session] of uploadSessions.entries()) {
    if (!session || (session.status !== "completed" && Number(session.expiresAt || 0) <= now)) {
      if (session && session.status !== "uploaded") queuePartialResumableUploadDelete(session);
      safeUnlink(session?.tempPath);
      uploadSessions.delete(sessionId);
    } else if (session.status === "completed" && Number(session.expiresAt || 0) <= now) {
      uploadSessions.delete(sessionId);
    }
  }

  if (cleanupEmptyVoiceRooms(now)) changed = true;
  if (cleanVoiceRoomInvites(now)) changed = true;

  for (const [token, session] of Object.entries(db.sessions || {})) {
    if (!session || Number(session.expiresAt || 0) <= now) {
      delete db.sessions[token];
      changed = true;
    }
  }

  for (const [key, value] of cloudflareTurnCredentialCache.entries()) {
    if (!value || Number(value.expiresAt || 0) <= now) cloudflareTurnCredentialCache.delete(key);
  }
  if (cloudflareTurnCredentialCache.size > 800) {
    for (const key of cloudflareTurnCredentialCache.keys()) {
      cloudflareTurnCredentialCache.delete(key);
      if (cloudflareTurnCredentialCache.size <= 500) break;
    }
  }

  for (const [roomId, retryAfter] of telegramTopicRetryAfter.entries()) {
    if (!Number.isFinite(Number(retryAfter)) || Number(retryAfter) <= now) {
      telegramTopicRetryAfter.delete(roomId);
    }
  }

  for (const [username, sockets] of activeOnlineUsers.entries()) {
    if (!sockets || sockets.size === 0) activeOnlineUsers.delete(username);
  }
  for (const [username, count] of activeUploadsByUser.entries()) {
    if (!Number.isFinite(count) || count <= 0) activeUploadsByUser.delete(username);
  }

  for (const roomId of voiceRoomRuntime.keys()) {
    if (!db.voiceRooms?.[roomId]) voiceRoomRuntime.delete(roomId);
  }

  // Remove expired platform and public-room bans to keep persistent state bounded.
  for (const [username, ban] of Object.entries(db.platformBans || {})) {
    if (!ban || ban.isPermanent) continue;
    const expires = ban.expiresAt ? Date.parse(ban.expiresAt) : NaN;
    if (Number.isFinite(expires) && expires <= now) {
      delete db.platformBans[username];
      changed = true;
    }
  }
  for (const [roomId, bans] of Object.entries(db.roomBans || {})) {
    if (!bans || typeof bans !== "object") continue;
    for (const [username, ban] of Object.entries(bans)) {
      if (!ban || ban.isPermanent) continue;
      const expires = ban.expiresAt ? Date.parse(ban.expiresAt) : NaN;
      if (Number.isFinite(expires) && expires <= now) {
        delete bans[username];
        changed = true;
      }
    }
    if (Object.keys(bans).length === 0) {
      delete db.roomBans[roomId];
      changed = true;
    }
  }

  // Remove expired temporary voice-room bans without touching permanent bans.
  for (const [roomId, bans] of Object.entries(db.voiceRoomBans || {})) {
    if (!bans || typeof bans !== "object") continue;
    for (const [username, ban] of Object.entries(bans)) {
      const expires = ban?.expiresAt ? Date.parse(ban.expiresAt) : NaN;
      if (Number.isFinite(expires) && expires <= now) {
        delete bans[username];
        changed = true;
      }
    }
    if (Object.keys(bans).length === 0) {
      delete db.voiceRoomBans[roomId];
      changed = true;
    }
  }

  // Expire only the disposable local acceleration copy. The canonical GridFS
  // object remains untouched and continues to serve the message after cache TTL.
  for (const record of Object.values(db.uploads || {})) {
    if (!record?.cacheStoredName) continue;
    if (["checking", "processing"].includes(record.playbackStatus)) continue;
    const expires = Date.parse(record.cacheExpiresAt || "");
    if (Number.isFinite(expires) && expires <= now) {
      fs.promises.unlink(path.join(UPLOAD_DIR, record.cacheStoredName)).catch(() => {});
      record.cacheStoredName = null;
      record.cacheExpiresAt = null;
      changed = true;
    }
  }

  // The compatibility copy has its own short-lived local acceleration cache;
  // its durable GridFS copy is never removed here.
  for (const record of Object.values(db.uploads || {})) {
    if (!record?.playbackCacheStoredName || ["checking", "processing"].includes(record.playbackStatus)) continue;
    const expires = Date.parse(record.playbackCacheExpiresAt || "");
    if (Number.isFinite(expires) && expires <= now) {
      fs.promises.unlink(path.join(UPLOAD_DIR, record.playbackCacheStoredName)).catch(() => {});
      record.playbackCacheStoredName = null;
      record.playbackCacheExpiresAt = null;
      changed = true;
    }
  }

  // Uploaded-to-chat files that were never published are temporary. Clean them
  // after a grace period so abandoned mobile uploads cannot grow state forever.
  for (const [fileId, record] of Object.entries(db.uploads || {})) {
    if (!record || record.context !== "chat" || record.messageId) continue;
    const created = Date.parse(record.createdAt || "");
    if (Number.isFinite(created) && now - created >= UNSENT_CHAT_UPLOAD_TTL_MS && !isChatUploadReferenced(fileId)) {
      delete db.uploads[fileId];
      queuePhysicalUploadDelete(record);
      changed = true;
    }
  }

  // Remove stale temporary local files left by aborted uploads.
  fs.promises.readdir(UPLOAD_DIR, { withFileTypes: true }).then(async entries => {
    for (const entry of entries) {
      if (!entry.isFile()) continue;
      const full = path.join(UPLOAD_DIR, entry.name);
      try {
        const st = await fs.promises.stat(full);
        if (Date.now() - st.mtimeMs >= UNSENT_CHAT_UPLOAD_TTL_MS) {
          const known = Object.values(db.uploads || {}).some(r =>
            r?.storedName === entry.name || r?.cacheStoredName === entry.name
              || r?.playbackStoredName === entry.name || r?.playbackCacheStoredName === entry.name
          );
          if (!known) await fs.promises.unlink(full).catch(() => {});
        }
      } catch (_) {}
    }
  }).catch(() => {});

  if (aggressive) trimAllRoomHistories();
  if (changed) scheduleMongoSave();
  return changed;
}

async function requestMemorySafetyRestart(rssMB) {
  if (memoryRestartRequested) return;
  memoryRestartRequested = true;
  memoryGuardStatus = "restart-pending";
  console.error(`🛟 Memory guard: RSS ${rssMB}MB stayed above critical limit. Requesting a controlled restart before Render OOM-kills the process.`);
  // Stop accepting new HTTP connections; existing clients will reconnect through
  // Socket.IO after Render restarts the process. Avoid serializing the whole DB at
  // this point because doing so under memory pressure can itself cause an OOM.
  try { server.close(() => process.exit(1)); } catch (_) {}
  setTimeout(() => process.exit(1), 2500).unref();
}

const memoryGuardTimer = setInterval(() => {
  const m = process.memoryUsage();
  const rssMB = Math.round(m.rss / 1024 / 1024);
  const heapMB = Math.round(m.heapUsed / 1024 / 1024);
  const heapTotalMB = Math.round(m.heapTotal / 1024 / 1024);
  const externalMB = Math.round(m.external / 1024 / 1024);
  const arrayBuffersMB = Math.round((m.arrayBuffers || 0) / 1024 / 1024);
  const confirmedMemoryPressure = heapMB >= MEMORY_RESTART_HEAP_MB
    || externalMB >= MEMORY_RESTART_EXTERNAL_MB
    || arrayBuffersMB >= MEMORY_RESTART_EXTERNAL_MB;

  if (rssMB >= MEMORY_CRITICAL_MB) {
    memoryGuardStatus = "critical";
    memoryCriticalStrikes += 1;
    cleanupExpiredRuntimeState({ aggressive: true });
    if (global.gc) {
      try { global.gc(); } catch (_) {}
    }
    console.warn(`🔴 Memory critical: RSS ${rssMB}MB, heap ${heapMB}MB, heapTotal ${heapTotalMB}MB, external ${externalMB}MB, arrayBuffers ${arrayBuffersMB}MB (${memoryCriticalStrikes}/${MEMORY_CRITICAL_STRIKES})`);
    if (memoryCriticalStrikes >= MEMORY_CRITICAL_STRIKES && MEMORY_GUARD_RESTART && confirmedMemoryPressure) {
      requestMemorySafetyRestart(rssMB).catch(() => {});
    } else if (memoryCriticalStrikes >= MEMORY_CRITICAL_STRIKES && !memoryRestartSkipLogged) {
      memoryRestartSkipLogged = true;
      console.warn(`🛟 Memory guard: controlled restart skipped; restartEnabled=${MEMORY_GUARD_RESTART}, confirmedPressure=${confirmedMemoryPressure}. RSS alone is not treated as fatal.`);
    }
    return;
  }

  memoryCriticalStrikes = 0;
  memoryRestartSkipLogged = false;
  if (rssMB >= MEMORY_CLEANUP_MB) {
    memoryGuardStatus = "cleanup";
    cleanupExpiredRuntimeState({ aggressive: true });
    if (global.gc) {
      try { global.gc(); } catch (_) {}
    }
    console.warn(`🧹 Memory cleanup: RSS ${rssMB}MB, heap ${heapMB}MB, external ${externalMB}MB, arrayBuffers ${arrayBuffersMB}MB`);
  } else if (rssMB >= MEMORY_WARN_MB) {
    memoryGuardStatus = "warning";
    cleanupExpiredRuntimeState();
    console.warn(`⚠️ Memory warning: RSS ${rssMB}MB, heap ${heapMB}MB, external ${externalMB}MB, arrayBuffers ${arrayBuffersMB}MB`);
  } else {
    memoryGuardStatus = "normal";
  }
}, MEMORY_GUARD_INTERVAL_MS);
memoryGuardTimer.unref?.();

const transientCleanupTimer = setInterval(() => {
  cleanupExpiredRuntimeState();
}, 60 * 1000);
transientCleanupTimer.unref?.();

async function startServer() {
  await initCloudDatabase();
  db = normalizeDatabaseState(db);
  // Apply the same legacy Android MP4 repair in local mode as in MongoDB mode;
  // otherwise an old audio/mp4 record could still bypass desktop conversion.
  repairLegacyMediaMetadata();
  ensurePlatformOwner();
  analyticsService?.ensureAllReferralCodes();
  await analyticsService?.configureMongo?.();
  analyticsService?.start?.();
  consolidatePlatformInboxes();
  trimAllRoomHistories();
  cleanupExpiredRuntimeState({ aggressive: true });
  // If a previous instance restarted while a video was being copied from the
  // fast local source to GridFS, continue that copy without making the user
  // upload the video again.
  resumePendingVideoCloudUploads();
  // Continue any compatibility conversion that was interrupted by a deploy or
  // restart. The queue is intentionally single-file to protect small Render
  // instances from concurrent ffmpeg processes.
  resumePendingVideoCompatibilityJobs();
  // Keep notification subscriptions across restarts. When VAPID variables are
  // not supplied, initializeWebPush creates one key pair and persists it in
  // the existing database so Render restarts do not invalidate every phone.
  initializeWebPush();
  saveDB(db);

  server.listen(PORT, () => {
    console.log(`🚀 Server Started on port ${PORT}`);
    console.log(mongoReady ? "☁️ Database: MongoDB Atlas" : `📁 Database: local JSON (${DB_PATH})`);
    if (objectStorage.isConfigured()) {
      console.log(`☁️ Files: Cloudflare R2 (direct browser upload, ${objectStorage.getPartSize()} byte parts)`);
    } else if (gridFsBucket) {
      console.log("☁️ Files: MongoDB GridFS (legacy fallback; configure R2 for direct media transfer)");
    } else {
      console.log(`⚠️ Files: local disk (${UPLOAD_DIR}); configure Cloudflare R2 before production media use`);
    }
  });
}

async function shutdown(signal) {
  console.log(`\n${signal}: saving Chatify state...`);
  try { await analyticsService?.stop?.(); } catch (err) { console.error(err.message); }
  try { await flushCloudDatabase(); } catch (err) { console.error(err.message); }
  try { await mongoose.disconnect(); } catch (_) {}
  server.close(() => process.exit(0));
  setTimeout(() => process.exit(0), 5000).unref();
}

process.once("SIGTERM", () => shutdown("SIGTERM"));
process.once("SIGINT", () => shutdown("SIGINT"));

startServer().catch(err => {
  console.error("Server startup failed:", err);
  process.exit(1);
});
